window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-obstetricia-obs-4"]={"block":"medcurso:medcurso-obstetricia-obs-4","label":"Medcurso · OBS 4","count":406,"questions":[{"id":"medcurso-obstetricia-obs-4-343755","number":"343755","sourceNumber":"343755","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 25 anos, primigesta, com idade gestacional de 13 semanas e 5 dias,\ncomparece à sua segunda consulta de pré-natal, para mostrar seus exames. Entre eles está o de\nglicemia em jejum, com o valor de 97 mg/dl. Em relação ao quadro clínico desta paciente, a\nconduta mais adequada é:","options":{"A":"A glicemia está normal e a paciente deve seguir a consulta no pré-natal de risco habitual.","B":"Caso essa glicemia se confirme em segundo exame, a paciente deve ser encaminhada ao\npré-natal de alto risco e iniciar insulina como primeira conduta.","C":"A glicemia está normal e a paciente deve realizar o exame de teste oral de tolerância à glicose\ncom 24 a 28 semanas.","D":"Caso a glicemia seja confirmada com segundo exame, a paciente tem o diagnóstico de diabetes\ngestacional e deverá iniciar dieta e controle glicêmico simplificado."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-345458","number":"345458","sourceNumber":"345458","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Durante o pré-natal de uma gestante, o exame de urina tipo I constatou leucocitúria.\nNesse caso, como o médico deve proceder?","options":{"A":"Comunicar imediatamente à maternidade.","B":"Encaminhar a gestante ao pré-natal de alto risco.","C":"Realizar urinocultura para confirmar a presença de ITU e, na indisponibilidade do exame, tratar\nempiricamente.","D":"Repetir o exame em 15 dias."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-345480","number":"345480","sourceNumber":"345480","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 18 semanas de gravidez, assintomática, apresentou bacteriúria no\nexame de urina tipo I. Realizou duas\nuroculturas com intervalo de uma semana que revelou >10?\nUFC. O diagnóstico e conduta são:","options":{"A":"Bacteriúria assintomática e antibioticoterapia.","B":"Cistite intersticial e antibioticoterapia.","C":"Uretrite e antibioticoterapia.","D":"Uretrotrigonite e aumentar a ingesta líquida."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-345489","number":"345489","sourceNumber":"345489","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Analise o contexto a seguir: É uma das complicações mais comuns e mais sérias\ndurante a gestação, ocorrendo em 1 a 2% das\ngestantes. Clinicamente, a sintomatologia é\nevidente, com febre alta, calafrios e dor na loja renal, além da referência pregressa de sintomas de\ninfecção urinária baixa. A presença de náuseas e vômitos, além de taquicardia, dispneia e\nhipotensão, podem sugerir evolução para quadro séptico. O tratamento inicial deve ser hospitalar. A\ninformação acima refere-se a:","options":{"A":"Bacteriúria assintomática.","B":"Cistite.","C":"Pielonefrite aguda.","D":"Nenhuma das alternativas."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-343845","number":"343845","sourceNumber":"343845","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente com quadro de trombose venosa de repetição, trombocitopenia e abortos\nespontâneos no primeiro trimestre de gravidez, deve ser testado para qual anticorpo abaixo?","options":{"A":"Anti Histona.","B":"Anti Cardiolipina.","C":"Anti U1-RNP.","D":"Anti Mi-2."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-291784","number":"291784","sourceNumber":"291784","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Casal jovem, ambos com de 33 anos, vem ao consultório porque desejam ter um filho.\nEla é tercigesta, nulípara. Há três anos\nvem tentando engravidar sem sucesso. Paciente referiu que\nantes ela conseguia engravidar, porém sofreu 3 abortamentos precoces, sendo o último há 4 anos.\nEm todas as gestações os embriões paravam de apresentar batimento cardíaco fetal antes de 9\nsemanas de idade gestacional. Todos os exames hormonais realizados não evidenciaram\nalterações. Cariótipo da paciente e do esposo: normais. Exame de imagem na época do último\nabortamento não evidenciou malformações uterinas. Realizou curetagem uterina no primeiro e no\nterceiro abortamentos. Ciclo menstrual costuma ser regular, porém há 5 meses não menstrua.\n\nSabendo que um dos diagnósticos diferenciais para a causa do abortamento de repetição é a\nSíndrome do Anticorpo Antifosfolípideo (SAAF), é correto afirmar:","options":{"A":"Para confirmar o diagnóstico para SAAF, nessa paciente ela teria que ter histórico de um evento\ntrombótico.","B":"O diagnóstico de SAAF é baseado em um critério clínico e em dois critérios laboratoriais.","C":"O diagnóstico de, SAAF é baseado, além do critério clínico, em um critério laboratorial; exemplo:\nanti-coagulante lúpico presente em duas ou mais ocasiões com intervalo de 12 semanas.","D":"O diagnóstico de SAAF é baseado, além do critério clínico, em um critério laboratorial; exemplo:\nanti-coagulante lúpico presente em exame isolado."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-291786","number":"291786","sourceNumber":"291786","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Casal jovem, ambos com de 33 anos, vem ao consultório porque desejam ter um filho.\nEla é tercigesta, nulípara. Há três anos\nvem tentando engravidar sem sucesso. Paciente referiu que\nantes ela conseguia engravidar, porém sofreu 3 abortamentos precoces, sendo o último há 4 anos.\nEm todas as gestações os embriões paravam de apresentar batimento cardíaco fetal antes de 9\nsemanas de idade gestacional. Todos os exames hormonais realizados não evidenciaram\nalterações. Cariótipo da paciente e do esposo: normais. Exame de imagem na época do último\nabortamento não evidenciou malformações uterinas. Realizou curetagem uterina no primeiro e no\nterceiro abortamentos. Ciclo menstrual costuma ser regular, porém há 5 meses não menstrua.\n\nCaso seja confirmada a Síndrome do Anticorpo Antifosfolipídeo (SAAF), nessa paciente, indique a\nmelhor conduta a ser adotada.","options":{"A":"Fazer uso contínuo de heparina de baixo pelo molecular, antes e durante a gestação.","B":"Fazer uso de ácido acetilsalicílico, continuamente, antes e durante a gestação.","C":"Fazer uso de heparina e ácido acetilsalicílico, continuamente, a partir do diagnóstico precoce da\ngestação.","D":"Fazer uso de varfarina, continuamente, a partir do diagnóstico precoce da gestação."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-291787","number":"291787","sourceNumber":"291787","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 36 semanas, sem comorbidades, secundigesta com parto normal anterior,\nvem à maternidade para atendimento pois há\n1 dia começou a apresentar turvação visual e edema\nem membros inferiores. Ao exame físico, além do edema, PA: 150x100mmHg, FC: 82bpm,\nmucosas normocoradas. Ausculta cardíaca e pulmonar sem alterações. Exame obstétrico: altura\nuterina: 33cm, apresentação cefálica, batimentos cardíacos fetais: 148bpm, dinâmica uterina\nausente, tônus uterino normal. Ao toque vaginal: colo fechado, grosso, posterior. Com base no\nquadro clínico descrito e nos seus conhecimentos sobre hipertensão, é correto afirmar:","options":{"A":"Paciente que apresenta hipertensão crônica fora da gestação e que está bem controlada com\nmedicações não apresenta risco aumentado de evoluir para pré-eclâmpsia quando gestante.","B":"O cálcio é uma medicação utilizada na prevenção de pré-eclâmpsia em pacientes previamente\nhipertensas.","C":"Quando a paciente evolui com hipertensão gestacional o uso de Captopril é uma opção.","D":"A mola hidatiforme é uma patologia associada à pré-eclâmpsia de início tardio."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-291788","number":"291788","sourceNumber":"291788","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 36 semanas, sem comorbidades, secundigesta com parto normal anterior,\nvem à maternidade para atendimento pois há\n1 dia começou a apresentar turvação visual e edema\nem membros inferiores. Ao exame físico, além do edema, PA: 150x100mmHg, FC: 82bpm,\nmucosas normocoradas. Ausculta cardíaca e pulmonar sem alterações. Exame obstétrico: altura\nuterina: 33cm, apresentação cefálica, batimentos cardíacos fetais: 148bpm, dinâmica uterina\nausente, tônus uterino normal. Ao toque vaginal: colo fechado, grosso, posterior. Indique a\nprincipal hipótese diagnóstica para o caso.","options":{"A":"Hipertensão gestacional.","B":"Pré-eclâmpsia.","C":"Pré-eclâmpsia superajuntada.","D":"Síndrome HELLP."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-291789","number":"291789","sourceNumber":"291789","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 36 semanas, sem comorbidades, secundigesta com parto normal anterior,\nvem à maternidade para atendimento pois há\n1 dia começou a apresentar turvação visual e edema\nem membros inferiores. Ao exame físico, além do edema, PA: 150x100mmHg, FC: 82bpm,\nmucosas normocoradas. Ausculta cardíaca e pulmonar sem alterações. Exame obstétrico: altura\nuterina: 33cm, apresentação cefálica, batimentos cardíacos fetais: 148bpm, dinâmica uterina\nausente, tônus uterino normal. Ao toque vaginal: colo fechado, grosso, posterior. Em relação ao\nquadro clínico descrito, a melhor conduta para o caso é:","options":{"A":"Exame de fundo de olho e prescrever o anti- hipertensivo.","B":"Internação, sulfato de magnésio, coleta de exames laboratoriais e corticoide seguido de\ninterrupção da gestação em 48 horas.","C":"Internação, cardiotocografia, ultrassonografia obstétrica, controle adequado da pressão, sulfato\nde magnésio, exames laboratoriais. Avaliar via de\nparto conforme ultrassonografia, vitalidade fetal e\nestabilidade materna.","D":"Internação, cardiotocografia, ultrassonografia obstétrica, controle adequado da pressão, sulfato\nde magnésio, exames laboratoriais. Interrupção\nda gestação por cesariana."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-283335","number":"283335","sourceNumber":"283335","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Os anticorpos antifosfolípides podem estar envolvidos em quadros de:","options":{"A":"Incompetência istmocervical.","B":"Abortamento.","C":"Amniorrexe prematura.","D":"Placenta prévia."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-251878","number":"251878","sourceNumber":"251878","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, com 23 anos de idade, 27 semanas de gestação, relata que, há dois dias,\napresenta dor na região lombar à direita. Relata, ainda, que há um dia vem se sentindo muito mal,\ncom calafrios e náuseas. Hoje, pela manhã, apresentou febre de 38,5ºC, tendo feito uso de\nantitérmico. Ao exame físico: estado geral regular; descorada +/4+; levemente desidratada; afebril,\neupneica; frequência cardíaca de 104 bpm; Pressão arterial = 110 x 70 mmHg. Relatou dor intensa\nà punho percussão na região lombar direita. Ao exame obstétrico: altura uterina de 28 cm, 156\nbatimentos cardíacos fetais por minuto; movimentos fetais presentes, ausência de contrações\nuterinas. Qual a conduta a ser tomada?","options":{"A":"Solicitar exame sumário de urina e retorno em 24 horas para resultado de exames.","B":"Hemograma, urocultura e antibioticoterapia.","C":"Internação hospitalar, hidratação e antibioticoterapia, após resultado da cultura de urina.","D":"Internação hospitalar, hemograma, eletrólitos, cultura de urina e antibioticoterapia endovenosa."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-251879","number":"251879","sourceNumber":"251879","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente primigesta, com 17 anos de idade e no terceiro trimestre de gestação, é\ntrazida à Emergência Obstétrica devido a história de cefaleia intensa, seguida de epigastralgia há\n40 minutos. Familiares informam que a paciente referiu turvação visual e que, após esses sintomas,\napresenta-se meio \"aérea\", motivo pelo qual a trouxeram ao hospital. A gestante apresenta-se\nconsciente, ainda referindo turvação visual e epigastralgia. Refere melhora da cefaleia. Ao exame\napresenta: palidez cutâneo-mucosa (+++/4+), pressão arterial = 180 x 120 mmHg, edema em\nmembros inferiores (++++/4+), batimentos cardiofetais (feto 1 = 120 bpm; feto 2 = 105 bpm). Com\nbase nos dados clínico-obstétricos expostos, o diagnóstico e a conduta imediata a ser tomada são:","options":{"A":"Eclâmpsia; resolução da gestação.","B":"Síndrome HELLP; administração de dexametasona.","C":"Eminência de eclâmpsia; administração de sulfato de magnésio.","D":"Pré-eclâmpsia grave; administração de hidralazina endovenosa."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-251886","number":"251886","sourceNumber":"251886","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher com 34 anos de idade, gestante de 28 semanas, iniciou quadro febril há cinco\ndias associado a dor no hemitórax esquerdo à\nrespiração profunda. Há dois dias passou a\napresentar tosse produtiva com expectoração amarelada. Procurou Unidade de Pronto\nAtendimento. Ao exame: bom estado geral; sinais vitais: Pulso = 100 bpm; Pressão arterial = 120 x\n80 mmHg; Frequência respiratória = 23 irpm. Temperatura axilar = 39ºC; Ausculta pulmonar:\ncrepitações, broncofonia e aumento do frêmito tóraco-vocal na base do pulmão esquerdo. O\nleucograma apresenta 15.800 leucócitos/mm³, com predomínio de polimorfonucleares neutrófilos.\nQual a conduta a ser tomada, com relação a exames de imagem e tratamento antimicrobiano?","options":{"A":"Solicitar radiografia de tórax com proteção abdominal e iniciar tratamento com amoxicilina oral.","B":"Solicitar ultrassonografia de tórax e iniciar tratamento com quinolona respiratória oral.","C":"Solicitar tomografia computadorizada do tórax e iniciar tratamento com aminoglicosídeo\ninjetável.","D":"Solicitar radiografia de tórax com proteção abdominal e iniciar claritromicina oral."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-251887","number":"251887","sourceNumber":"251887","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 40 anos de idade, Gesta 4 para 2 aborto 1, assintomática, na 16ª\nsemana de gestação, é atendida no\nambulatório de pré-natal de alto risco, encaminhada da\nUnidade Básica de Saúde (UBS), por ser portadora de hipertensão crônica e ter apresentado\npressão arterial = 150 x 100 mmHg na última consulta na UBS. A gestante relata ter feito uso de\ncaptopril (75 mg/dia) desde seu último parto, há três anos, e ter suspendido o uso da medicação\napós descobrir que estava grávida. Aferida novamente a pressão arterial, obteve-se resultado de\n160 x 105 mmHg. Nesse caso, a conduta terapêutica indicada é:","options":{"A":"Iniciar furosemida.","B":"Iniciar alfametildopa.","C":"Reintroduzir captopril, com dose maior.","D":"Reintroduzir captopril e associar hidroclorotiazida."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-251906","number":"251906","sourceNumber":"251906","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 20 anos, primigesta, com história familiar de diabetes em parentes de\nprimeiro grau, traz na terceira consulta de pré-natal, com 26 semanas de gestação, um exame de\nglicemia de jejum de 90 mg/dl. Assinale a alternativa que apresenta a conduta que o médico de\nfamília e comunidade deve adotar.","options":{"A":"Repetir a glicemia de jejum em outro dia.","B":"Solicitar o teste de tolerância à glicose com 75 g.","C":"Estabelecer o diagnóstico de diabetes gestacional e encaminhar para o pré-natal de alto risco.","D":"Manter uma conduta expectante e avaliar sinais e sintomas nas próximas consultas."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-247205","number":"247205","sourceNumber":"247205","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 19 anos de idade, com 33 semanas de gestação, é admitida no\npronto-socorro com queixa de cefalia e desconforto respiratório importante. Ao exame físico:\n\ndescorada ++/4, edema generalizado atingindo face, PA = 180x120 mmHg, pulso rítmico com 134\nbpm, ausculta torácica com bulhas rítmicas sem sopros e pulmões com roncos difusos e estertores\nem base. No exame obstétrico: altura uterina 30 cm, feto único cefálico e batimentos rítmicos de\n155 bpm. A melhor alternativa terapêutica é","options":{"A":"Betabloqueador e sulfato de magnésio.","B":"Nitroprussiato de sódio e hidralazina.","C":"Hidralazina e betabloqueador.","D":"Nitroprussiato de sódio e sulfato de magnésio.","E":"Nifedipina e sulfato de magnésio."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-217731","number":"217731","sourceNumber":"217731","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A lesão renal mais associada à eclâmpsia é:","options":{"A":"Edema glorumelar endotelial.","B":"Necrose cortical.","C":"Necrose tubular aguda.","D":"Nenhuma das anteriores está correta."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-217733","number":"217733","sourceNumber":"217733","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Pacientes em pré-eclâmpsia grave apresentam diminuição:","options":{"A":"Na resposta às aminas vasopressoras.","B":"No volume plasmático.","C":"No sódio corporal total.","D":"Todas as anteriores estão corretas."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-183148","number":"183148","sourceNumber":"183148","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 14 anos admitida na maternidade com 37 semanas na vigência de crise\nconvulsiva do tipo tônico-clônica generalizada, PA=160x100 mmHg, proteinúria de fita 2+, sem\nhisttória prévia de crises convulsivas, pressão arterial no primeiro trimestre =100x60 mmHg,\nelevando-se nas últimas semanas. Recebe o suporte básico de vida e sulfato de magnésiona dose\nde ataque por via intravenosa.É reavaliada ao término da dose de ataque e observa-se\nPA=150x100 mmHg, Glasgow de 15, dinâmica uterina de duas contrações em 10 minutos com\nFCF=144 bpm. Ao toque, colo apagado 90%, dilatado 3 cm, apresentação cefálica em plano 0 de\nDeLee, bolsa íntegra. Solicitam-se exames laboratorias. Nesse íterim, paciente apresentada nova\ncrise convulsiva tônico-clônica generalizada. A conduta, além de manter vias aéreas pérvicas e\nadministrar oxigênio deve ser:","options":{"A":"Administrar hidantal IV.","B":"Administrar hidralazina IV.","C":"Repetir metade da dose de ataque do sulfato de magnésio IV.","D":"Administrar sulfato de magnésio IM.","E":"Anestesia geral e cesariana de emergência."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182626","number":"182626","sourceNumber":"182626","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, com 23 anos de idade, 27 semanas de gestação, relata que, há dois dias,\napresenta dor na região lombar à direita e há 1 dia vem se sentindo muito mal, com calafrios e\nnaúseas. Hoje, pela manhã, apresentou febre de 38,5 ºC, tendo feito uso de antitérmico. Ao exame\nfísico: estado geral regular, descorada +/4+, levemente desidratada, afebril, eupneica, frequência\ncardíaca de 104 bpm, Pressão arterial = 110 x 70 mmHg. Relatou dor intensa à punhopercussão na\nregião lombar direita. Ao exame obstétrico: altura uterina de 28 cm, 156 batimentos\ncardiofetais/minuto, movimentos fetais presentes, ausência de contrações uterinas. Qual a conduta\na ser tomada?","options":{"A":"Solicitar exame sumário de urina e retorno em 24 horas para resultado de exames.","B":"Hemograma, urocultura e antibioticoterapia.","C":"Internação hospitalar, hidratação e antibioticoterapia, após resultado da cultura de urina.","D":"Internação hospitalar, hemograma, eletrólitos, cultura de urina e antibioticoterapia endovenosa."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182652","number":"182652","sourceNumber":"182652","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente primigesta, negra, 17 anos de idade e no terceiro trimestre de gestação,\né trazida à Emergência Obstétrica devido à\nhistória de cefaleia intensa, seguida de epigastralgia há\n40 minutos. Familiares informam que a paciente referiu turvação visual e que, após esses sintomas,\napresenta-se meio \"aérea\", motivo pelo qual a trouxeram ao hospital. A gestante apresenta-se\nconsciente, ainda referindo, turvação visual e epigastralgia. Refere melhora de cefaleia. Ao exame\napresenta: palidez cutâneo-mucosa (+++/4+), pressão arterial = 180 x 120 mmHg, edema em\nmembros inferiores (++++/4+), batimentos cardiofetais (feto 1 = 120 bpm; feto 2 = 105 bpm). Com\nbase nos dados clínico-obstétricos expostos, o diagnóstico e a conduta imediata a ser tomada são:","options":{"A":"Eclâmpsia; resolução da gestação.","B":"Síndrome HELLP; administração de dexametasona.","C":"Eminência de eclâmpsia; administração de sulfato de magnésio.","D":"Pré-ecâmpsia grave; administração de hidralazina endovenosa."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182679","number":"182679","sourceNumber":"182679","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Secundigesta, com 18 semanas de idade gestacional, comparece à segunda consulta\nde pré-natal em Unidade Básica de Saúde. Traz\nresultado de exame de urocultura com mais de\n100 mil unidades formadoras de colônias bacterianas por mL. Nega queixas urinárias e febre. Ao\nexame físico: bom estado geral, corada, hidratada, eupneica, pressão arterial = 120 x 80 mmHg.\nExame obstétrico: altura uterina de 17 cm, batimentos cardiacos fetais presentes, rítmicos, 136\nbpm. A conduta indicada é:","options":{"A":"Iniciar tratamento profilático com cefalosporina diariamente até o parto.","B":"Iniciar antibioticoterapia e repetir urocultura sete dias após o término do tratamento.","C":"Repetição da urocultura em duas semanas, pois o resultado sugere contaminação da amostra.","D":"Solicitar ultrassonografia das vias urinárias e realizar uroculturas bimensais para monitoramento\ndo quadro."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182702","number":"182702","sourceNumber":"182702","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 40 anos de idade, Gesta 4 Para 2 Aborto 1, assintomática, na 16ª\nsemana de gestação, é atendida no\nambulatório de pré-natal de alto risco, encaminhada da\nUnidade Básica de Saúde (UBS), por ser portadora de hipertensão crônica e ter apresentado\npressão arterial = 150 x 100 mmHg na última consulta na UBS. A gestante relata ter feito uso de\ncaptopril (75 mg/dia) desde seu último parto, há três anos, e ter suspendido o uso da medicação\napós descobrir que estava grávida. Aferida novamente a pressão arterial, obteve-se resultado de\n160 x 150 mmHg. Nesse caso, a conduta terapêutica indicada é:","options":{"A":"Iniciar furosemida.","B":"Iniciar alfametildopa.","C":"Reintroduzir captopril, com dose maior.","D":"Reintroduzir captopril e associar hidroclorotiazida."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182706","number":"182706","sourceNumber":"182706","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Quanto ao desenvolvimento de diabetes gestacional em paciente primigesta, com 29\nanos de idade, estatura de 1,50 m, peso\npré-gravídico de 70 Kg, peso atual de 75Kg na 24ª\nsemana de gestação e glicemia em jejum de 90mg/dl, pode-se afirmar que há:","options":{"A":"Ausência de risco pela idade inferior a 30 anos de gestante.","B":"Existência de risco pelo ganho excessivo de peso na gestação.","C":"Ausência de risco pela normalidade da glicemia de jejum da gestante.","D":"Existência de risco pelo IMC pré-gravídico superior a 27Kg/m²."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-159040","number":"159040","sourceNumber":"159040","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 16 anos, primigesta, com idade gestacional de 40 semanas, chega à\nmaternidade assintomática, referindo que foi orientada a procurar atendimento especializado\nporque o bebê está \"passando da hora\". Realizou o pré-natal de baixo risco na unidade básica de\nsaúde, onde não apresentou alterações nos exames laboratoriais. Ao exame físico: PA 150 X 100\nmmHg após duas aferições, altura uterina 36 cm, BCF: 146 bpm. Toque vaginal: colo grosso,\nposterior, pérvio 2 cm, apresentação cefálica e bolsa íntegra. A conduta mais adequada é:","options":{"A":"Realizar uma cesariana.","B":"Orientar a paciente a retornar em 48 horas para realizar uma cardiotocografia.","C":"Solicitar exames de rotina para DHEG, avaliar o bem-estar fetal e dar alta à paciente caso os\nexames estejam normais.","D":"Iniciar a indução do trabalho de parto, após comprovada avaliação do bem-estar fetal e exames\nlaboratoriais de rotina para DHEG."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-159087","number":"159087","sourceNumber":"159087","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Considerando a infecção do trato urinário na gestação, é CORRETO afirmar que:","options":{"A":"A paciente deve ser internada sempre, mesmo nos casos de cistite, pois as repercussões para a\ngravidez, como: trabalho de parto prematuro e baixo peso trazem negativas para o feto.","B":"Os casos de bacteriúria assintomática não devem ser tratados com antibióticos, mas a paciente\ndeve ser orientada a repetir a urocultura.","C":"Os aminoglicosídeos devem ser utilizados como primeira escolha no tratamento da pielonefrite.","D":"Nos casos de recidiva ou reinfecção, indica-se o tratamento supressivo, por via oral (ampicilina,\nnitrofurantoína ou ácido nalidíxico) uma vez ao dia, até duas semanas após o parto."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-159129","number":"159129","sourceNumber":"159129","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Advogada de 26 anos, refere que há 4 meses iniciou cansaço, mal estar geral e queda\nde cabelo; atribuía todos os sintomas ao\nestresse do trabalho. Porém, há duas semanas iniciou dor\npunhos, interfalangeanas proximais e joelhos, acompanhada de rigidez matinal de 1 hora e urina\n\"espumosa\". História familiar: irmão faleceu por lúpus há 8 anos. História prévia: G2PN0C0A2\nespontâneos. Ao exame: REG; úlcera região palato (indolor); queda de mais de 3 fios de cabelo à\ntração; AR: MV reduzido em bases; AC: BRNF 2T sem sopros; artrite visível em punhos e joelhos;\nFC 102 bpm; FR 20 irpm; PA: 160x100mmHg. Exames: Hb: 8; Ht 25%; VCM: 110; Leuco: 6.300 (linf\n\n10% seg 86%); Plaquetas: 143.000; creatinina: 1,5 mg/dl; EAS: proteínas +++; hemácias ++;\ncilindros +; FAN: negativo; C3: 50 (80-100); C4: 7 (20-40); Coombs direto positivo; Fator\nreumatoide: positivo. Neste caso, podemos afirmar que:","options":{"A":"Trata-se de uma paciente com Síndrome do Anticorpo Antifosfolípede (SAAF), o início de\nanticoagulante oral é indispensável neste caso, pela história de aborto de repetição.","B":"A história descrita é muito sugestiva de lúpus, mas não podemos excluir a possibilidade de\nartrite\nreumatoide.","C":"Trata-se de um caso raro de início concomitante de artrite reumatoide e Sindrome Nefrítica.","D":"A insuficiência renal aguda, causada por provável nefrite proliferativa difusa, deve ser\nrapidamente tratada com metilprednisolona 1g EV, por 3 dias."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-84509","number":"84509","sourceNumber":"84509","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma das intercorrências clínicas mais frequentes na gravidez é a infecção do sistema\nurinário. Com base nessa afirmação, assinale a opção correta:","options":{"A":"Não se deve tratar bacteriúria assintomática, já que a gestante não apresenta sintomas.","B":"São fatores de risco para bacteriúria assintomática na gravidez: malformações anatômicas das\nvias urinárias e diabetes mellitus gestacional.","C":"A pielonefrite na gestação deve, sempre e exclusivamente, ser tratada ambulatorialmente.","D":"Não existe profilaxia de infecção urinária durante a gestação.","E":"Uma cistite não tratada nunca desencadeia um trabalho de parto prematuro."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-84514","number":"84514","sourceNumber":"84514","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação à fisiopatologia da pré-eclâmpsia, assinale a alternativa INCORRETA.","options":{"A":"Ausência da segunda onda de migração trofoblástica.","B":"Desequilíbrio do sistema das prostaglandinas, com predomínio das prostaciclinas.","C":"Angioespasmo universal levando à hemoconcentração.","D":"Perda da refratariedade ao SRAA.","E":"A lesão clássica da pré-eclâmpsia é a glomeruloendoteliose."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-66940","number":"66940","sourceNumber":"66940","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O conceito de hipertensão arterial na gestação, dado as modificações fisiológicas\ndecorrentes do período gestacional, deve ser considerado quando:","options":{"A":"PA \"maior ou igual\" 160/110 em duas medidas com intervalo mínimo de 4 horas;","B":"PA \"maior ou igual\" 140/90 em duas medidas com intervalo mínimo de 4 horas;","C":"PA \"maior ou igual\" 130/90 em uma única medida, após repouso de 30 minutos;","D":"O aumento de 30 mmHg na PA sistólica e de 15 mmHg na PA diastólica é o conceito mais atual\npara considerar hipertensão arterial na gestação, dadas as especificidades da gestante."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-66963","number":"66963","sourceNumber":"66963","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"São critérios para a classificação da pré-eclâmpsia grave:","options":{"A":"PA \"maior ou igual\" 160/110; creatinina > 1,2 mg/dl; proteinúria > 2 g/24h; LDH > 600 mg/dl;\nTGO > 70 mg/dl; sofrimento fetal agudo; edema agudo de pulmão;","B":"PA \"maior ou igual\" 180/120; creatinina > 1,5 mg/dl; proteinúria > 5g/24h; LDH > 600 mg/dl;\nTGO > 70 mg/dl;","C":"PA \"maior ou igual\" 160/110; creatinina > 0,9 mg/dl; proteinuria > 300 mg/24h; edema 4+ em\nMMII; sofrimento fetal agudo;","D":"Por se tratar da principal causa de mortalidade materna no Brasil, toda pré-eclâmpsia deve ser\nconsiderada grave."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-66982","number":"66982","sourceNumber":"66982","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 30 semanas de gestação, apresenta-se na maternidade com quadro\nconvulsivo, sem história prévia de convulsões, a melhor conduta será:","options":{"A":"Tratar a crise convulsiva com diazepan ou hidantal, solicitar tomografia de crânio e avaliação\ncom neurologista;","B":"Realizar suporte de vida, conter a paciente e aguardar que cesse a convulsão\nespontaneamente, acesso venoso, solicitar exames,\niniciar sulfato de magnésio, após a paciente\ncompensada e recebido os exames: interromper a gestação;","C":"Realizar suporte de vida, conter a paciente e aguardar que cesse a convulsão\nespontaneamente, acesso venoso, solicitar exames,\niniciar sulfato de magnésio, após a paciente\ncompensada e recebido os exames (se não houver critérios de gravidade nos resultados) iniciar\ncorticoide para maturação pulmonar fetal e postergar a resolução da gestação por 48 horas;","D":"Por se tratar de gestação longe do termo, a melhor conduta seria encaminhar a paciente para\ncuidados em UTI, pois dificilmente se trata de eclâmpsia nesta idade gestacional."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-67003","number":"67003","sourceNumber":"67003","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Frente a uma gestante com ITU baixo, que droga você escolheria como primeira opção\ndentre as citadas abaixo?","options":{"A":"Amoxicilina;","B":"Ciprofloxacino;","C":"Cefalotina;","D":"Nitrofurantoina."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-50048","number":"50048","sourceNumber":"50048","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Diante de uma gestante apresentando crises convulsivas eclâmpticas persistentes,\npode-se lançar mão das seguintes medidas,\nEXCETO:","options":{"A":"Administrar diazepan endovenoso (EV);","B":"Administrar dose adicional EV de sulfato de magnésio;","C":"Administrar hidantal;","D":"Levar a paciente ao bloco cirúrgico e submetê-la a anestesia geral;"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-37141","number":"37141","sourceNumber":"37141","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Para diagnosticar pré-eclâmpsia deve-se ter os seguintes critérios exceto:","options":{"A":"PA igual ou maior a 140 X 90 mmHg.","B":"Idade gestacional após 20 semanas.","C":"Confirmação da medida da PA após 4 horas.","D":"Presença de edema em membros inferiores maior que 2+/4+.","E":"Proteinúria acima de 300 mg/24h."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-37142","number":"37142","sourceNumber":"37142","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O uso de sulfato de magnésio está indicado nas seguintes situações durante a gravidez\nacima de 20 semanas, exceto:","options":{"A":"Reflexo patelar aumentado.","B":"Proteinúria maciça.","C":"Hellp Síndrome.","D":"Convulsão por eclâmpsia.","E":"Convulsão por eclâmpsia com primeira manifestação na gravidez."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-29418","number":"29418","sourceNumber":"29418","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As convulções da eclampsia são melhor controladas através da seguinte droga:","options":{"A":"diazepan","B":"bicarbonato de sódio","C":"sulfato de magnésio","D":"hidróxido de magnésio","E":"hidantal"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-341062","number":"341062","sourceNumber":"341062","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 26 semanas, com obesidade grau 2, nega comorbidades. Tercigesta e\nprimípara, vem para consulta de pré-natal com ultrassonografia morfológica de 2º trimestre,\nevidenciando feto único vivo, cefálico, placenta grau 0, peso estimado no percentil 95, ILA sem\nalterações. Ausência de alterações na morfologia fetal. Sobre o diagnóstico de diabetes\ngestacional, é correto afirmar que","options":{"A":"está estabelecido, nesse caso, pois já há 2 critérios maiores importantes: obesidade e feto no\npercentil 95.","B":"será estabelecido, caso haja constatação de glicemia de jejum ? 92mg/dL e ? 125mg/dL.","C":"será estabelecido, caso haja constatação de glicemia após a primeira hora ? 153mg/d, no Teste\nde Tolerância Oral a Glicose com 100g.","D":"será estabelecido, caso haja constatação de glicemia após a primeira hora ? 180mg/dL, no\nTeste de Tolerância Oral a Glicose com 100g."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-341063","number":"341063","sourceNumber":"341063","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 26 semanas, com obesidade grau 2, nega comorbidades. Tercigesta e\nprimípara, vem para consulta de pré-natal com ultrassonografia morfológica de 2º trimestre,\nevidenciando feto único vivo, cefálico, placenta grau 0, peso estimado no percentil 95, ILA sem\nalterações. Ausência de alterações na morfologia fetal. Uma vez confirmada a principal suspeita\ndiagnóstica no acompanhamento pós-parto para reclassificação diagnóstica, especifique o exame\nindicado para definição de Diabetes pós-gestacional:","options":{"A":"Dosagem de hemoglobina glicada 6 semanas após o parto.","B":"Nova glicemia de jejum 6 meses após o parto.","C":"Teste de Tolerância Oral a Glicose (TOTG 75g) 6 semanas após o parto.","D":"Teste de Tolerância Oral a Glicose (TOTG 75g) 6 meses após o parto."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-341065","number":"341065","sourceNumber":"341065","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em consulta de pré-natal, gestante de 34 anos de idade, na 30ª semana de gestação,\nafirma que vem apresentando cefaleia e\ncansaço com piora nos últimos três dias. Também relata\nque apresentou turvação visual ao se levantar hoje. Nega comorbidades prévias. Ao exame físico,\nPA: 140x100mmHg, edema de membros inferiores ++/4+. Teste de proteinúria: positivo. Diante do\nquadro clínico, indique a principal suspeita diagnóstica:","options":{"A":"Hipertensão gestacional.","B":"Eclâmpsia.","C":"Pre-eclâmpsia leve.","D":"Pre-eclâmpsia grave."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-341066","number":"341066","sourceNumber":"341066","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em consulta de pré-natal, gestante de 34 anos de idade, na 30ª semana de gestação,\nafirma que vem apresentando cefaleia e\ncansaço com piora nos últimos três dias. Também relata\nque apresentou turvação visual ao se levantar hoje. Nega comorbidades prévias. Ao exame físico,\nPA: 140x100mmHg, edema de membros inferiores ++/4+. Teste de proteinúria: positivo. Frente ao\ncaso, indique a conduta a ser adotada:","options":{"A":"Solicitar exames laboratoriais, M.A.P.A e retorno em uma semana.","B":"Realizar cardiotocografia, exames laboratoriais e solicitar retorno em uma semana.","C":"Internar a paciente para observação e solicitar e exames.","D":"Solicitar exames laboratoriais e ultrassom obstétrico e pedir retorno com exames em uma\nsemana."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-341067","number":"341067","sourceNumber":"341067","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em consulta de pré-natal, gestante de 34 anos de idade, na 30ª semana de gestação,\nafirma que vem apresentando cefaleia e\ncansaço com piora nos últimos três dias. Também relata\nque apresentou turvação visual ao se levantar hoje. Nega comorbidades prévias. Ao exame físico,\nPA: 140x100mmHg, edema de membros inferiores ++/4+. Teste de proteinúria: positivo. Indique a\nmedicação que deverá inicialmente ser prescrita para essa paciente.","options":{"A":"Hidralazina.","B":"Sulfato de magnésio.","C":"Nifedipina ou metildopa.","D":"Metildopa."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-315197","number":"315197","sourceNumber":"315197","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 12 semanas de gestação vem para segunda consulta de pré-natal\napresentar primeiros exames de rotina. Entre os\nexames, colhidos há 1 mês, apresenta glicemia de\njejum de 158 mg/dl. Sobre o caso relatado, assinale a alternativa CORRETA.","options":{"A":"A paciente possui diabetes mellitus gestacional.","B":"Deve ser solicitado TOTG 75 g a partir das 24 semanas de gestação para conclusão diagnóstica.","C":"O diagnóstico é de diabetes mellitus prévio e a avaliação da hemoglobina glicada, apesar de não\nser necessária como parâmetro diagnóstico, pode\nacrescentar informações sobre riscos de\nmalformações fetais associadas à hiperglicemia.","D":"Esse feto não possui risco de macrossomia, tendo em vista tratar-se de um quadro de diabetes\nmellitus prévio, o que confere maior risco de crescimento intrauterino restrito.","E":"Para confirmação diagnóstica deve ser solicitado imediatamente o TOTG 75 g e será confirmado\ndiabetes prévio diante de no mínimo 2 valores alterados."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-315201","number":"315201","sourceNumber":"315201","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Sobre Hiperêmese Gravídica, assinale a alternativa INCORRETA.","options":{"A":"Quadro depressivo prévio à gestação e gravidez não planejada configuram fatores de risco para\na ocorrência de hiperêmese gravídica.","B":"A hiperêmese gravídica pode estar associada a níveis muito elevados de hCG, tal como ocorre\nem doença trofoblástica gestacional e gestação\nmúltipla.","C":"Sua ocorrência, mais comum no primeiro trimestre, não se associa à elevada morbidade\nmaterna com ocorrência de distúrbios hidroeletrolítico e ácidobásico.","D":"O uso do gengibre tem sido aventado no tratamento desta patologia gestacional.","E":"Pode ser vista como uma doença psicossomática em que a gestante exterioriza através da\nêmese um conflito psíquico por rejeição à\ngravidez, por exemplo."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-275999","number":"275999","sourceNumber":"275999","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"G?P??A?, obesa, com 10 semanas de gestação traz exames de rotina apresentando\nGlicemia de Jejum de 140 mg/dl e HbAc1 de\n12%. Refere diabetes gestacional em gravidez\nanterior. Assinale a opção CORRETA.","options":{"A":"Trata-se de um quadro de diabetes gestacional e deve-se iniciar tratamento medicamentoso.","B":"Trata-se de um quadro de diabetes gestacional e deve-se iniciar tratamento não medicamentoso.","C":"Não se trata de diabetes, sendo necessário prosseguir investigação com TOTG 75g de glicose\ncom 24 semanas de gestação.","D":"Trata-se de um quadro de diabetes mellitus instalado previamente à gestação.","E":"Trata-se de um quadro de diabetes mellitus e a hemoglobina glicada de 12% não demonstra\npossibilidade de riscos fetais para cardiopatias estruturais."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-283741","number":"283741","sourceNumber":"283741","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Casal jovem, ambos com de 33 anos, vem ao consultório porque desejam ter um filho.\nEla é tercigesta, nulípara. Há três anos\nvem tentando engravidar sem sucesso. Paciente referiu que\nantes ela conseguia engravidar, porém sofreu 3 abortamentos precoces, sendo o último há 4 anos.\nEm todas as gestações os embriões paravam de apresentar batimento cardíaco fetal antes de 9\nsemanas de idade gestacional. Todos os exames hormonais realizados não evidenciaram\nalterações. Cariótipo da paciente e do esposo: normais. Exame de imagem na época do último\nabortamento não evidenciou malformações uterinas. Realizou curetagem uterina no primeiro e no\nterceiro abortamentos. Ciclo menstrual costuma ser regular, porém há 5 meses não menstrua. Caso\nseja confirmada a Síndrome do Anticorpo Antifosfolípideo (SAAF), nessa paciente, indique a melhor\nconduta a ser adotada.","options":{"A":"Fazer uso contínuo de heparina de baixo pelo molecular, antes e durante a gestação.","B":"Fazer uso de ácido acetilsalicílico, continuamente, antes e durante a gestação.","C":"Fazer uso de heparina e ácido acetilsalicílico, continuamente, a partir do diagnóstico precoce da\ngestação.","D":"Fazer uso de varfarina, continuamente, a partir do diagnóstico precoce da gestação."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-283742","number":"283742","sourceNumber":"283742","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 36 semanas, sem comorbidades, secundigesta com parto normal anterior,\nvem à maternidade para atendimento pois há\n1 dia começou a apresentar turvação visual e edema\nem membros inferiores. Ao exame físico, além do edema, PA: 150x100mmHg, FC: 82bpm,\nmucosas normocoradas. Ausculta cardíaca e pulmonar sem alterações. Exame obstétrico: altura\nuterina: 33cm, apresentação cefálica, batimentos cardíacos fetais: 148bpm, dinâmica uterina\nausente, tônus uterino normal. Ao toque vaginal: colo fechado, grosso, posterior. Com base no\nquadro clínico descrito e nos seus conhecimentos sobre hipertensão, é correto afirmar:","options":{"A":"Paciente que apresenta hipertensão crônica fora da gestação e que está bem controlada com\nmedicações não apresenta risco aumentado de evoluir para pré-eclâmpsia quando gestante.","B":"O cálcio é uma medicação utilizada na prevenção de pré-eclâmpsia em pacientes previamente\nhipertensas.","C":"Quando a paciente evolui com hipertensão gestacional o uso de Captopril é uma opção.","D":"A mola hidatiforme é uma patologia associada à pré-eclâmpsia de início tardio."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-283743","number":"283743","sourceNumber":"283743","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 36 semanas, sem comorbidades, secundigesta com parto normal anterior,\nvem à maternidade para atendimento pois há\n1 dia começou a apresentar turvação visual e edema\nem membros inferiores. Ao exame físico, além do edema, PA: 150x100mmHg, FC: 82bpm,\nmucosas normocoradas. Ausculta cardíaca e pulmonar sem alterações. Exame obstétrico: altura\nuterina: 33cm, apresentação cefálica, batimentos cardíacos fetais: 148bpm, dinâmica uterina\nausente, tônus uterino normal. Ao toque vaginal: colo fechado, grosso, posterior. Indique a\nprincipal\nhipótese diagnóstica para o caso.","options":{"A":"Hipertensão gestacional.","B":"Pré-eclâmpsia.","C":"Pré-eclâmpsia superajuntada.","D":"Síndrome HELLP."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-283744","number":"283744","sourceNumber":"283744","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 36 semanas, sem comorbidades, secundigesta com parto normal anterior,\nvem à maternidade para atendimento pois há\n1 dia começou a apresentar turvação visual e edema\nem membros inferiores. Ao exame físico, além do edema, PA: 150x100mmHg, FC: 82bpm,\nmucosas normocoradas. Ausculta cardíaca e pulmonar sem alterações. Exame obstétrico: altura\nuterina: 33cm, apresentação cefálica, batimentos cardíacos fetais: 148bpm, dinâmica uterina\nausente, tônus uterino normal. Ao toque vaginal: colo fechado, grosso, posterior. Em relação ao\nquadro clínico descrito, a melhor conduta para o caso é:","options":{"A":"Exame de fundo de olho e prescrever o anti-hipertepsivo.","B":"Internação, sulfato de magnésio, coleta de exames laboratoriais e corticoide seguido de\ninterrupção da gestação em 48 horas.","C":"Internação, cardiotocografia, ultrassonografia obstétrica, controle adequado da pressão, sulfato\nde magnésio, exames laboratoriais. Avaliar via de\nparto conforme ultrassonografia, vitalidade fetal e\nestabilidade materna.","D":"Internação, cardiotocografia, ultrassonografia obstétrica, controle adequado da pressão, sulfato\nde magnésio, exames laboratoriais. Interrupção\nda gestação por cesariana."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-276003","number":"276003","sourceNumber":"276003","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Sobre síndromes hipertensivas gestacionais, assinale a resposta INCORRETA.","options":{"A":"Podem ser tratadas com metildopa e nifedipino.","B":"Dopplerfluxometria das artérias umbilical e cerebral média fetal e cardiotocografia são exames\nque fazem avaliação da vitalidade fetal em\ncasos de síndromes hipertensivas gestacionais.","C":"Síndrome HELLP é uma de suas formas graves e se caracteriza por elevação das enzimas\nhepáticas, hemólise e plaquetopenia.","D":"Sua forma grave denominada eclâmpsia pode ser tratada com MgSO4 (sulfato de magnésio),\ncuja função é a redução da pressão arterial.","E":"Pode haver quadro de hematoma subcapsular hepático diante da importante elevação da\nconcentração das transaminases."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-280441","number":"280441","sourceNumber":"280441","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Considere as assertivas a respeito do diabete na gestação. I. No início do terceiro\ntrimestre o exame mais adequado para\nrastreamento é o TOTG-75g. II. Uma glicemia de jejum\nacima de 92 no primeiro trimestre faz o diagnóstico de diabete. III. Gestantes diabéticas devem ser\ntratadas somente com insulina. IV. Hipoglicemiantes orais, quando comparados com insulina,\npodem aumentar o risco de hipoglicemia neonatal. São corretas as assertivas","options":{"A":"I e II","B":"I e III","C":"I e IV","D":"II e IV"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-278124","number":"278124","sourceNumber":"278124","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Considere as seguintes assertivas em relação ao diabete na gestação. I. A primeira\nmetade da gravidez é considerada a fase\nanabólica. II. Na gestação normal não ocorre aumento na\nnecessidade de insulina. III. O pâncreas na gravidez normal consegue aumentar a produção de\ninsulina em até 200%. IV. Na segunda metade da gestação ocorre diminuição na resistência\nperiférica à insulina. As assertivas corretas são","options":{"A":"I e II","B":"I e III","C":"II e III","D":"II e IV"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-279079","number":"279079","sourceNumber":"279079","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Fator responsável pela diminuição da contagem de plaquetas em gestantes com\npré-eclâmpsia é","options":{"A":"perda de plaquetas para o espaço extravascular.","B":"adesão das plaquetas ao endotélio lesionado.","C":"descolamento de placenta subclínico.","D":"anemia crônica."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-279081","number":"279081","sourceNumber":"279081","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Os quadros hipertensivos na gravidez associados a alterações da circulação\nútero-placentária e restrição de crescimento fetal são geralmente classificados como","options":{"A":"pré-eclâmpsia de início precoce.","B":"pré-eclâmpsia sobreposta.","C":"hipertensão crônica sem pré-eclâmpsia.","D":"hipertensão transitória."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-280451","number":"280451","sourceNumber":"280451","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Situação que não caracteriza risco gestacional que indique aborto terapêutico","options":{"A":"coarctação de aorta.","B":"Síndrome de Marfan.","C":"persistência de canal arterial.","D":"miocardiopatia dilatada."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-280453","number":"280453","sourceNumber":"280453","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Droga de escolha em caso de trombofilia na gestação.","options":{"A":"Warfarina.","B":"Enoxaparina.","C":"Heparina Liquemine.","D":"AAS."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-278664","number":"278664","sourceNumber":"278664","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A gestação gemelar é dita monocoriônica quando os fetos","options":{"A":"dividem uma placenta.","B":"se originam de um óvulo.","C":"dividem a mesma cavidade amniótica.","D":"têm placentas separadas."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-278665","number":"278665","sourceNumber":"278665","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Para gestantes com asma persistente, o melhor tratamento isolado é","options":{"A":"Beta2 agonista inalatório.","B":"Corticóide Inalatório.","C":"Montelucaste.","D":"Aminofilinaoral."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-279085","number":"279085","sourceNumber":"279085","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante previamente normotensa, com aferição de pressão arterial em consultório de\n145x90 mmHg, submetida a aferições\ndomiciliares sem nunca ultrapassar 135x85 mmHg. Segundo\na mais moderna classificação de quadros hipertensivos na gravidez, se trata de","options":{"A":"pré-eclampsia leve.","B":"pré-eclâmpsia grave.","C":"hipertensão do jaleco branco.","D":"hipertensão crônica."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-280455","number":"280455","sourceNumber":"280455","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em gestação gemelar monocoriônica ? diamniótica de 26 semanas, existe discrepância\nentre o peso dos fetos de 30%, com feto maior\napresentando polidramnia e feto menor com\noligodramnia. O diagnóstico mais provável é","options":{"A":"restrição de crescimento fetal por insuficiência placentária.","B":"síndrome de transfusão feto-fetal.","C":"malformação cardíaca do feto maior.","D":"isoimunização Rh."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-280457","number":"280457","sourceNumber":"280457","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A integração entre embrião e útero materno provoca no organismo um intrínseco\nestímulo hormonal, sendo adequado o item:","options":{"A":"Que impede transformações na fisiologia do sistema cardiovascular, as quais são fundamentais\npara o adequado desenvolvimento da gravidez.","B":"Que induz a transformações na fisiologia do sistema cardiovascular, as quais não são\nfundamentais para o adequado desenvolvimento da gravidez.","C":"Que induz a transformações na fisiologia do sistema cardiovascular, as quais são fundamentais\npara o inadequado desenvolvimento da gravidez.","D":"Que induz a transformações na fisiologia do sistema cardiovascular, as quais são fundamentais\npara o adequado desenvolvimento da gravidez."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-278668","number":"278668","sourceNumber":"278668","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Podemos considerar que as mulheres com Diabetes Mellitus Gestacional DMG\napresentam","options":{"A":"Maior chance de recorrência do DMG em gestações futuras e também maior risco de\ndesenvolverem DM2 ao longo da vida.","B":"Menor chance de recorrência do DMG em gestações futuras e também maior risco de\ndesenvolverem DM2 ao longo da vida.","C":"Igual chance de recorrência do DMG em gestações futuras e também maior risco de\ndesenvolverem DM2 ao longo da vida.","D":"Maior chance de recorrência do DMG em gestações futuras, mas menor risco de desenvolverem\nDM2 ao longo da vida."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-231364","number":"231364","sourceNumber":"231364","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Os distúrbios hipertensivos da gravidez são considerados os distúrbios mais comuns da\ngestação. Suas formas de apresentação são variadas e com critérios de gravidade distintos. É\npossível identificar aquelas de maior gravidade a fim de se introduzir terapêutica e monitorização\nmais rigorosas. Assinale, dentre as alternativas a seguir, aquela que NÃO apresenta critério de\ngravidade da pré-eclâmpsia.","options":{"A":"Edema 4+ em membros inferiores bilateralmente.","B":"Dor epigástrica ou em hipocôndrio direito.","C":"PA = 160/110 mmHg.","D":"Proteinúria de 2+ em exame de urina.","E":"Aumento de enzimas hepáticas TGO e TGP."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-249308","number":"249308","sourceNumber":"249308","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A principal indicação de ecocardiograma fetal está na gestante:","options":{"A":"diabética gestacional com Hb Glicada 5,6% no primeiro trimestre.","B":"diabética tipo 2 com Hb Glicada 10,2% no primeiro trimestre.","C":"diabética tipo 1 com Hb Glicada 6,1% no primeiro trimestre.","D":"diabética tipo 2 com Hb Glicada 5,9% no segundo trimestre."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-252903","number":"252903","sourceNumber":"252903","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher branca, 43 anos de idade, 4 gestações anteriores, todas tendo evoluído com\nparto normal. Última gestação há 10 anos.\nRefere que nas duas últimas gestações apresentou\npicos pressórios que melhoraram após o parto. Vem em consulta de pré-natal pois está grávida de\n8 semanas do seu novo marido. No momento encontra-se obesa grau 2 e é tabagista meio maço\npor dia. Diante do caso descrito, pode-se afirmar que são fatores de risco para pré-eclâmpsia:","options":{"A":"Tabagismo, obesidade, multiparidade, idade materna avançada.","B":"Gestação com novo parceiro, raça branca, idade materna avançada, longo intervalo interpartal.","C":"Gestação com novo parceiro, obesidade, idade materna avançada, longo intervalo interpartal.","D":"Tabagismo, longo intervalo interpartal, multiparidade, raça branca."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-252904","number":"252904","sourceNumber":"252904","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher branca, 43 anos de idade, 4 gestações anteriores, todas tendo evoluído com\nparto normal. Última gestação há 10 anos.\nRefere que nas duas últimas gestações apresentou\npicos pressóricos que melhoraram após o parto. Vem em consulta de pré-natal, pois está grávida\nde 8 semanas do seu novo marido. No momento encontra-se obesa grau 2 e é tabagista meio\nmaço por dia. Durante a consulta de pré-natal, com 8 semanas, a paciente apresentou pressão\narterial de 150 x 90 mmHg (mesmo após repetição da aferição) e estava assintomática. Nesse\ncaso, o diagnóstico mais provável é:","options":{"A":"Pré-eclâmpsia.","B":"Pré-eclâmpsia sobreposta.","C":"Hipertensão gestacional.","D":"Hipertensão crônica."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-252905","number":"252905","sourceNumber":"252905","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher branca, 43 anos de idade, 4 gestações anteriores, todas tendo evoluído com\nparto normal. Última gestação há 10 anos.\nRefere que nas duas últimas gestações apresentou\npicos pressórios que melhoraram após o parto. Vem em consulta de pré-natal pois está grávida de\n8 semanas do seu novo marido. No momento encontra-se obesa grau 2 e é tabagista meio maço\npor dia. Com relação à situação atual da paciente, a conduta terapêutica a ser indicada nesse\nmomento, é o uso","options":{"A":"de diuréticos tiazidicos para prevenção de outras complicações gestacionais, pois melhorarão a\nperfusão placentária.","B":"diário de hidralazina oral.","C":"de inibidores da enzima conversora da angiotensina, pela ausência de efeitos colaterais.","D":"de metildopa, apesar de ser considerada um anti-hipertensivo leve."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-249311","number":"249311","sourceNumber":"249311","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 28 semanas realiza TOTG 75 g e o resultado é: Jejum = 97 mg/dl 60 min.\n\n= 172 mg/dl 120 min.= 138 mg/dl. A conduta nesse caso é explicar à gestante que:","options":{"A":"o exame está normal e não há necessidade de tratamento.","B":"apesar do exame estar normal, a gestante deve evitar carboidratos pelo risco de diabete\ngestacional.","C":"existe diagnóstico de diabete gestacional no momento e deve ser instituída dieta específica.","D":"existe diagnóstico de diabete gestacional e já está indicada dieta e insulinoterapia."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-249317","number":"249317","sourceNumber":"249317","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestações gemelares monocoriônicas / monoamnióticas devem ter resolução com a\nidade gestacional de:","options":{"A":"34 semanas","B":"37 semanas","C":"39 semanas","D":"40 semanas"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-249427","number":"249427","sourceNumber":"249427","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Atualmente a principal indicação para uso do Sulfato de Magnésio em obstetrícia é:","options":{"A":"Realizar tocólise.","B":"Controle de pressão arterial.","C":"Evitar enterocolite necrotizante no recém-nascido.","D":"Prevenir ou tratar eclampsia."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-249242","number":"249242","sourceNumber":"249242","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 28 semanas realiza TOTG 75 g e o resultado é: Jejum = 97 mg/dl; 60\nmin. = 172 mg/dl; 120 min.= 138 mg/dl. A conduta nesse caso é explicar à gestante que:","options":{"A":"o exame está normal e não há necessidade de tratamento.","B":"apesar do exame estar normal, a gestante deve evitar carboidratos pelo risco de diabete\ngestacional.","C":"existe diagnóstico de diabete gestacional no momento e deve ser instituída dieta específica.","D":"existe diagnóstico de diabete gestacional e já está indicada dieta e insulinoterapia."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-249250","number":"249250","sourceNumber":"249250","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Na hemólise microangiopática causada pela pré-eclampsia grave, o exame laboratorial\nalterado é:","options":{"A":"transaminase","B":"ácido úrico","C":"esquisócito","D":"plaqueta"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-201779","number":"201779","sourceNumber":"201779","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A situação que se associa à pré-eclâmpsia de repetição e descolamento prematuro de\nplacenta é:","options":{"A":"Trombofilias.","B":"Diabetes gestacional.","C":"Primopaternidade sucessivas.","D":"Obesidade materna.","E":"Extremos de idade."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-219904","number":"219904","sourceNumber":"219904","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O acompanhamento pré-natal de qualidade é essencial para a saúde materno e fetal.\n\nEntre os objetivos dessa assistência está diagnosticar ou confirmar doenças maternas\n\npré-existentes. O exame clínico completo é imprescindível na primeira consulta pré-natal para a\ngarantia desse objetivo. Você está atendendo uma gestante de 32 anos, G3P2, dois partos vaginais\nprévios. História de elevação de níveis pressóricos na última gestação há 2 anos, com uso de\nhipotensor até a data do parto. Hoje está com 6 semanas de amenorreia e teste rápido de gravidez\npositivo. Nega doenças prévias e uso atual de medicamentos. Tabagista - 3 a 5 cigarros por dia.Ao\nexame clínico identifica-se: IMC 30 kg/m²; frequência cardíaca de 80 bpm; frequência respiratória\n20 irpm; PA (sentada) 140 x 90 mmHg; mucosas coradas e hidratadas; sem edemas; ausculta\ncardíaca e respiratória sem alterações; abdome normotenso sem visceromegalias; exame\nginecológico com resíduo vaginal fisiológico, colo uterino epitelizado, útero pouco aumentado de\ntamanho, consistência gravídica. Diante desse caso assinale a MELHOR CONDUTA a ser adotada:","options":{"A":"Iniciar metildopa 250 mg, via oral de 12/12 horas e reavaliar em uma semana e orientar para\ninterromper tabagismo.","B":"Iniciar nifedipina de liberação prolongada 20mg, via oral, uma vez ao dia e reavaliar em uma\nsemana e orientar","C":"Orientar para interromper tabagismo e reavaliar em um segundo momento os níveis pressóricos\npara definição de diagnóstico.","D":"Solicitar proteinúria de 24 horas, clearance de creatinina, dosagem sérica de ureia, creatinina e\nácido úrico, eletrocardiograma e fundoscopia e reavaliar após os resultados dos exames."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-219906","number":"219906","sourceNumber":"219906","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As gestações múltiplas representam riscos elevados para a mulher e para o feto e sua\nincidência vem aumentando nas últimas décadas. A correta caracterização do tipo de gemelaridade\nauxilia no planejamento do cuidado obstétrico e na caracterização das complicações fetais. Associe\na classificação da gemelaridade da COLUNA A com os achados no primeiro trimestre e assinale a\nalternativa que mostra a correlação CORRETA:","options":{"A":"1A; 2C; 3B.","B":"1B; 2A; 3C.","C":"1C; 2A; 3B.","D":"1C; 2B; 3A."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-212137","number":"212137","sourceNumber":"212137","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Diabetes Mellitus (DM) é um importante e crescente problema de saúde para todos os\npaíses, independentemente do seu grau de desenvolvimento. Qual a principal causa de óbito nos\nindivíduos com diabetes tipo 2?","options":{"A":"Infecção.","B":"Cetoacidose.","C":"Hipoglicemia.","D":"Nefropatia diabética.","E":"Doença cardiovascular."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215476","number":"215476","sourceNumber":"215476","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O Sulfato de Magnésio é a droga de escolha para:","options":{"A":"Promover o controle e profilaxia de crises convulsivas.","B":"Diminuir a pressão arterial com rapidez.","C":"Controlar a pressão arterial a longo prazo.","D":"Induzir o amadurecimento pulmonar fetal."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-216308","number":"216308","sourceNumber":"216308","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente questiona seu ginecologista sobre os riscos de trombose venosa pelo uso de\nanticoncepcional combinado oral. O ginecologista orienta que, em caso de gravidez, o risco de\ntromboembolismo seria","options":{"A":"igual ao de uma mulher que toma anticoncepcional.","B":"menor do que tomar o anticoncepcional.","C":"de 7 a 10 vezes maior do que uma mulher que não toma anticoncepcional.","D":"seria 30 vezes maior do que uma mulher que toma anticoncepcional."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-212224","number":"212224","sourceNumber":"212224","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 16 semanas de gravidez, pela data da última mestruação ? DUM,\napresenta altura de fundo uterino medindo 22 cm,\ncom bcf presentes. São hipóteses diagnósticas:\n\nI. erro de cálculo na data da DUM. II. prenhez gemelar. III. oligohidramnia. IV. mola hidatiforme\ncompleta. Dos itens, verifica-se que estão corretos apenas","options":{"A":"I e II.","B":"I e III.","C":"I e IV.","D":"II e III.","E":"II, III e IV."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-216229","number":"216229","sourceNumber":"216229","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A única desvantagem do Pindolol em relação à metildopa é","options":{"A":"piora o edema materno.","B":"o custo mais elevado.","C":"tem menor eficácia no controle pressórico.","D":"diminui mais acentuadamente o fluxo útero-placentário."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215534","number":"215534","sourceNumber":"215534","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em quadros de pré-eclâmpsia grave, a epigastralgia pode representar complicação\ntemível. O mecanismo que determina esse\nsintoma é:","options":{"A":"Gastrite enantematosa aguda.","B":"Distensão de cápsula hepática.","C":"Úlcera péptica.","D":"Fissuras esofágicas."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-216250","number":"216250","sourceNumber":"216250","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em gestante com hipertiroidismo utilizando Propiltiouracil, o objetivo do tratamento é\nmanter","options":{"A":"o T4 livre no limite superior de normalidade.","B":"o T4 livre em níveis próximos ao limite inferior de normalidade.","C":"o TSH no limite superior da normalidade.","D":"níveis similares de T4 livre e T3."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-216304","number":"216304","sourceNumber":"216304","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com infecção urinária apresenta ao antibiograma sensibilidade a vários\nantibióticos, sendo a melhor opção dos listados abaixo,","options":{"A":"gentamicina.","B":"nitrofurantoina.","C":"clindamicina.","D":"doxiciclina."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215195","number":"215195","sourceNumber":"215195","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Os casos de trombose venosa profunda durante a gravidez acontecem em membro\ninferior esquerdo em 85 % das vezes. O que explica essa estatística é a:","options":{"A":"Sinistro-versão uterina.","B":"Compressão da veia ilíaca esquerda pela artéria ilíaca direita.","C":"Dextroversão uterina.","D":"Compressão da veia ilíaca direita pela artéria ilíaca esquerda."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-216206","number":"216206","sourceNumber":"216206","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Pensando em realizar cesareana em paciente de 34 semanas, com DHEG grave, dos\nexames listados, aquele que deve ser\nconsiderado o mais importante no pré-operatório é","options":{"A":"TGO.","B":"Gama GT.","C":"Contagem de plaquetas.","D":"Esquisócitos."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215551","number":"215551","sourceNumber":"215551","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A preocupação com a situação atual do diabetes e do problema que ele representa\npara todos os países foi suficiente para que se\ntornasse o tema de uma Assembleia das Nações\nUnidas, sendo ADEQUADO que, em articulação com o setor educacional, essas ações:","options":{"A":"Não devem priorizar a população de crianças, adolescentes e adultos jovens.","B":"Devem priorizar a população de crianças, adolescentes e adultos jovens.","C":"Devem priorizar a população de crianças, apenas.","D":"Devem priorizar a população de e adultos jovens, apenas."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215553","number":"215553","sourceNumber":"215553","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Estudos epidemiológicos para a história natural e a patogênese do diabetes baseiam-se\napenas nas alterações glicêmicas, apesar de\ncondições associadas, com várias evidências foram\nacumuladas, sugerindo mecanismos que apenas NÃO podem ser condizentes com o seguinte item:","options":{"A":"Etiologicamente iguais.","B":"Genéticos.","C":"Ambientais.","D":"Imunológicos."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215557","number":"215557","sourceNumber":"215557","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Para que se consiga elucidar a história natural e a patogênese do diabetes baseiam-se,\napenas, na grande variedade de\nmanifestações clínicas e condições associadas. Várias evidências\nforam acumuladas sugerindo mecanismos que, apenas, podem ser condizentes com o seguinte\nitem:","options":{"A":"Não possuem importante papel na patogênese, no curso clínico e no aparecimento de\ncomplicações do diabetes.","B":"Possuem importante papel na patogênese, no curso clínico e não no aparecimento de\ncomplicações do diabetes.","C":"Possuem importante papel na patogênese, no curso clínico e no aparecimento de complicações\ndo diabetes.","D":"Possuem importante papel na patogênese, no curso clínico e nunca no aparecimento de\ncomplicações do diabetes."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215561","number":"215561","sourceNumber":"215561","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Na análise da epidemiologia e impacto global do diabetes mellitus, os indivíduos com\ndiabetes mal controlado desenvolvem mais complicações. Apesar de que, as complicações do\ndiabetes são encontradas mesmo antes da hiperglicemia; assim podemos ACEITAR que:","options":{"A":"Não evidenciando a grande heterogeneidade desse distúrbio metabólico.","B":"Evidenciando a grande heterogeneidade desse distúrbio metabólico.","C":"Evidenciando a pouca heterogeneidade desse distúrbio metabólico.","D":"Evidenciando a grande homogeneidade desse distúrbio metabólico."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215565","number":"215565","sourceNumber":"215565","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Dentro do impacto global do diabetes mellitus, quanto às complicações crônicas do\ndiabetes resultantes, podemos ACEITAR que:","options":{"A":"Está claro o quanto as complicações crônicas do diabetes são resultantes da própria\nhiperglicemia ou de condições associadas, como\ndeficiência de insulina, excesso de glucagon,\nmudanças da osmolaridade, glicação de proteínas e alterações lipídicas ou da pressão arterial.","B":"Está claro o quanto as complicações crônicas do diabetes não são resultantes da própria\nhiperglicemia ou de condições associadas, como deficiência de insulina, excesso de glucagon,\nmudanças da osmolaridade, glicação de proteínas e alterações lipídicas ou da pressão arterial.","C":"Ainda não está claro o quanto as complicações crônicas do diabetes são resultantes da própria\nhiperglicemia ou de condições associadas, como deficiência de insulina, excesso de glucagon,\nmudanças da osmolaridade, glicação de proteínas, mas sim e somente de alterações lipídicas ou\nda pressão arterial.","D":"Ainda não está claro o quanto as complicações crônicas do diabetes são resultantes da própria\nhiperglicemia ou de condições associadas, como deficiência de insulina, excesso de glucagon,\nmudanças da osmolaridade, glicação de proteínas e alterações lipídicas ou da pressão arterial."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215566","number":"215566","sourceNumber":"215566","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Epidemiologia e impacto global do diabetes mellitus dentro da saúde pública são\ninformações importantes para o conhecimento da carga que o diabetes representa para os\nsistemas de saúde. Assim, está CORRETO que:","options":{"A":"Tanto a frequência de novos casos (incidência) como a de casos existentes (prevalência), não\nsão informações importantes para o conhecimento da\ncarga que o diabetes representa para os\nsistemas de saúde.","B":"Tanto a frequência de novos casos (incidência) como a de casos existentes (prevalência) são\ninformações pouco importantes para o conhecimento da carga que o diabetes representa para os\nsistemas de saúde.","C":"Tanto a frequência de novos casos (incidência) como a de casos existentes (prevalência) são\ninformações importantes para o conhecimento da carga que o diabetes não representa para os\nsistemas de saúde.","D":"Tanto a frequência de novos casos (incidência) como a de casos existentes (prevalência) são\ninformações importantes para o conhecimento da carga que o diabetes representa para os\nsistemas de saúde."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215567","number":"215567","sourceNumber":"215567","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As informações importantes para o conhecimento do diabetes representam para os\nsistemas de saúde dentro da saúde pública, pode ser ENTENDIDO que:","options":{"A":"A incidência não traduz o risco médio da população em adquirir a doença, além de servir de\nparâmetro para a avaliação do impacto produzido por medidas de prevenção.","B":"A incidência traduz o risco médio da população em adquirir a doença, além de servir de\nparâmetro para a avaliação do impacto produzido por medidas de prevenção.","C":"A incidência traduz o risco médio da população em adquirir a doença, além de não servir de\nparâmetro para a avaliação do impacto produzido por medidas de prevenção.","D":"A incidência não traduz o risco da população em adquirir a doença, além de servir de parâmetro\npara a avaliação do impacto produzido por\nmedidas de prevenção."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215547","number":"215547","sourceNumber":"215547","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Entendendo a epidemiologia e impacto do diabetes mellitus nos países desenvolvidos,\nque difere de nossa realidade de país em\ndesenvolvimento, o aumento da prevalência ocorrerá,\nprincipalmente, devido ao seguinte item:","options":{"A":"Pela contribuição de indivíduos com diabetes nas faixas etárias mais baixas, em decorrência do\naumento da expectativa de vida e do crescimento populacional.","B":"Pela contribuição de indivíduos com diabetes nas faixas etárias mais avançadas, em decorrência\nda redução da expectativa de vida e do\ncrescimento populacional.","C":"Pela contribuição de indivíduos com diabetes nas faixas etárias mais avançadas, em decorrência\ndo aumento da expectativa de vida e do\ncrescimento populacional.","D":"Pela contribuição de indivíduos com diabetes nas faixas etárias mais avançadas, em decorrência\ndo aumento da expectativa de vida e da diminuição\npopulacional."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215556","number":"215556","sourceNumber":"215556","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O estudo Global Burden of Disease (GBD) 4 aponta que a carga representada pelo\ndiabetes terá maior impacto (em termos de sistema de saúde e sociedade) nos países em\ndesenvolvimento.","options":{"A":"Em relação ao diabetes, o fenômeno da transição epidemiológica, em termos econômicos,\nrepresenta uma importante carga tanto nos custos diretos para o sistema de saúde e para a\nsociedade como nos custos indiretos atribuíveis à mortalidade prematura e a incapacitações\ntemporárias e permanentes decorrentes de suas complicações.","B":"Em relação ao diabetes, o fenômeno da transição epidemiológica, em termos econômicos, não\nrepresenta uma importante carga tanto nos custos diretos para o sistema de saúde e para a\nsociedade como nos custos indiretos atribuíveis à mortalidade prematura e a incapacitações\ntemporárias e permanentes decorrentes de suas complicações.","C":"Em relação ao diabetes, o fenômeno da transição epidemiológica, em termos econômicos,\nrepresenta uma importante carga somente nos\ncustos diretos para o sistema de saúde e não para a\nsociedade como nos custos indiretos atribuíveis à mortalidade prematura e a incapacitações\ntemporárias e permanentes decorrentes de suas complicações.","D":"Em relação ao diabetes, o fenômeno da transição epidemiológica, em termos econômicos,\nrepresenta uma importante carga tanto nos\ncustos diretos para o sistema de saúde, mas não para a\nsociedade como nos custos indiretos atribuíveis à mortalidade prematura e a incapacitações\ntemporárias e permanentes decorrentes de suas complicações."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215559","number":"215559","sourceNumber":"215559","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Para novas estratégias que devem promover um estilo de vida saudável e mudanças\nde hábitos em relação ao consumo de certos\nalimentos para obter sucesso no controle do diabetes,\né CORRETO que:","options":{"A":"Não é necessário estabelecer e desenvolver novas e mais fortes parcerias entre órgãos\ngovernamentais e sociedade civil, para uma\nmaior corresponsabilidade em ações orientadas para\nprevenção, detecção e controle do diabetes.","B":"É necessário não estabelecer e desenvolver novas e mais fortes parcerias entre órgãos\ngovernamentais e sociedade civil, para uma\nmaior corresponsabilidade em ações orientadas para\nprevenção, detecção e controle do diabetes.","C":"É necessário estabelecer e desenvolver novas e mais fortes parcerias entre órgãos\ngovernamentais e sociedade civil, para uma\nmaior corresponsabilidade em ações orientadas para\nprevenção, detecção e controle do diabetes.","D":"É necessário estabelecer e desenvolver novas e mais fracas parcerias entre órgãos\ngovernamentais e sociedade civil, para uma\nmaior corresponsabilidade em ações orientadas para\nprevenção, detecção e controle do diabetes."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-187795","number":"187795","sourceNumber":"187795","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"No que diz respeito às alterações hematológicas da gravidez, assinale alternativa\nERRADA:","options":{"A":"A expansão do volume sanguíneo da mulher durante a gestação é de 10 - 20%","B":"A suplementação de ferro aumenta o volume da massa eritrocitária em 30%","C":"Devido ao fato do volume plasmático aumentar mais rápido que o número de hemácias, o\nhematócrito materno cai por volta de 30 semanas","D":"O volume sanguíneo materno começa a aumentar por volta da 6ª semana de gestação,\naumentando progressivamente até 30 a 34 semanas, quando se\nmantém estável até o termo da\ngestação"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-187802","number":"187802","sourceNumber":"187802","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 32 anos, com quadro de hipertensão arterial crônica grave, controlada\ncom uso de Captopril, consulta o obstetra\npara orientações pré-concepcionais. No que diz respeito\nao tratamento da hipertensão, qual medida deve ser tomada, antes da concepção?","options":{"A":"Acrescentar um diurético","B":"Interromper o uso do anti-hipertensivo","C":"Substituir o Captopril por Losartana","D":"Substituir o Captopril por Metildopa"},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-181284","number":"181284","sourceNumber":"181284","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação à Síndrome do Anticorpo Antifosfolipídeo (SAF), assinale a alternativa\nCORRETA.","options":{"A":"A trombocitopenia não é um achado comum.","B":"A manifestação mais comum da SAF é a trombose arterial cerebral.","C":"A trombose venosa superficial é considerada um dos critérios para SAF.","D":"O anticorpo anticardiolipina apresenta maior especificidade do que o anticorpo anticoagulante\nlúpico para o diagnóstico de SAF.","E":"O abortamento espontâneo recorrente é uma das manifestações mais importantes e se deve à\noclusão de vasos uteroplacentários."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-187843","number":"187843","sourceNumber":"187843","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 19 anos de idade, G1P0, com 29 semanas de gestação com PA de\n160/110 mmHg, proteinúria de 4+, com história\nde dor epigástrica há dois dias. Negava cefaléia ou\ndistúrbios visuais. Os exames laboratorias mostravam um Hemoglobina de 13mg/dL, Contagem de\nPlaquetas de 130.000/mL e uma elevação acentuada das enzimas hepáticas. Duas horas após ter\ntido um parto normal, a paciente queixa-se de dor abdominal intensa, e apresenta um episódio de\nsíncope. Neste momento, a PA é de 80/60 e a FreqUência cardíaca é de 140bpm. Qual é o\ndiagnóstico MAIS PROVÁVEL E A CONDUTA?","options":{"A":"Coagulopatia - Transfusão de plasma sanguíneo","B":"Hipotonia uterina - Histerectomia","C":"Laceração genital - Revisão do canal do parto","D":"Rotura hepática - Transfusão sanguínea e Laparotomia exploradora de emergência"},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-180153","number":"180153","sourceNumber":"180153","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Qual a droga de escolha na crise convulsiva em gestantes com eclampsia","options":{"A":"Fenobarbital","B":"Fenitoína","C":"Diazepam","D":"Sulfato de magnésio","E":"Hidantal"},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-181298","number":"181298","sourceNumber":"181298","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante do primeiro trimestre revela IgM reagente para Rubéola. Qual a\nprobabilidade de que o feto venha a apresentar a Síndrome da Rubéola Congênita?","options":{"A":"Menos de 10%.","B":"40 a 45%.","C":"50 a 60%.","D":"75 a 80%.","E":"98 a 100%."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-183052","number":"183052","sourceNumber":"183052","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em paciente com Eclampsia Refratária ao tratamento com Sulfato de Magnésio, a\nconduta subsequente é:","options":{"A":"Iniciar tratamento com fenilhidantoina endovenosa.","B":"Iniciar Diazepam endovenoso.","C":"Iniciar Carbamazepina endovenosa.","D":"Iniciar Hidralazina endovenosa."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182782","number":"182782","sourceNumber":"182782","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante referindo aumento discreto do sono durante a gravidez, comparece ao\npré-natal com exame de TSH = 3,8mU/l. O diagnóstico e conduta são, respectivamente:","options":{"A":"Hipotiroidismo Subclínico = tratar com levotiroxina.","B":"Hipotiroidismo Clínico = tratar com levotiroxina.","C":"Hipertiroidismo Subclínico = tratar com propiltiouracil.","D":"Eutiroidismo = nada a fazer."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-183059","number":"183059","sourceNumber":"183059","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A presença de Incisura Protodiastólica de artérias uterinas bilateral é considerada de\nbaixo risco para restrição de crescimento fetal intra-uterino quando presente até:","options":{"A":"12 semanas","B":"26 semanas","C":"16 semanas","D":"20 semanas"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182791","number":"182791","sourceNumber":"182791","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 36 semanas com Síndrome HELLP, contagem de plaquetas 45.000/ml. Em\nrelação ao quadro clínico, a melhor opção anestésica, neste caso, é:","options":{"A":"Anestesia geral.","B":"Peridural.","C":"Raquidiana.","D":"Local."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-182799","number":"182799","sourceNumber":"182799","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"São complicações esperadas em partos de fetos macrossômicos, EXCETO:","options":{"A":"Distocia de ombro","B":"Síndrome de Bandl-Frommel","C":"Lesão de plexo braquial no parto","D":"Descolamento prematuro de placenta"},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-181366","number":"181366","sourceNumber":"181366","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"No rastreamento da Diabetes na gravidez, o período gestacional ideal para se realizar o\nTeste Oral de Tolerância à Glicose simplificado é entre","options":{"A":"28 e 32 semanas de gravidez.","B":"24 e 28 semanas de gravidez.","C":"20 e 24 semanas de gravidez.","D":"18 e 22 semanas de gravidez.","E":"16 e 20 semanas de gravidez."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-152675","number":"152675","sourceNumber":"152675","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em recém-nascidos de diabéticas não controladas, observa-se maior tendência a:","options":{"A":"Hipocalcemia e hipofosfatemia.","B":"Hipocalcemia e hiperfosfatemia.","C":"Hiperalcemia e hipofosfatemia.","D":"Hipercalcemia e hiperfosfatemia.","E":"Normocalcemia e normofosfatemia."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-152642","number":"152642","sourceNumber":"152642","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Qual a droga de escolha na crise convulsiva da eclâmpsia?","options":{"A":"Fenobarbital.","B":"Diazepam.","C":"Hidantoína.","D":"Sulfato de magnésio.","E":"Prometazina."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161127","number":"161127","sourceNumber":"161127","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Apresenta enorme importância preventiva o adequado diagnóstico e tratamento de\ngestantes com diabetes. Em referência a isso, aponte a alternativa considerada INCORRETA.","options":{"A":"Gestantes com diabetes apresentam risco aumentado de aborto espontâneo.","B":"Gestantes com diabetes apresentam risco aumentado de malformação congênita fetal.","C":"A magnitude destes riscos depende, principalmente, do grau de controle metabólico do diabetes\nno período pré-concepcional e no último\ntrimestre da gestação.","D":"A mulher diabética que pretende engravidar deve ser encorajada a obter o melhor controle\nmetabólico possível antes e durante a gestação."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161311","number":"161311","sourceNumber":"161311","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a opção que informa, em relação à eclampsia, a substância a ser prescrita\ncomo anticonvulsivante e seu respectivo antídoto no\ncaso de superdosagem.","options":{"A":"Hidrato de cloral e bicarbonato de cálcio.","B":"Sulfato de magnésio e carbonato de sódio.","C":"Sulfato de magnésio e gluconato de cálcio.","D":"Hidrato de cloral e gluconato de cálcio."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161312","number":"161312","sourceNumber":"161312","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 18 semanas, em consulta de pré-natal, traz resultado de exame com\nhemoglobina de 11,0 mg/dL e hematócrito de 35%. Quanto à suplementação de ferro, é CORRETO\nafirmar que","options":{"A":"deve ser iniciada.","B":"não se faz necessária nesse caso.","C":"deve ser iniciada somente se o nível socioeconômico da paciente for baixo.","D":"deve ser iniciada se a hemoglobina for menor que 11 mg/dL após novo exame."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161204","number":"161204","sourceNumber":"161204","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação ao diabete mellitus gestacional, marque a opção INCORRETA.","options":{"A":"A intolerância aos carboidratos é diagnosticada pela primeira vez durante a gestação.","B":"Valores acima de 105 mg/dL, em duas aferições, também fecham o diagnóstico de diabetes\nmellitus franco (pré-gestacional).","C":"Muitas vezes representa o aparecimento do diabetes mellitus tipo 2 durante a gravidez.","D":"No início do pré-natal, glicemia de jejum em valores iguais ou maiores que 126 mg/dL\ndiagnostica o diabetes pré-gestacional."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161345","number":"161345","sourceNumber":"161345","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em mulheres com infecção urinária, uma ferramenta valiosa no exame de urina é a\navaliação da presença de Nitrito. Assinale a alternativa CORRETA.","options":{"A":"Em seu metabolismo as bactérias irão converter o nitrito em nitrato.","B":"A desvantagem do método é que ele não identifica a presença de patógenos gram-positivos.","C":"Não há necessidade de se colher a primeira urina da manhã, bastando a paciente permanecer\npor 1 hora sem urinar antes da coleta.","D":"Por ser um teste complexo e caro, poucos laboratórios disponibilizam para seus pacientes."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161336","number":"161336","sourceNumber":"161336","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante inicia pré-natal e diz ser diabética tipo I (faz uso de insulina NPH 40 UI dia).\nEncontra-se na oitava semana de gestação. Desse modo, é INCORRETO dizer que:","options":{"A":"no início do pré-natal deve ser solicitado dosagem de Hemoglobina Glicosilada (HbA1C) com a\nfinalidade de rastrear malformações fetais.","B":"será solicitado o GTT 3h com 75 g de glicose para confirmar o tipo de diabetes.","C":"dieta específica para diabetes sempre fará parte da rotina de seguimento dessa paciente.","D":"exercícios físicos leves devem ser estimulados durante todo o acompanhamento pré-natal."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-158793","number":"158793","sourceNumber":"158793","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Dadas as afirmativas em relação a diabetes e gestação,; I. Fetos de gestantes\ndiabéticas tipo I com vasculopatia\ndiabética apresentam maior risco de macrossomia fetal quando\ncomparados às diabéticas gestacionais.; II. O uso metformina na gestação deve ser evitado devido\nà grande incidência de más-formações fetais, principalmente faciais e do sistema nervoso central\nquando utilizada no primeiro trimestre.; III. Gestante apresenta glicemia de jejum no primeiro\ntrimestre de 89 mg/dl, sem fatores de risco para diabetes gestacional. Nesse caso, foi utilizado\nteste\nde tolerância à glicose 75 g com 24 semanas de gestação e os seguintes resultados: Jejum ? 88\nmg/dl; 1 h após ingestão ? 174 mg/dl; 2 h após ingestão ? 139 mg/dl. Conforme esses resultados, o\npaciente não preenche critérios para diabetes gestacional. Verifica-se que está(ão) correta(s)","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e III, apenas.","E":"I, II e III."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161369","number":"161369","sourceNumber":"161369","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Na gravidez, assinale a alternativa contendo o micro-organismo mais comum na\ninfecção urinária:","options":{"A":"Proteus mirabilis.","B":"Escherichia coli.","C":"Klebsiella pneumoniae.","D":"Streptococcus SP."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161385","number":"161385","sourceNumber":"161385","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a alternativa que apresenta a cardiopatia materna com pior prognóstico (para\na mãe) na gestação:","options":{"A":"Síndrome de Eisenmenger.","B":"Defeito de septo interventricular.","C":"Estenose mitral.","D":"Síndrome de Wolf-Parkinson-white."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-161399","number":"161399","sourceNumber":"161399","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a alternativa que apresenta as complicações da Doença Hipertensiva\nEspecífica da Gestação (DHEG):","options":{"A":"Hidropsia fetal não imune e gestação molar.","B":"Eclâmpsia e descolamento prematuro de placenta.","C":"Glomerulonefrite e amniorrexe prematura.","D":"Amnionite e descolamento prematuro de placenta."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-131343","number":"131343","sourceNumber":"131343","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação à gestação múltipla, assinale a alternativa CORRETA:","options":{"A":"Os gêmeos dizigóticos são sempre de sexos diferentes.","B":"A incidência de toxemia é a mesma de uma gestação com feto único.","C":"A dizigotia pode condicionar ovos dicoriônicos, monoamnióticos.","D":"Nos ovos monozigóticos ocorrem, frequentemente, anastomoses entre as duas circulações\nfetoplacentárias.","E":"As alternativas b e d estão corretas."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-131348","number":"131348","sourceNumber":"131348","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"É INCORRETO afirmar em relação à diabetes gestacional:","options":{"A":"O maior fator para morte materna é o controle inadequado do diabetes.","B":"A diabetes descompensada acarreta, no feto, um maior acúmulo de gorduras e glicogênio.","C":"Após o nascimento, o recém-nascido macrossômico apresenta alto risco de desenvolver\nhipoglicemia.","D":"Na diabetes gestacional, o feto apresenta maior risco de apresentar malformações que em uma\ngestação normal.","E":"Na diabetes gestacional existe maior risco de polidramnia e macrossomia fetal"},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-131354","number":"131354","sourceNumber":"131354","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Na gestação gemelar a associação mais frequente entre os fetos é:","options":{"A":"Dois cefálicos.","B":"Primeiro cefálico e o segundo pélvico.","C":"Primeiro pélvico e o segundo cefálico.","D":"Os dois pélvicos.","E":"Primeiro cefálico e o segundo transverso."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-131359","number":"131359","sourceNumber":"131359","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"São drogas utilizadas no tratamento da doença hipertensiva específica da gestação,\nexceto:","options":{"A":"Hidralazina.","B":"Hidroclorotiazida.","C":"Sulfato de magnésio.","D":"Diazepan.","E":"Pindolol."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-131388","number":"131388","sourceNumber":"131388","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A principal causa de mortalidade materna no nosso meio é decorrente de:","options":{"A":"Diabetes gestacional.","B":"Síndrome hipertensiva na gestação.","C":"Infecções.","D":"Placenta prévia.","E":"Cardiopatias."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134096","number":"134096","sourceNumber":"134096","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Segundo os novos critérios adotados pelo ADA 2011(American Diabetes Association),\npara fazer o diagnóstico do diabetes gestacional\nem gestante euglicêmica, faremos:","options":{"A":"o TTG 100 g, entre 24-28 semanas de gestação.","B":"o TTG 50 g, entre 24-28 semanas de gestação.","C":"o TTG 75 g, entre 24-28 semanas de gestação.","D":"o TTG 50 g, entre 10-14 semanas de gestação."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134065","number":"134065","sourceNumber":"134065","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 36 semanas dá entrada no Pronto-socorro apresentando convulsões\ntônico-clônicas, pressão arterial de 170 x 120 mmHg e Labstix revelando proteinúria (+++). A\nMELHOR conduta é:","options":{"A":"Pesquisar maturidade fetal e, se presente, interromper a gestação.","B":"Cesárea imediata.","C":"Administrar sulfato e hipotensor de ação rápida e estabilizar o quadro clínico e, em seguida,\ninterromper a gestação.","D":"Administrar fluidos em grande quantidade para reverter a hipovolemia e, em seguida,\ninterromper a gestação."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134839","number":"134839","sourceNumber":"134839","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher de 30 anos, primigesta, gestação 20 semanas, obesa, sem patologias,\nassintomática, tendo ganho de peso de 8 kg durante a gestação, apresentando exames de\n\npré-natal normais. Qual exame deve ser feito durante a gestação para investigação de diabetes\ngestacional?","options":{"A":"Glicemia de jejum a partir de 24 semanas.","B":"Teste de tolerância à glicose de 50 g com 20 semanas.","C":"Teste de tolerância à glicose de 75 g com 20 semanas.","D":"Teste de tolerância à glicose 75 g a partir de 24 semanas."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134129","number":"134129","sourceNumber":"134129","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 18 anos, primigesta, com 26 semanas de gestação, vem para consulta de\npré-natal queixando de desconforto em baixo ventre, disúria, polaciúria, urina escura, com odor\nforte, nega febre e perdas. Qual é o PRINCIPAL agente etiológico para esse caso?","options":{"A":"Proteus sp.","B":"Klebsiella sp.","C":"E. coli.","D":"Micoplasma."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134132","number":"134132","sourceNumber":"134132","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 28 anos, obesa, filha de mãe diabética, chega a consulta de pré-natal com\n22 semanas de gestação e exame de glicose no\nsangue de 98 mg/dl. Em relação ao diabetes\ngestacional, segundo estudo Whapo e ADA 2011, aponte a afirmativa CORRETA.","options":{"A":"Gestantes com glicemia de jejum > 126 mg/dl no início da gestação não são\nconsideradas diabéticas pré-gestacional e sim\n\ndiabéticas gestacionais.","B":"No puerpério de 42 dias não é necessário realizar TTG 75 g para as pacientes com diabetes\ngestacional.","C":"O TTG 75 g está indicado para as gestantes que tiveram glicemias de jejum < 92 mg/dl no início\nda gestação.","D":"O TTG 50 g está indicado para o diagnóstico do diabetes gestacional entre 24-28 semanas de\ngestação."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134325","number":"134325","sourceNumber":"134325","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação ao diabetes gestacional, segundo ADA 2011, assinale a afirmativa\nCORRETA.","options":{"A":"Pacientes com glicemia de jejum>126 mg/dl no início da gestação, não são consideradas\ndiabéticas pré-gestacional e sim\n\ndiabetes gestacional.","B":"O TTG 75 g está indicado para as gestantes que tiveram glicemias de jejum < 92 mg/dl, no início\nda gestação.","C":"O TTG 50 g está indicado para o diagnóstico do diabetes gestacional entre 24-28 semanas de\ngestação.","D":"Gestante com glicemia de jejum entre 92 e 126 mg/dl é considerada euglicêmica."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-110603","number":"110603","sourceNumber":"110603","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação à diabetes gestacional, é INCORRETO afirmar:","options":{"A":"O maior fator para mortalidade materna é o\ncontrole inadequado da diabetes.","B":"A diabetes descompensada acarreta, no feto, um\nmaior acúmulo de gorduras e glicogênio.","C":"Após o nascimento, o recém-nascido macrossômico apresenta alto risco de desenvolver\nhipoglicemia.","D":"Na diabetes gestacional, o feto apresenta maior\n\nrisco de apresentar malformações que em uma gestação normal.","E":"Na diabetes gestacional existe maior risco de\npolidrâmnia e macrossomia fetal."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-110607","number":"110607","sourceNumber":"110607","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O valor de referência para o rastreamento do Diabetes Gestacional no pré-natal através\ndo TOTG (Teste Oral de Tolerância à Glicose)\né de:","options":{"A":"100 mg/dl.","B":"120 mg/dl.","C":"140 mg/dl.","D":"160 mg/dl.","E":"200 mg/dl."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-110529","number":"110529","sourceNumber":"110529","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à gestação múltipla:","options":{"A":"Os gêmeos dizigóticos são sempre de sexos diferentes.","B":"A incidência de toxemia é a mesma de uma gestação com feto único.","C":"A dizigotia pode condicionar ovos dicoriônicos, monoamnióticos.","D":"Nos ovos monozigóticos ocorrem, frequentemente, anastomoses entre as duas circulações\nfeto-placentárias.","E":"Na gestação múltipla, a possibilidade de ocorrer diabetes gestacional é menor que em uma\ngestação única."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-110036","number":"110036","sourceNumber":"110036","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 35 semanas, com aumento de peso, edema de mãos, face e MMII e PA\n180X120 mmHg, associada à cefaleia, escotomas\ne epigastralgia. Qual é a associação de fármacos\nconsiderada a MAIS adequada?","options":{"A":"Fenitoína e Verapamil.","B":"Sulfato de magnésio e Nitroprussiato de sódio.","C":"Diazepan e Nifedipina.","D":"Sulfato de magnésio e Hidralazina."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-109978","number":"109978","sourceNumber":"109978","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Qual é o teste MAIS indicado para a Confirmação do Diabetes Mellitus Gestacional,\nentre 24-28 semanas de gestação?","options":{"A":"Teste de Glicemia de jejum.","B":"Teste de Tolerância, usando-se 75 g de glicose.","C":"Teste de Glicosúria urinária.","D":"Teste de Tolerância, usando-se 50 g de glicose."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-109982","number":"109982","sourceNumber":"109982","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Qual dos antecedentes abaixo NÃO merece consideração em relação ao Diabetes\nGestacional?","options":{"A":"Antecedente obstétrico de macrossomia fetal.","B":"Antecedente familiar de Diabetes.","C":"Óbito fetal no 3° trimestre sem causa aparente em gestação anterior.","D":"Trabalho de parto prematuro em gestação anterior."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-86836","number":"86836","sourceNumber":"86836","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O principal risco de óbito fetal depois de 20 semanas é:","options":{"A":"Diminuição da titulagem da Gonadotrofina\nCoriônica Humana (hCG);","B":"Alergias sistêmicas;","C":"Coagulopatias;","D":"Toxemia;","E":"Embolia."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-86847","number":"86847","sourceNumber":"86847","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente com pré-eclâmpsia grave apresentam uma diminuição:","options":{"A":"No volume plasmático;","B":"No sódio corporal total;","C":"No ácido úrico;","D":"Na prova de função hepática;","E":"Da frequência cardíaca."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-86651","number":"86651","sourceNumber":"86651","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a opção que se presume que estejam alterados os parâmetros abaixo em\nmulheres pré-eclâmpticas:","options":{"A":"Óxido nítrico aumentado e tromboxano diminuído.","B":"Prostaciclina diminuída e óxido nítrico diminuído.","C":"Tromboxano aumentado e óxido nítrico aumentado.","D":"Prostaciclina aumentada e tromboxano diminuído.","E":"Tromboxano aumentado e prostaciclina aumentada."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-158415","number":"158415","sourceNumber":"158415","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 42 anos, foi submetida a parto cesariana por iteratividade, durante a\ndequitação manual, a paciente apresentou quadro de dispneia importante, cianose e hipotensão\narterial. Mesmo após os procedimentos iniciais da equipe médica, a paciente evoluiu com parada\ncardiorrespiratória. Qual a hipótese mais provável?","options":{"A":"Atonia uterina.","B":"Infarto agudo do miocárdio.","C":"Embolia amniótica.","D":"Acidente vascular cerebral.","E":"Embolia gordurosa."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108594","number":"108594","sourceNumber":"108594","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Na pré-eclâmpsia observa-se que a produção de endotelina e prostaciclina encontra-se,\nrespectivamente:","options":{"A":"Diminuída e aumentada.","B":"Aumentada e inalterada.","C":"Aumentada e diminuída.","D":"Inalterada e diminuída.","E":"Diminuída e inalterada."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49607","number":"49607","sourceNumber":"49607","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"São indicadores de pré-eclâmpsia grave, EXCETO:","options":{"A":"Proteinúria maior que 2 g/24hrs.","B":"Dor epigástrica ou em hipocôndrio direito.","C":"Creatinina sérica maior que 1,2 mg%.","D":"Anemia hemolítica microangiopática.","E":"Pressão arterial maior que 140x100."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49610","number":"49610","sourceNumber":"49610","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"São fatores de risco para diabetes mellitus gestacional, EXCETO:","options":{"A":"Hipertireoidismo.","B":"Síndrome dos ovários policísticos.","C":"Obesidade.","D":"Perdas gestacionais de repetição.","E":"Hipertensão arterial sistêmica."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49589","number":"49589","sourceNumber":"49589","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A lesão renal mais associada à eclâmpsia é:","options":{"A":"Edema glomerular endotelial.","B":"Pielonefrite.","C":"Necrose medular.","D":"Necrose cortical.","E":"Necrose tubular aguda."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-13120","number":"13120","sourceNumber":"13120","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Nas eritrofalcêmicas em grávidas, visando reduzir os riscos dos acidentes por anoxia,\nestá indicado no 3º trimestre:","options":{"A":"Interrupção da gestação.","B":"Transfusões de sangue.","C":"Uso de ferro por via intravenosa.","D":"Uso de ferro intravenoso + concentrado de hemácias.","E":"Alternativa A e B estão corretas."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-13121","number":"13121","sourceNumber":"13121","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A lesão renal própria da doença hipertensiva específica da gravidez é no(a):","options":{"A":"Alça de Hende.","B":"Glomérulo.","C":"Tubo proximal.","D":"Tubo distal.","E":"Não há lesão renal na DHEG."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-327274","number":"327274","sourceNumber":"327274","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Qual tratamento deve ser iniciado em gestante de 20 semanas com diagnóstico de\nmalária não grave por P. vivax","options":{"A":"Primaquina","B":"Tafenaquina","C":"Cloroquina","D":"Artesunato"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-327278","number":"327278","sourceNumber":"327278","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante primigesta, foi a consulta de pré-natal para mostrar exame de ultrassonografia\ndo primeiro trimestre que evidenciou índice de\npulsatilidade das artérias uterinas acima do percentil\n\n95. O risco calculado para pré eclampsia pelo algoritmo da Fetal Medicine Foundation foi 1:100.\n\nAssinale conduta mais adequada para o caso.","options":{"A":"Iniciar nifedipina 40 mg.","B":"Reavaliar com 20 semanas.","C":"Realizar Monitorização da Pressão Arterial.","D":"Iniciar acido acetil salicílico 150 mg a noite."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-327280","number":"327280","sourceNumber":"327280","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O exame obstétrico de uma gestante de 20 semanas evidenciou altura uterina no\napêndice xifóide. Qual das alternativas podem ser responsáveis por esse achado?","options":{"A":"Diabetes gestacional","B":"Insuficiência placentária","C":"Doença Hipertensiva específica da gravidez","D":"Síndrome de Prunny Belly"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-298277","number":"298277","sourceNumber":"298277","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma das principais intercorrências clínicas em gestantes acompanhadas pelo médico\nde família e comunidade é a infecção urinária.\nSobre o manejo de ITU em gestantes no âmbito da\nAPS podemos afirmar que:","options":{"A":"Dois ou mais episódios de ITU durante a gravidez caracterizam quadro de ITU repetição.","B":"A primeira escolha de tratamento de ITU gestacional é o sulfametoxazol/trimetoprim.","C":"Bacteriúria assintomática diagnosticada após a 36a. Semana de gravidez deve ser tratada com\nnitrofurantoína.","D":"Cultura de urina com contagem de colônias acima de 10.000 (dez mil) UFC/ml é suficiente para\ndiagnosticar bacteriúria assintomática em gestantes sem queixas urinárias."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-256601","number":"256601","sourceNumber":"256601","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente GII PI(PN), retorna à consulta de pré natal com o seguinte resultado do TOTG\n\n: 92 mg/dl em jejum; 157 mg/dl na 1ª hora e 145 mg/dl na 2ª hora. Sobre esse resultado pode-se\nafirmar que:","options":{"A":"A paciente fecha critérios para o diagnóstico de Diabetes mellitus gestacional.","B":"A paciente precisaria de mais 1 valor alterado para fechar o diagnóstico de Diabetes mellitus\ngestacional.","C":"A paciente não fecha critérios para o diagnóstico de Diabetes mellitus gestacional.","D":"A paciente precisará repetir o exame."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-252248","number":"252248","sourceNumber":"252248","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante foi ao Pré-natal com o resultado de glicemia de jejum de 110 mg/dl. Qual\ndiagnóstico deve ser dado pelo obstetra segundo os critérios da International Association of\nDiabetes and Pregnancy?","options":{"A":"Diabetes pré gestacional.","B":"Euglicemia.","C":"Diabetes Melitus Gestacional.","D":"Necessita de exames complementares para fechar o diagnóstico."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-252251","number":"252251","sourceNumber":"252251","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante 33 semanas foi internada pois estava com PA 160 x 120 mmHg, plaquetas\n90.000, transaminases elevadas e creatinina 2,1\nmg/dl. Qual a conduta deve ser adotada?","options":{"A":"Internação, hipotensor e interrupção da gestação após estabilização do quadro.","B":"Internação e Interrupção imediata da gestação.","C":"Hipotensor e avaliação da vitalidade fetal com Doppler.","D":"Corticoterapia e Doppler para avaliar a vitalidade fetal."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-252252","number":"252252","sourceNumber":"252252","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante 12 semanas, realizou Doppler de artérias uterinas que estava com alta\nresistência. Qual a conduta adequada nesse caso:","options":{"A":"Repetir o exame com 20 semanas.","B":"Iniciar hipotensor.","C":"Iniciar ácido acetilsalicílico 100 mg/dia.","D":"Solicitar glicemia."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-208345","number":"208345","sourceNumber":"208345","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Luiza, 19 anos, primigesta na 38a. semana de gravidez, comparece a uma consulta na\nUBS com queixa de disúria e polaciúria. Traz\numa exame de urina realizado no dia anterior o qual\napresenta incontáveis piócitos. Podemos recomendar o uso dos seguintes antibióticos no\ntratamento da cistite aguda nesta paciente, EXCETO:","options":{"A":"Ampicilina","B":"Cefalexina","C":"Nitrofurantoína","D":"Amoxicilina/clavulanato"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-152007","number":"152007","sourceNumber":"152007","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"AGB, 26 anos, gestante com 11 semanas foi levada ao pronto socorro pelo SAMU com\nvômitos incoercíveis há 3 dias. Devido aos vômitos, está impossibilitada de responder a anamnese\nadequadamente. A acompanhante refere apenas perda de peso. Ao exame físico está desidratada,\ncom hemorragia retiniana. Qual o tratamento mais adequado para a paciente:","options":{"A":"Internação, dieta hipocalórica, hidratação com soro glicofisiológico, observar diurese,\nprescrever\nmetoclopramida, sedativos e psicoterapia.","B":"Internação, jejum por 24-48 horas, hidratação com soro glicofisiológico, observar diurese,\nprescrever metoclopramida, sedativos e psicoterapia.","C":"Orientação dietética, hidratação com soro caseiro, observar diurese, prescrever metoclopramida\ne sedativos","D":"Orientação dietética, hidratação com soro caseiro, observar diurese, rescrever metoclopramida,\nsedativos e psicoterapia."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-152029","number":"152029","sourceNumber":"152029","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"As gestações múltiplas estão associadas com aumento de todas as complicações, incluindo o\npós datismo e a macrossomia fetal.","B":"A síndrome da transfusão feto-fetal é complicação específica e exclusiva das gestações\ndicoriônicas, ocorrendo em cerca de 10 a 15% dessas.","C":"O melhor período para a determinação da corionicidade e da amnionicidade é durante o\nsegundo trimestre da gestação, quando a acurácia\ndo exame ultrassonográfico chega a 100%.","D":"O conhecimento da corionicidade de uma gestação múltipla é quesito importante para proceder\nao aconselhamento do casal quanto aos riscos\nenvolvidos na gestação, além de ter fundamental\nimportância para o manejo adequado dessas gestações."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-129801","number":"129801","sourceNumber":"129801","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação à Doença Hipertensiva Específica da Gestação (DHEG) é CORRETO\nafirmar:","options":{"A":"A maioria das gestantes em fase inicial já apresenta algum sintoma.","B":"O diagnóstico de DHEG deve ser presumido nas gestantes com hipertensão arterial, edema e/ou\nproteinúria significativa antes de 20 semanas de gestação.","C":"A dosagem de ácido úrico sérico é importante para o clínico, pois sua elevação ocorre\nprecocemente na DHEG e pode estar relacionada à\nqueda da filtração glomerular ou a alterações\nde reabsorção e excreção tubular.","D":"O diagnóstico de hipertensão arterial é feito diante de níveis de pressão arterial sistólica =\n145\nmmHg e/ou pressão arterial diastólica = 100\nmmHg."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-103842","number":"103842","sourceNumber":"103842","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"No diagnóstico da hipertensão na gravidez o que caracteriza o diagnóstico de certeza\nde pré-eclâmpsia:","options":{"A":"Proteinúria de \"maior ou igual a\" 2g /24 horas.","B":"PA \"maior ou igual a\" 140x90 mmHg antes da gravidez.","C":"PA \"maior ou igual a\" 160x110.","D":"Plaquetas \"menor que\" 100.000ug/ml."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-80975","number":"80975","sourceNumber":"80975","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente 32 semanas de gestação chega à maternidade com PA: 180 x 130 mmHg e\nturvação visual. Na propedêutica laboratorial, além de dosagem de proteinúria de 24 horas,\ndeverão ser solicitados no momento de sua internação:","options":{"A":"eletrólitos, bilirrubina, coagulograma, glicemia, fundo de olho e urinocultura.","B":"Transaminases, hemograma, fosfatase alcalina, urinocultura e colpocitologia.","C":"Provas de função renal, glicemia, fosfatase alcalina, hemograma completo, urinocultura.","D":"Hemograma, hematoscopia, provas de função hepática, coagulograma e urina tipo 1.","E":"Glicemia, provas de função renal, transaminases e fundo de olho, rotina de Kramer."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-80985","number":"80985","sourceNumber":"80985","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 30 anos, com 28 semanas de gestação, apresenta ao exame de\nrotina, glicemia de 162 mg/dl uma hora após a ingestão de dextrose. Qual a melhor conduta:","options":{"A":"Solicitar curva glicêmica.","B":"Instituir dieta e após 3 semanas solicitar perfil glicêmico.","C":"Iniciar hipoglicemiante oral","D":"Iniciar insulina usando a fórmula 0,6 x peso para calcular a dose total diária.","E":"Iniciar insulina usando a fórmula 0,9 x peso para calcular a dose total diária segundo White."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-81946","number":"81946","sourceNumber":"81946","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As opções apresentam critérios de pré-eclâmpsia grave, EXCETO:","options":{"A":"Trombocitopenia","B":"PA maior ou igual a 160 x 110 mmHg, persistente","C":"Ácido úrico elevado","D":"Elevação das enzimas hepáticas","E":"oligúria"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-61510","number":"61510","sourceNumber":"61510","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente 38 anos, gestante na 35ª semana de gestação, deu entrada na maternidade\ncom queixa de cefaleia intensa, dor epigástrica\ne náuseas após ter discutido com a vizinha. Ao\nexame físico estava dispneica com dor epigástrica à palpação. A Pressão Arterial no momento do\nexame era de 160 x 110 mmHg. O exame obstétrico não evidenciava nenhuma anormalidade. A\ncontagem de plaquetas foi de 98000/mm³, a aspartato transaminase foi de 86 UI/I, os níveis de\nalanina transferase foi de 78 UI/I e a bilirrubina era de 1,4 mg/dl. Com base nos dados acima,\nassinale a melhor resposta.","options":{"A":"O diagnóstico provável é: Eclâmpsia, devemos internar e interromper a gestação.","B":"O diagnóstico é: Síndrome HELLP, devemos internar, estabilizar a paciente e interromper a\ngestação.","C":"O diagnóstico provável é: Hipertensão crônica, devemos internar e estabilizar a paciente. Até\ndiminuir sua pressão arterial.","D":"O diagnóstico provável é: Stress pela discussão com a vizinha, devemos conversar para acalmar\na paciente e liberá-la a seguir.","E":"O diagnóstico provável é: Stress pela discussão com a vizinha, devemos internar para acalmar a\npaciente e assim diminuir a pressão da mesma."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-34143","number":"34143","sourceNumber":"34143","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 32 semanas, apresenta cefaleia, alterações visuais, epigastralgia, vômitos,\nhiperreflexia. Ao exame: normocorada, edema de MMII discreto, PA de 160 x110 mmHg, feto único,\ndorso à esquerda, altura uterina compatível, BCF de 152 bpm, ausência de dinâmica uterina.\n\nRefere que não realizou pré-natal, tem 38 anos e esta é sua primeira gestação. As condutas a\nserem tomadas de imediato, EXCETO?","options":{"A":"Acesso venoso.","B":"Sonda vesical.","C":"Esquema de Pritchard para uso do sulfato de magnésio.","D":"Cesariana.","E":"Hidralazina endovenosa."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-26490","number":"26490","sourceNumber":"26490","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A causa mais comum de óbito na Texemia Gravídica é:","options":{"A":"Edema agudo de pulmão.","B":"Hemorragia cerebral.","C":"Ruptura hepática.","D":"Miocardite.","E":"Hepatite."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-26508","number":"26508","sourceNumber":"26508","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Os casos de gemelaridade imperfeita ocorrem em que situações?","options":{"A":"gêmeos monocoriônicos, diamnióticos.","B":"gêmeos dicoriônicos, diamnióticos.","C":"gêmeos dicoriônicos, monoamnióticos.","D":"gêmeos monocoriônicos, monoamnióticos.","E":"em qualquer caso de gemelaridade pode ocorrer gemelaridade imperfeita."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-13249","number":"13249","sourceNumber":"13249","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher jovem com 23 anos, gestante pela 1ª vez, 36 semanas, apresenta-se com\nPressão Arterial = 170 x 110 mmHg na Emergência\nObstétrica e queixa-se de cefaleia, visão turva,\ndiplopia e dor epigástrica. Diante desse quadro qual a hipótese mais provável?","options":{"A":"Quadro clássico de eclâmpsia.","B":"Crise convulsiva iminente.","C":"Acidente vascular cerebral.","D":"Síndrome HELLP.","E":"Iminência de eclampsia."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-9955","number":"9955","sourceNumber":"9955","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Quanto à cirurgia laparoscópica durante a gravidez, é possível afirmar:","options":{"A":"constata-se aumento da morbidade e mortalidade materna e fetal.","B":"é menos segura que a cirurgia aberta.","C":"o segundo trimestre é a época mais segura para sua execução.","D":"tem suas indicações mais restritas que as cirurgias abertas.","E":"tem grande associação com aborto e trabalho de parto prematuro."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-7477","number":"7477","sourceNumber":"7477","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Dos fatores abaixo citados qual não exibe correlação com a diabetes gestacional?","options":{"A":"Idade materna inferior a 25 anos.","B":"História de mal formação fetal.","C":"Antecedente de óbito fetal.","D":"Aumento do volume de líquido amniótico.","E":"Macrossomia fetal."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-7486","number":"7486","sourceNumber":"7486","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 32 semanas de idade gestacional foi internada com pressão arterial de\n160/110 mmHg (após 30 minutos de repouso) e sintomas de cefaleia e escotomas. Trouxe exame\nde proteinúria de 3 g em 24 horas. À cardiotocografia, o feto mostrou-se reativo. Foi realizada\namniocentese, a qual revelou teste de Clements positivo. Qual a conduta mais adequada?","options":{"A":"Administrar sulfato de magnésio, hidralazina ou nifedipina e interromper a gestação.","B":"Administrar benzodiazepínico intravenoso e realizar cesariana imediatamente.","C":"Administrar nitroprussiato de sódio e realizar cesariana a seguir.","D":"Administrar hidantoína e corticosteroides e realizar cesariana.","E":"Administrar corticosteroide, repetir a amniocentese e, se o feto apresentar maturidade,\ninterromper a gestação."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-324683","number":"324683","sourceNumber":"324683","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher admitida em maternidade com gestação de 34 semanas e 2 dias, referindo\ncefaleia. Ao exame físico: PA: 170x110mmHg.\nDinâmica uterina ausente, vitalidade fetal\npreservada; colo uterino fechado. Solicitados exames laboratoriais que evidenciaram: AST: 80UI,\nHb: 10,5 mg/dL, Plaquetas: 92.000, LDH: 650U/L, bilirrubinas: 1,3mg/dL e proteinúria ++.\n\nConsiderando esses dados clínicos, indique o diagnóstico mais provável:","options":{"A":"Eclampsia.","B":"Pré-eclampsia.","C":"Síndrome HELLP.","D":"Esteatose aguda da gravidez."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-324684","number":"324684","sourceNumber":"324684","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher admitida em maternidade com gestação de 34 semanas e 2 dias, referindo\ncefaleia. Ao exame físico: PA: 170x110mmHg.\nDinâmica uterina ausente, vitalidade fetal\npreservada; colo uterino fechado. Solicitados exames laboratoriais que evidenciaram: AST: 80UI,\nHb: 10,5 mg/dL, Plaquetas: 92.000, LDH: 650U/L, bilirrubinas: 1,3mg/dL e proteinúria ++. Indique a\nconduta imediata para o caso:","options":{"A":"Sulfato de magnésio, hidralazina e interrupção da gestação.","B":"Sulfato de magnésio, hidralazina e avaliar perfil biofísico fetal para decidir sobre interrupção\nda\ngestação.","C":"Hidralazina e acompanhamento, dispensando uso de sulfato de magnésio se houver correção\nda PA.","D":"Sulfato de magnésio e hidralazina, com liberação para acompanhamento ambulatorial se houver\ncorreção da PA."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-324685","number":"324685","sourceNumber":"324685","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher admitida em maternidade com gestação de 34 semanas e 2 dias, referindo\ncefaleia. Ao exame físico: PA: 170x110mmHg.\nDinâmica uterina ausente, vitalidade fetal\npreservada; colo uterino fechado. Solicitados exames laboratoriais que evidenciaram: AST: 80UI,\nHb: 10,5 mg/dL, Plaquetas: 92.000, LDH: 650U/L, bilirrubinas: 1,3mg/dL e proteinúria ++. Identifique\na principal causa de óbito materno nesses casos:","options":{"A":"Ruptura hepática.","B":"Sangramento pós-parto por atonia uterina.","C":"Hemorragia cerebral (AVC hemorrágico).","D":"Intoxicação por sulfato de magnésio."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-62853","number":"62853","sourceNumber":"62853","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Adolescente, 15 anos de idade, tabagista, apresenta quadro de vulvovaginite e ITU\nrecorrente. Não adere ao tratamento\nfarmacológico. Inicia o acompanhamento pré-natal e obstetra\na orienta sobre um possível aumento na incidência de:","options":{"A":"hipertensão arterial.","B":"diabetes gestacional.","C":"distocia de ombros.","D":"anemia falciforme.","E":"rotura prematura de membranas."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-62806","number":"62806","sourceNumber":"62806","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em multípara, com quatro partos naturais anteriores, apresentando cardiopatia classe\nfuncional I, segundo New York Heart Association, a melhor via de parto é:","options":{"A":"de acordo com a indicação obstétrica.","B":"cesariana eletiva.","C":"vaginal.","D":"vaginal com fórcipe alto.","E":"abortamento terapêutico pelo risco de morte materna."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-62818","number":"62818","sourceNumber":"62818","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, na 25ª semana de gestação, sem fatores de risco, apresenta o seguinte\nresultado: TOTG 75 g, glicemia de jejum: 120 e glicemia de 2 horas: 160. A paciente, segundo a\nOMS, apresenta:","options":{"A":"diagnóstico de diabetes melito tipo 1.","B":"diagnóstico de diabetes melito tipo 2.","C":"diagnóstico de diabetes melito gestacional.","D":"diagnóstico de glicemia alterada de jejum.","E":"exame normal."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-62820","number":"62820","sourceNumber":"62820","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, 18 anos de idade, com 22 semanas de gestação, assintomática, apresenta\nPA 160 x 110 mmHg e proteinúria de 24 horas:\n3g. O diagnóstico provável é de","options":{"A":"hipertensão crônica.","B":"pré-eclâmpsia leve.","C":"pré-eclâmpsia grave.","D":"hipertensão crônica com pré-eclâmpsia superposta.","E":"hipertensão gestacional."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49469","number":"49469","sourceNumber":"49469","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente, com 30 semanas de gestação, apresenta queixa de disúria, polaciúria, febre\ne vômitos. Ao exame, temperatura axilar: 39°C.\nPR: 120 bpm. Sinal de Giordano positivo à direita.\nFundo uterino compatível com idade gestacional. BCF presentes. Metrossístoles ausentes.\n\nUrocultura: 200000 UFC - E.coli. A conduta mais adequada para essa paciente é:","options":{"A":"prescrever antibiótico e antipirético e indicar acompanhamento pré-natal.","B":"prescrever antibiótico e antioirético, apenas.","C":"indicar hidratação venosa e solicitar uricultura de controle.","D":"internar imediamente para resolução do parto.","E":"internar imediatamente e iniciar antibioticoterapia venosa."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49352","number":"49352","sourceNumber":"49352","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, 33 semanas, assintomática, apresenta quadro de edema em MMII,\nassociado à elevação dos níveis pressóricos,\nmantendo média de 140 x 90 mmHg sem uso de\nterapêutica anti-hipertensiva. Apresenta proteinúria de 1+ no sumário de urina. A melhor conduta\npara o caso é:","options":{"A":"Internar para acompanhamento em enfermaria.","B":"Realizar cesariana imediatamente.","C":"Iniciar corticoterapia seguida de cesariana.","D":"Internar para acompanhamento em UTI.","E":"Acompanhar em pré-natal de alto risco, avaliar vitalidade fetal e iniciar metildopa."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49360","number":"49360","sourceNumber":"49360","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, com 16 semanas de gestação, apresenta duas glicemias de jejum acima de\n126 mg%. De acordo com os critérios da OMS, a\npróxima conduta para esse caso é:","options":{"A":"orientar dieta e prática de exercício físico.","B":"realizar TOTG 75 g de dextrosol com 18 semanas.","C":"realizar TOTG 100 g de dextrosol com 18 semanas.","D":"iniciar insulinoterapia.","E":"indicar hipoglicemiante oral."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49274","number":"49274","sourceNumber":"49274","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente, com 40 semanas de gestação, cardiopata, classe funcional I, NYHA, dá\nentrada na maternidade no período expulsivo\ndo trabalho de parto. A melhor conduta, no caso, é","options":{"A":"realizar cesariana imediatamente.","B":"encaminhar para maternidade de alto risco com UTI.","C":"acompanhar como gestante de baixo risco.","D":"aplicar fórcipe de alívio.","E":"realizar cesariana seguida de salpingotripsia."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-49275","number":"49275","sourceNumber":"49275","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Secundigesta, com parto natural anterior, encontra-se em trabalho de parto de uma\ngestação gemelar de 35 semanas. O primeiro feto em apresentação cefálica e o segundo em\napresentação pélvica, pesando, respectivamente, 2200 g e 2300 g. A melhor via de parto, para\nesse caso, é:","options":{"A":"vaginal para os dois fetos.","B":"cesariana.","C":"vaginal para o primeiro feto e cesariana para o segundo feto.","D":"cesariana para o primeiro feto e vaginal para o segundo feto.","E":"de livre escolha."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-34952","number":"34952","sourceNumber":"34952","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, 28 semanas de gestação, assintomática, com PA: 150 X 90 mmHg,\nproteinúria +/4 e edema ++/4. A melhor conduta para o acompanhamento pré-natal é:","options":{"A":"iniciar tratamento com metildopa.","B":"iniciar tratamento com hidroclorotiazida.","C":"iniciar tratamento com captopril.","D":"iniciar tratamento com nifedipina.","E":"orientar apenas dieta hipossódica e controle diário de PA."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-34958","number":"34958","sourceNumber":"34958","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Secundigesta, 16 semanas de gestação, apresenta glicemia de jejum igual a 100 mg/dl.\nNão tem fatores de risco para diabetes. A conduta adequada é:","options":{"A":"realizar TTGO 50 g.","B":"realizar TTGO 100 g.","C":"realizar nova glicemia de jejum.","D":"iniciar tratamento com dieta e insulina.","E":"iniciar tratamento com dieta e hipoglicemiante oral."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-27438","number":"27438","sourceNumber":"27438","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação às síndromes hipertensivas na gravidez, segundo o Colégio\n\nNorte-Americano de Ginecologia e Obstetrícia (ACOG), pode-se afirmar: I. A hipertensão induzida\npela gravidez geralmente inicia antes das 20\nsemanas de gestação. II. Na hipertensão crônica, não\nocorre a segunda onda de migração trofoblástica. III. A hipertensão transitória se desenvolve na\nsegunda metade da gestação e caracteriza-se por elevação leve da pressão arterial, geralmente\nsem impacto na morbimortalidade materno-fetal. A alternativa que contém apenas as assertivas\ncorretas é:","options":{"A":"I.","B":"II.","C":"III.","D":"II e III.","E":"I, II e III."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-27439","number":"27439","sourceNumber":"27439","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"São drogas utilizadas na emergência hipertensiva da gestação:","options":{"A":"nifedipina, hidralazina, alfametildopa.","B":"captopril, nifedipina, hidralazina.","C":"nifedipina, hidralazina, diazóxido.","D":"captopril, nifedipina, pindolol","E":"captopril, furosemida, hidralazina"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-13312","number":"13312","sourceNumber":"13312","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente, 32 anos de idade, G1P0A0, com gestação de 31 semanas, vem ao pré-natal\nreferindo que apresentou palpitações, pele quente, insônia, perda de peso, aumento da tireoide e\nexoftalmia. Traz exames com Ht: 34%, Hb: 11 g%, TSH: 0,001, T4 livre: aumentado.\n\nUltrassonografia obstétrica, IG: 31 semanas e 2 dias, ILA: 95 mm, placenta - grau 1, peso fetal de\n1000 g, apresenta aumento das medidas da\ntireoide fetal. Vem em uso de Propiltiouracil (PTU) 400\nmg/dia. Das drogas utilizadas no tratamento do hipertireoidismo na gestação, a que está\nrelacionada à aplasia cútis, à atresia cloacal e esofágica é:","options":{"A":"metimazol.","B":"propiltiouracil.","C":"propranolol.","D":"lugol forte.","E":"dexametasona."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-11144","number":"11144","sourceNumber":"11144","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, 15 anos de idade, com 35 semanas de gravidez, procura a maternidade\ncom cefaleia, escolomas e pressão arterial de\n150x100 mmHg. A melhor conduta, nesse caso é:","options":{"A":"indicar sulfato de magnésio e aguardar o trabalho de parto espontâneo, na dependência das\nprovas laboratoriais materna e de vitalidade fetal.","B":"indicar sulfato de magnésio e induzir parto ou realizar cesárea, de acordo com as condições\nmaternas.","C":"indicar sulfato de magnésio, corticoterapia, e induzir parto ou realizar cesárea após 24 horas,\nde\nacordo com as condições obstétricas.","D":"não indicar sulfato de magnésio e, sim, promover resolução imediata do caso, por cesárea.","E":"indicar sulfato de magnésio e induzir parto ou realizar cesárea após 24 horas de início do\ntratamento."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-18084","number":"18084","sourceNumber":"18084","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente, 28 anos de idade, G1P0A0, vem ao hospital referindo gestação de 38\nsemanas e ser portadora de síndrome de\nMarfan. Queixa-se de contrações uterinas de 10 em 10\nminutos. Ao exame, colo permeável a 2 cm, BCF: 136 bpm, apresentação cefálica no 1º plano,\nbolsa íntegra. Trouxe ecocardiografia transesofágica, que evidenciava prolapso de válvula mitral e\nraiz aórtica de 47 mm. A melhor conduta, nesse caso, seria:","options":{"A":"Orientar quanto ao período de dilatação e solicitar que retorne mais tarde.","B":"Internar e aguardar trabalho de parto.","C":"Internar e realizar operação cesariana em hospital terciário.","D":"Internar, aguardar trabalho de parto e realizar fórceps.","E":"Internar e deter o trabalho de parto até completar 40 semanas."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-332609","number":"332609","sourceNumber":"332609","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Pamela retorna após 14 dias para consulta de pré-natal, com 27 semanas,\nqueixando-se de dor de cabeça. No último\natendimento, a medida de pressão arterial chamou a\n\natenção do médico. No momento estava 130 X 90 mmHg, porém durante todo o acompanhamento\na paciente apresentou média de pressão arterial\nde 110/70 mmHg. Por esse motivo solicitou o\nmonitoramento da pressão que está descrito a seguir: 140x90, 140x100, 140x90, 140x90, 130x90,\n140x80, 140x90, 150x80, 150x90, 140x90, 120x90, 150x100, 140x90, 140x90. Além de solicitar\n\nhemograma com plaquetas, proteinúria de 24 horas, ácido úrico, creatinina, transaminases\nhepáticas, albumina sérica, desidrogenase láctica,\ntempo de protrombina e tempo de\ntromboplastina parcial ativada, qual alternativa traz as condutas mais adequadas e qual o\ndiagnóstico correto:","options":{"A":"Trata-se de hipertensão crônica na gestação, o tratamento medicamentoso de escolha é\nenalapril 20 mg a cada 12 horas, não havendo necessidade de exame de imagem.","B":"Trata-se de hipertensão gestacional, o tratamento medicamentoso de escolha é metildopa 250\nmg a cada 12 horas, havendo necessidade de\nsolicitar ultrassonografia obstétrica agora e\nmensalmente após a 32ª semana.","C":"Trata-se de hipertensão gestacional, o tratamento medicamentoso de escolha é metildopa 250\nmg a cada 12 horas, havendo necessidade de\nsolicitar ultrassonografia obstétrica com doppler de\nartéria","D":"Trata-se de hipertensão crônica na gestação, o tratamento medicamentoso de escolha é\nenalapril 20 mg a cada 12 horas, havendo\nnecessidade de solicitar ultrassonografia obstétrica com\ndoppler de artéria umbilical mensalmente.","E":"Trata-se de hipertensão gestacional, o tratamento medicamentoso de escolha é enalapril 10 mg\na cada 12 horas, havendo necessidade de\nsolicitar ultrassonografia obstétrica com doppler de\nartéria"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-343371","number":"343371","sourceNumber":"343371","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 11 semanas que realizava pré-natal na Espanha, muda para o Brasil e em\nsua primeira consulta de pré-natal apresenta\nlaudo de exame onde consta Antígeno Austrália\npositivo. Isso significa que ela tem:","options":{"A":"Herpes.","B":"Hepatite B.","C":"Sífilis.","D":"Toxoplasmose."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-281885","number":"281885","sourceNumber":"281885","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Distúrbios da tiroide na gravidez estão relacionados, exceto.","options":{"A":"Malformação fetal.","B":"Pré-eclâmpsia.","C":"Restrição de crescimento fetal.","D":"Prematuridade."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-281889","number":"281889","sourceNumber":"281889","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"É considerado fator protetor para pré-eclampsia:","options":{"A":"Obesidade.","B":"Diabete.","C":"Tabagismo.","D":"Gestação gemelar."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-281894","number":"281894","sourceNumber":"281894","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O teste do Nitrito é útil no auxílio de:","options":{"A":"Diagnosticar infecção urinária.","B":"Avaliar insuficiência renal aguda.","C":"Diagnosticar síndrome nefrótica.","D":"Quantificar a gravidade da pré-eclâmpsia."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-218151","number":"218151","sourceNumber":"218151","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Maria Aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretarias de Saúde do Estado e do Município, Maria fez a mamografia também com resultados\nnormais. Maria Aparecida teve menarca aos 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e\num filho, Carlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida\nmenstrua regularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de\nPaulo há 2 anos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem\nde 30 anos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é\nhipertensa em uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA 140/90 mmHg,\npesa 78 kg, mede 1,60 m de altura (IMC 30,5). Maria Aparecida retorna após 6 meses com um\n\"teste de gravidez de farmácia\" com resultado positivo. Ela não planejava engravidar novamente,\nmas Valdomiro não tem filhos e vinha propondo que o casal tivesse um. Daiane observa que Maria\nAparecida se apresenta com um misto de entristecimento e resignação. Sobre a conduta mais\nadequada a ser adotada por Daiane, analise as assertivas e identifique com V as verdadeiras e\ncom F as falsas. ( ) Pela idade, Hipertensão Arterial Sistêmica (HAS) e histórico de Maria\nAparecida, sua gestão é de alto risco, então, Daiane deve encaminhá-la ao serviço adequado a seu\ntratamento. ( ) Daiane deve solicitar os exames de rotina previstos no retorno para a primeira\nconsulta de pré-natal e deverá substituir o medicamento para HAS optando por metildopa ou,\nalternativamente, antagonistas do canal de cálcio. ( ) Daiane deve solicitar os exames de rotina\nprevistos no retorno para a primeira consulta de pré-natal e manter o tratamento medicamentoso\npara HAS, uma vez que tem conseguido controlar adequadamente sua HAS, e acrescentar\nmetildopa se houver aumento da pressão arterial. ( ) Daiane deve, desde o primeiro momento,\n\nexplicar a Maria Aparecida as situações nas quais a legislação brasileira proíbe o aborto, deverá\nsolicitar o B-HCG, sérico para confirmação\nda gravidez, explicar a Maria Aparecida a rotina e\nprogramação do pré-natal e já marcar nova consulta com Maria Aparecida e Valdomiro juntos. ( )\nDaiane deve acolher Maria Aparecida - dialogando sobre ideias, expectativas e medos - com\ncuidado para não fazer julgamentos. Deve avaliar o risco de abortamento e realizar ação de\neducação em saúde, conforme as diretrizes e protocolos nacionais - que inclui legislação, riscos de\npráticas inseguras de abortamento, mediação de conflitos e diálogo com rede de apoio. Deve\nsolicitar o B-HCG sérico para confirmação da gravidez, explica a Maria Aparecida como será o\n\npré-natal e agendar retorno em curto espaço de tempo. A alternativa que contém a sequência\nCORRETA, de cima para baixo, é:","options":{"A":"V, F, V, F, F.","B":"V, F, F, V, F.","C":"F, V, F, F, V.","D":"F, V, F, V, F.","E":"F, V, V, F, V."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-218188","number":"218188","sourceNumber":"218188","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Maria Aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretarias de Saúde do Estado e do Município, Maria fez a mamografia também com resultados\nnormais. Maria Aparecida teve menarca aos 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e\num filho, Carlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida\nmenstrua regularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de\nPaulo há 2 anos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem\nde 30 anos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é\nhipertensa em uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA 140/90 mmHg,\npesa 78 kg, mede 1,60 m de altura (IMC 30,5). Maria Aparecida, já no segundo trimestre da\ngestação, vem com Valdomiro a mais uma consulta de pré-natal. Está assintomática, mas vem\npreocupada porque viu que, no exame de rastreamento, apareceu um resultado anormal. - O que é\nisso doutora? - pergunta à Daiane. Está circulado 500.000 colônias por ml de urina. Considerando o\ncaso clínico 01, analise as assertivas e identifique com V as verdadeiras e com F as falsas. ( )\nApós\no tratamento da bacteriúria assintomática, deve-se realizar urocultura de controle de 7 a 10 dias\napós o término do tratamento. ( ) Os antibióticos de escolha para esse tratamento são: ampicilina\n500 mg, azitromicina 500 mg, cefalexina 500 mg ou nitrofurantoína 100 mg. ( ) Define-se como\nbacteriúria assintomática o crescimento de > 10? colônias por ml de urina coletada por jato médio\nsem sintomas urinários. ( ) O rastreamento para infecção urinária em usuários assintomáticos não é\nrecomendado, a não ser em casos específicos como em gestantes, nos quais deve ser feito no\nprimeiro e no terceiro trimestre da gestação. A alternativa que contém a sequência CORRETA, de\ncima para baixo é:","options":{"A":"V, V, F, F.","B":"V, F, V, V.","C":"V, V, V, F.","D":"V, F, F, V.","E":"F, V, F, V."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215585","number":"215585","sourceNumber":"215585","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em gestação gemelar monocoriônica, a discordância de peso entre os fetos superior a\n20% faz suspeitar de:","options":{"A":"Diabete gestacional.","B":"Síndrome transfusão gemelo-gemelar.","C":"Insuficiência placentária.","D":"Toxemia gravídica."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215582","number":"215582","sourceNumber":"215582","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Não é considerado fator de risco para pré-eclâmpsia:","options":{"A":"Hipertensão prévia.","B":"Obesidade.","C":"Dislipidemias.","D":"Idade abaixo de 16 anos."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215620","number":"215620","sourceNumber":"215620","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em 2015, a Federação Internacional de Diabetes (Internacional Diabetes Federation,\nIDF) estimou que 8,8% (intervalo de confiança\n[IC] de 95%: 7,2 a 11,4) da população mundial com\n20 a 79 anos de idade (415 milhões de pessoas) vivia com diabetes. Podemos, apenas, ACEITAR,\nque:","options":{"A":"Diabetes Mellitus (DM) não é um importante e crescente problema de saúde para todos os\npaíses, independentemente do seu grau de desenvolvimento.","B":"Diabetes Mellitus (DM) é um importante e crescente problema de saúde para todos os países,\nindependentemente do seu grau de desenvolvimento.","C":"Diabetes Mellitus (DM) é um importante e decrescente problema de saúde para todos os países,\nindependentemente do seu grau de desenvolvimento.","D":"Diabetes Mellitus (DM) é um importante e crescente problema de saúde para todos os países,\ndependentemente do seu grau de desenvolvimento, somente nos pobres."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215621","number":"215621","sourceNumber":"215621","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A rápida urbanização, transição nutricional, maior frequência de estilo de vida\nsedentário, maior frequência de excesso de peso,\ncrescimento e envelhecimento populacional e,\ntambém, a maior sobrevida dos indivíduos com diabetes, está ADEQUADA:","options":{"A":"À redução global da prevalência do diabetes associado a diversos fatores, como os listados\nacima.","B":"Ao aumento da prevalência do diabetes não associado a diversos fatores, como os listados\nacima.","C":"Ao aumento da prevalência do diabetes associado a diversos fatores, como os listados acima.","D":"Ao aumento da prevalência do diabetes nunca se associando a diversos fatores, como os\nlistados acima."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215622","number":"215622","sourceNumber":"215622","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Como resultado de uma combinação de fatores, a condição do diabetes entre a\npopulação pode permanecer não detectada por vários anos, dando oportunidade ao\ndesenvolvimento de suas complicações. Assim podemos, apenas, CONCORDAR que:","options":{"A":"Estima-se que 16% dos casos de diabetes em adultos não sejam diagnosticados e, que, 83,8%\nde todos os casos de diabetes não\ndiagnosticados estejam em países em desenvolvimento.","B":"Estima-se que 96% dos casos de diabetes em adultos não sejam diagnosticados e, que, 83,8%\nde todos os casos de diabetes não\ndiagnosticados estejam em países em desenvolvimento.","C":"Estima-se que 46% dos casos de diabetes em adultos sejam diagnosticados e, que, 83,8% de\ntodos os casos de diabetes diagnosticados estejam em países desenvolvidos.","D":"Estima-se que 46% dos casos de diabetes em adultos não sejam diagnosticados e, que, 83,8%\nde todos os casos de diabetes não\ndiagnosticados estejam em países em desenvolvimento."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-215625","number":"215625","sourceNumber":"215625","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Pelo fato de o diabetes estar associado a maiores taxas de hospitalizações, maior\nutilização dos serviços de saúde, bem como maior incidência de doenças cardiovasculares e\ncerebrovasculares, cegueira, insuficiência renal e amputações não traumáticas de membros\ninferiores, pode-se prever a carga que isso representará nos próximos anos para os sistemas de\nsaúde de todos os países. Podemos, assim, CONCORDAR que, como resultado de uma\ncombinação de fatores:","options":{"A":"O que exclui baixo desempenho dos sistemas de saúde, pouca conscientização sobre diabetes\nentre a população geral e os profissionais\nde saúde e início insidioso dos sintomas ou progressão\ndo diabetes tipo 2; essa condição pode permanecer não detectada por vários anos, dando\noportunidade ao desenvolvimento de suas complicações.","B":"O que inclui baixo desempenho dos sistemas de saúde, muita conscientização sobre diabetes\nentre a população geral e os profissionais\nde saúde e início insidioso dos sintomas ou progressão\ndo diabetes tipo 2; essa condição pode permanecer não detectada por vários anos, dando\noportunidade ao desenvolvimento de suas complicações.","C":"O que inclui baixo desempenho dos sistemas de saúde, pouca conscientização sobre diabetes\nentre a população geral e os profissionais\nde saúde e início insidioso dos sintomas ou progressão\ndo diabetes tipo 2; essa condição pode permanecer não detectada por vários anos, dando\noportunidade ao desenvolvimento de suas complicações.","D":"O que inclui baixo desempenho dos sistemas de saúde, pouca conscientização sobre diabetes\nentre a população geral e os profissionais\nde saúde e início insidioso dos sintomas ou progressão\ndo diabetes tipo 2; essa condição pode permanecer não detectada por vários dias, dando\noportunidade ao desenvolvimento de suas complicações."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-181183","number":"181183","sourceNumber":"181183","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em pacientes com Iminência de Eclâmpsia tratadas com sulfato de magnésio, são\nimportantes as seguintes informações:","options":{"A":"A eliminação do Sulfato de Magnésio acontece via renal e seu antídoto é o Gluconato de Cálcio.","B":"A eliminação do Sulfato de Magnésio acontece via hepática e seu antídoto é o Gluconato de\nCálcio.","C":"A eliminação do Sulfato de Magnésio acontece via renal e seu antídoto é o Carbonato de Cálcio.","D":"A eliminação do Sulfato de Magnésio acontece via hepática e seu antídoto é o Carbonato de\nLítio."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-181189","number":"181189","sourceNumber":"181189","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Dos listados abaixo, o sabidamente reconhecido como fator de risco para\nPré-eclâmpsia é:","options":{"A":"Primigestação.","B":"Abortamento tardio prévio.","C":"Casamento consanguíneo.","D":"Transfusões de sangue prévias."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-181153","number":"181153","sourceNumber":"181153","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação aos exames abaixo, aquele que não faz parte no diagnóstico de Síndrome\nHELLP é:","options":{"A":"TGP","B":"TGO","C":"Gama GT","D":"Contagem de plaquetas"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157627","number":"157627","sourceNumber":"157627","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A segunda onda de migração trofoblástica, que ocorre entre 16 e 22 semanas de\ngestação, está prejudicada em: I. crescimento intrauterino retardado.; II. DHEG.; III. DHEG\nsuperajuntada.; Está CORRETO o contido em:","options":{"A":"II, apenas.","B":"III, apenas.","C":"I e III, apenas.","D":"I, II e III."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157678","number":"157678","sourceNumber":"157678","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O diagnóstico de Eclâmpsia se estabelece por","options":{"A":"hipertensão após 20 semanas de gestação.","B":"hipertensão + edema + proteinúria na gravidez.","C":"convulsões.","D":"síndrome HELLP."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157653","number":"157653","sourceNumber":"157653","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante diabética insulino-dependente, durante o terceiro trimestre de gestação,\napresenta necessidade cada vez menor de insulina\npara controle de glicemia. Esse quadro é\ncomum e pode significar:","options":{"A":"gemelaridade.","B":"insuficiência placentária.","C":"macrossomia fetal.","D":"polidrâmnio agudo."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157661","number":"157661","sourceNumber":"157661","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Na DHEG é comum ocorrer, EXCETO o contido em uma das opções. Assinale-a:","options":{"A":"Segunda onda de migração trofoblástica inadequada.","B":"Dano endotelial sistêmico.","C":"Aumento da concentração de prostaciclina e diminuição do tromboxano A2.","D":"Vasoespasmo."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157607","number":"157607","sourceNumber":"157607","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Durante o seu último plantão como clínico no hospital, você respondeu a um parecer\nsolicitado pelo Obstetra que teve\ndificuldades de abordagem de uma de suas gestantes decorrente\nde achado de hipertensão. Seu parecer informou, ADEQUADAMENTE, o seguinte. Assinale-o.","options":{"A":"HA na gestação como a presença de PAS =130 mmHg e/ou PAD = 90 mmHg, considerando-se\no 5ª ruído de Korotkoff.","B":"A medida deve ser realizada idealmente com a paciente deitada e alternativamente com a\ngestante em decúbito lateral.","C":"A Pré-eclâmpsia é definida pela presença de HA após a 10 ª semana associada à proteinúria\nsignificativa.","D":"A HA crônica é definida pela detecção de HA precedendo a gestação ou antes de 20 semanas."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157612","number":"157612","sourceNumber":"157612","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A associação da elevação pressórica durante a gestação apresenta grandes riscos,\ntanto para a saúde materna quanto para o feto.\nPodemos considerar como verdadeiras as\nseguintes colocações, com EXCEÇÃO de uma delas. Indique-a.","options":{"A":"O tratamento medicamentoso urgente é indicado em HA grave (PAS > 155-160 mmHg).","B":"O tratamento de HA grave em situações de emergência pode ser feito com hidralazina\nintravenosa (IV).","C":"Em situações excepcionais, como a presença de edema agudo de pulmão (EAP) e HAS grave e\nrefratária, o uso de Nitroprussiato de sódio (NPS) deve ser considerado como opção preferencial\npara controle urgente da PA.","D":"O tratamento medicamentoso deve ser iniciado quando a PA estiver acima de 180/100\nmmHg,12, com o objetivo de mantê-la em 130-150/80-100 mmHg."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157647","number":"157647","sourceNumber":"157647","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Jovem primigesta, 23 anos de idade, procurou o hospital com quadro de estrangúria e\nfebre. A obstetrícia pediu seu parecer clínico. Durante avaliação, você encontrou uma dor lombar e\npélvica, e solicitou USG de vias urinárias, que foi normal, e um exame de urina, que demonstrou\npiúria. Qual das medicações abaixo listadas, apesar de adequada ao tratamento de pielonefrite,\ndeve ser contraindicada por risco de lesão óssea fetal?","options":{"A":"Ceftriaxona.","B":"Ciprofloxacino.","C":"Cloranfenicol.","D":"Amicacina."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-139739","number":"139739","sourceNumber":"139739","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Considere as afirmações apresentadas a seguir. I. Diabetes gestacional pode ser\ndiagnosticado apenas em torno da 16 ª semana de gestação.; II. Diabetes gestacional é mais\ncomum em pacientes primigestas.; III. HPL (Hormônio Lactogênico Placentário) é o maior\nresponsável pelo efeito ?diabetogênico? da gravidez. Estão INCORRETAS as afirmações contidas\nem:","options":{"A":"II e III, apenas.","B":"I, II e III.","C":"I e II, apenas.","D":"I e III, apenas"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-139752","number":"139752","sourceNumber":"139752","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"No tratamento da pré-eclâmpsia grave, há o emprego do sulfato de magnésio. Qual é a\nprincipal justificativa para a sua utilização?","options":{"A":"Aumenta a diurese.","B":"Previne as crises convulsivas.","C":"Diminui a hipertonia uterina.","D":"Reverte a hipomagnesemia."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134711","number":"134711","sourceNumber":"134711","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 30 semanas, diabética mal controlada com tratamento com\ninsulinoterapia, dieta e exercícios. Esta\npaciente tem como riscos, as alternativas abaixo, EXCETO\numa. Aponte-a.","options":{"A":"Prematuridade fetal.","B":"Óbito intrauterino.","C":"Oligoâmnio.","D":"Distócias no parto."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134760","number":"134760","sourceNumber":"134760","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 20 anos, 28 semanas de gestação, vem ao PS com queixa de urina\nescura, com odor forte, polaciúria, disúria,\nvômitos, dor lombar à esquerda e calafrios. Ao exame,\npaciente prostrada, febril, corada, bom estado geral. Qual é a MELHOR conduta para esse caso?","options":{"A":"Tratamento ambulatorial com hidratação e antibiótico via oral.","B":"Tratamento internado com antibiótico endovenoso.","C":"Solicitar urina I e cultura, internar e mandar paciente voltar em 3 dias para ver resultado.","D":"Internar paciente e solicitar urina I e cultura e entrar com antibiótico endovenoso."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-111868","number":"111868","sourceNumber":"111868","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O sulfato de magnésio, utilizado no tratamento da eclâmpsia, quando em dose\nexcessiva, pode ocasionar:","options":{"A":"hipertensão arterial.","B":"hipoperfusão placentária.","C":"parada respiratória.","D":"taquicardia acentuada."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-111888","number":"111888","sourceNumber":"111888","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 38 semanas, 23 anos, IIG, 0P, I AB, feto único e vivo em apresentação\npélvica, apresenta-se pela primeira vez em consulta\napresentando P.A. de 155 x 100 mmHg,\nsentada. O Médico recomenda repouso em DLE e volta a medir a pressão arterial 2 horas após. Os\nníveis continuam os mesmos e o colega resolve internar a paciente. Como o Médico não consegue\nestabelecer um diagnóstico definitivo, ele telefona para você para ajudá-lo a esclarecer o caso.\n\nVocê recomenda que ele dê o diagnóstico provável de Pré-eclâmpsia leve mais H.A. crônica.\nSugere, também, pedir os seguintes exames para elucidação diagnóstica:","options":{"A":"fundo de olho, proteinúria de 24 horas, acido úrico e creatinina.","B":"proteinúria de 24 horas, cardiotocografia, ultrassom e dopllerfluxometria.","C":"creatinina, TGO, TGP e plaquetas.","D":"hemograma, ultrassom, cardiotocografia e fundo de olho."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-111824","number":"111824","sourceNumber":"111824","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A Pré-eclâmpsia tem como agravante a evolução para Síndrome HELLP, cuja sigla tem\ncomo significado:","options":{"A":"Hematúria, Elevação das Enzimas Hepáticas e Plaquetopenia.","B":"Hemólise, Elevação das Enzimas Hepáticas e Púrpura Trombocitopênica.","C":"Hemólise, Diminuição das Enzimas Hepáticas e Plaquetopenia.","D":"Hemólise, Elevação das Enzimas Hepáticas e Plaquetopenia."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-350842","number":"350842","sourceNumber":"350842","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente C.M.M, 15 anos, gestação no curso das 38 semanas, encontra-se internada\nem Maternidade terciária por ter apresentado quadro\nde pressão arterial de 120x90mmHg e\nepisódio convulsivo. Diurese satisfatória pela sonda vesical. Fez dose de ataque de sulfato de\nmagnésio e durante a primeira dose de manutenção de 2 gramas/h, apresenta novo episódio de\nconvulsão tônico-clônico generalizada. A conduta adequada após recorrência de episódio\nconvulsivo nesta paciente é:","options":{"A":"Aplicar Diazepam 20 mg em bolus, por via intravenosa.","B":"Administrar midazolam ou lorazepam, por via endovenosa.","C":"Aplicar dose adicional de 2 g de sulfato de magnésio, por via intravenosa.","D":"Administrar dose de anti-hipertensivo para controle dos níveis pressóricos, por via oral."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-350835","number":"350835","sourceNumber":"350835","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"FSN, 35 anos, G3P0 A2, apresenta durante consulta pré-natal no primeiro trimestre,\nTSH de 4,9mUI/L. Qual a Abordagem adequada na\ncondução da tireoidopatia desta paciente?","options":{"A":"Manter o TSH >2,5mUI/L, como meta terapêutica.","B":"Administrar levotiroxina 1mcg/Kg/dia se dosagem de T4 L normal.","C":"Solicitar o anti-TPO e se positivo, tratar com levotiroxina 50mcg/dia.","D":"Dosar T4 L e iniciar levotiroxina 0,5mcg/Kg/dia, até o resultado do exame."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-321364","number":"321364","sourceNumber":"321364","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 36 anos, com 26 semanas de idade gestacional, procura unidade de\npronto-atendimento referindo quadro de polaciúria, disúria e dor lombar há 7 dias, com\nagravamento há 12 horas, quando surgiram febre e tontura. Ao exame: pressão arterial de\n80x40mmHg, pulso de 144 bpm, sudoréica, frequência respiratória de 23 irpm. O diagnóstico mais\nadequado e a sua respectiva conduta são:","options":{"A":"Choque séptico e antibiótico venoso iniciado na primeira hora.","B":"Sepse e antibiótico venoso iniciado na primeira hora.","C":"Pielonefrite e antibiótico venoso.","D":"Cistite e antibiótico oral."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-321365","number":"321365","sourceNumber":"321365","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 17 anos, idade gestacional de 39 semanas, comparece à emergência de\nmaternidade referindo cólicas, inchaço, cefaleia e escotomas visuais. Ao exame: pressão arterial de\n140x90mmHg, dinâmica uterina de 3 contrações em 10 minutos, batimentos cardíacos fetais de 144\npor minuto, toque vaginal evidenciando colo com 5cm de dilatação, centralizado e apagado,\napresentação cefálica, variedade de posição em OEA (occipito esquerda anterior), plano 0 de\nDeLee. Durante a admissão, paciente apresenta convulsão tônico-clônica generalizada. A conduta\nprioritária a ser tomada pela equipe obstétrica é:","options":{"A":"Oxigênio sob cateter nasal, contenção da paciente no leito, proteção da língua, avaliação\nlaboratorial (hemoglobina, plaqueta, creatinina).","B":"Contenção da paciente no leito, proteção da língua, prescrição de benzodiazepínico, avaliação\nlaboratorial (hemoglobina, plaqueta, creatinina).","C":"Prescrição de sulfato de magnésio e cesárea de urgência.","D":"Prescrição de sulfato de magnésio e de ocitocina, solicitação de analgesia de parto com fórceps\nde alívio."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-292860","number":"292860","sourceNumber":"292860","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A revisão do prontuário de atendimentos prévios da Vanessa mostra que exames de\npesquisa de anticoagulante lúpico e anticorpo anticardiolipina foram solicitados duas vezes, em\nintervalo maior que 12 semanas, com resultados persistentemente elevados. A partir das\ninformações coletadas, assinale a alternativa com risco gestacional de Vanessa.","options":{"A":"Alto risco.","B":"Risco habitual.","C":"Risco habitual com vulnerabilidades.","D":"Não há informações suficientes para classificar o risco gestacional."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-292870","number":"292870","sourceNumber":"292870","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Os Centers for Disease Control and Prevention (CDC) definem cuidado\n\npré-concepcional como ?um conjunto de intervenções que visam identificar e modificar riscos\nbiomédicos, comportamentais e sociais para a saúde\nou o resultado da gestação por meio de\nintervenções profiláticas e terapêuticas ? (Johnson, 2006). Dentre os cuidados prestados durante o\npré-natal destacam-se o rastreio para a Diabetes Mellitus e a profilaxia desta patologia. Desta\nmaneira, é correto afirmar:","options":{"A":"Estabelecer o diagnóstico do Diabetes Mellitus Gestacional (DMG) oferece a oportunidade de\nmelhorar o prognóstico da gravidez, mas não reduz os fatores de risco associados ao\ndesenvolvimento subsequente do diabetes tipo 2.","B":"O diabetes pré-gestacional merece ser identificado na 1a consulta pré-natal, pois compromete a\nmãe e o feto. Mulheres diabéticas que desejam engravidar, devem ser avaliadas apenas se\napresentarem história de mal passado obstétrico.","C":"Grávidas de alto risco para diabetes que apresentam no 1o trimestre valor da HbA1c ? 6% têm\nreduzido valor preditivo para Diabetes Mellitus Gestacional. Mulheres com diabetes tipo 1 que\npretendam engravidar devem passar por avaliação da tireoide pela determinação do TSH e do\nanticorpo anti-tireoperoxidase (anti-TPO).","D":"Toda mulher com Diabetes Mellitus Gestacional (DMG) deve ser rastreada entre 6 e 12 semanas\napós o parto pelo TOTG-75 g de 2h.\nDiabéticas que planejam a gravidez, devem ser aconselhadas\na utilizar suplementação com ácido fólico 3 meses antes da concepção e por 12 semanas depois,\npara prevenir os defeitos do tubo neural (DTN)."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-292871","number":"292871","sourceNumber":"292871","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A residente B.M.W. chega ao plantão obstétrico em hospital terciário recebendo de seu\ncolega médico, em passagem de plantão, a história da paciente N.A.S.A., 16 anos, primigesta com\nidade gestacional de 34 semanas, apresentando quadro de elevação dos níveis pressóricos, PA:\n160x100mmhg, Auscuta Fetal com BCF: 180bpm, dinâmica uterina ausente, em uso de sonda\nvesical de demora, sem apresentar diurese nas últimas 3 horas. No momento da passagem do\ncaso, a paciente encontrava-se em uso da 2a fase de sulfato de magnésio (MgSO4), iniciado no\nmomento de sua internação, motivada pelo quadro descrito em associação com cefaleia occiptal,\nvômitos persistentes e alterações visuais (escotomas e amaurose). A conduta adequada a ser\ntomada é:","options":{"A":"Manter a infusão de sulfato de Magnésio 50%, visando prevenir crises convulsivas, AVC e\nedema agudo de pulmão.","B":"Administrar hidralazina 5 mg, EV, para tratar o pico pressórico e betametazona 12 mg, IM, para\npromoção da maturação pulmonar fetal.","C":"Confirmar a vitalidade fetal pela ultrassonografia obstétrica com doppler e resolver a gestação\nvia vaginal, através de indução com misoprostol.","D":"Administrar nifedipina 20 mg, via oral, para tratar pico pressórico e solicitar hematócrito,\nhemoglobina, contagem de plaquetas, creatinina,\nTGO, LDH, TP, TTPa, fibrinogênio e relação\nproteína creatinina, para avaliar lesões de órgãos alvo."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-292874","number":"292874","sourceNumber":"292874","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 34 anos, G1P0A0, realizou fertilização in vitro, comparece à segunda\nconsulta de pré-natal com ultrassom revelando gestação gemelar dicoriônica no curso da 8ª\nsemana. Qual das afirmativas não é verdadeira em relação a esta gestação?","options":{"A":"70-75% das gestações gemelares são dizigóticas, sendo estas dicoriônicas e diamnióticas em\n100% dos casos.","B":"O seguimento pré-natal desta gestação deve ser realizado de forma mensal, até a 28ª semana,\na cada 2-3 semanas a partir da 28ª semana e,\nsemanal, a partir da 36ª semana.","C":"Após a prematuridade, a complicação mais frequente da gravidez gemelar dicoriônica é a\nsíndrome da transfusão feto fetal (STFF), sendo importante causa de morbimortalidade perinatal.","D":"O rastreamento ultrassonográfico da gestação gemelar dicoriônica, se faz entre a 11ª e 14ª\nsemana para datação e rastreamento de cromossomopatias e entre a 20ª e 22ª semana para\navaliação detalhada da anatomia fetal e comprimento do colo. Após a 24ª semana, realiza-se a\ncada 30 dias para avaliar o crescimento, o líquido amniótico e doppler fetal."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-259776","number":"259776","sourceNumber":"259776","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente A.B.C., 40 anos, obesa, no curso da 25ª semana de gestação, comparece à\nconsulta pré-natal com queixas de edema em membros inferiores, poliúria e ganho ponderal de 3\nkg nos últimos 30 dias. Traz exame de TTOG com 75 g de glicose (curva glicêmica) com\nresultados: 90, 170 e 168 mg/dl (jejum, 1h e 2h). Após avaliar o quadro clínico e exames\nlaboratoriais acima, assinale o diagnóstico CORRETO e as metas glicêmicas esperadas.","options":{"A":"Diabetes mellitus tipo 1. Níveis glicêmicos de jejum ? 99 mg/dl, o de 1º h ? 140 mg/dl, e o de\n2º h\n\n? 120 mg/dl.","B":"Diabetes mellitus tipo 2. Níveis glicêmicos de jejum ? 92 mg/dl, o de 1º h ? 180 mg/dl, e o de\n2º h\n\n? 153 mg/dl.","C":"Diabetes mellitus gestacional. Níveis glicêmicos de jejum ? 95 mg/dl, o de 1º h ? 140 mg/dl, e o\nde 2º h ? 120 mg/dl.","D":"Diabetes mellitus pré-gestacional. Níveis glicêmicos de jejum ? 92 mg/dl, o de 1º h ? 126 mg/dl,\ne o de 2º h ? 110 mg/dl."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-259779","number":"259779","sourceNumber":"259779","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"G.E.M., 30 anos, G2P1vA0, com dois episódios de bacteriúria assintomática no primeiro\ntrimestre da gestação, comparece à Unidade de Pronto Atendimento (UPA) no segundo trimestre\nqueixando-se de febre e dor lombar à direita. No exame físico, foi visto pressão arterial de 90x50\nmmHg, pulso de 124 bpm e confusão mental. Qual a conduta adequada?","options":{"A":"Antibioticoterapia venosa após resultado de urinocultura para garantir adequado efeito da\nmedicação.","B":"Quimioprofilaxia contra novo episódio de infecção urinária após adequado tratamento do quadro\nséptico atual.","C":"Cefalosporina de primeira geração oral no nível ambulatorial, após adequada hidratação venosa\ncom 30ml/Kg de cristaloide.","D":"Quinolona oral no nível ambulatorial, após adequada hidratação venosa com 50ml/Kg de\ncristaloide na primeira hora."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-234089","number":"234089","sourceNumber":"234089","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 15 anos, com idade gestacional de 10 semanas, previamente hígida, em\nconsulta na emergência, afirma que perdeu 5 kg desde o início da gestação e vem apresentando\nnáuseas e vômitos após ingesta de sólido ou líquido, com piora progressiva a despeito do uso de\nmetoclopramida 3 vezes por dia intercalado com dimenidrinato + piridoxina. Paciente se queixa\ntambém de dor epigástrica e sonolência. Exame físico com pressão arterial de 90 x 60 mmHg,\npulso de 120 bpm, peso de 45kg. Traz exames mostrando cetonúria, TSH de 0,2 mU/L e creatinina\nde 1,6 mg/dl. Qual a conduta ideal?","options":{"A":"Suspender dieta oral + hidratação venosa e noradrenalina + solicitar ecocardiografia\ntranstorácica.","B":"Oferecer dieta rica em líquidos + propiltiouracila e propranolol + solicitar ultrassonografia da\ntireoide.","C":"Suspender dieta oral + hidratação venosa acrescida de tiamina, glicose e anti-emético + dosar\neletrólitos.","D":"Oferecer dieta rica em líquidos + terapia antibiótica venosa + colher ureia e urinocultura com\nantibiograma."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-234092","number":"234092","sourceNumber":"234092","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 15 anos, no curso de 29 semanas de gestação, apresenta-se em consulta de\npré-natal referindo cefaleia, visão turva e pressão arterial de 160 x 90 mmHg mantida após decúbito\nlateral esquerdo. Indique a melhor conduta a ser adotada:","options":{"A":"Encaminhar a gestante para seguimento na emergência. Solicitar avaliação laboratorial para\navaliação de proteinúria, função renal e diagnóstico de síndrome HELLP. Iniciar terapia\n\nanti-hipertensiva para tratamento do pico hipertensivo com uso de nifedipina oral e vigiar bem-estar\nfetal. Faz-se necessário iniciar uso de sulfato\nde magnésio para profilaxia de convulsões.","B":"Encaminhar a gestante para seguimento na emergência. Solicitar avaliação laboratorial para\navaliação de proteinúria, função renal e diagnóstico de síndrome HELLP. Iniciar terapia\n\nanti-hipertensiva para tratamento do pico hipertensivo com uso de nifedipina sublingual e vigiar\nbem-estar fetal. Faz-se necessário iniciar\nuso de sulfato de magnésio para profilaxia de convulsões.","C":"Permanecer com o seguimento pré-natal ambulatorial, com consultas mensais. Solicitar\navaliação laboratorial para avaliação de\nproteinúria, função renal e diagnóstico de síndrome\nHELLP. Iniciar terapia anti-hipertensiva oral para tratamento da elevação pressórica com uso de\nmetildopa e vigiar bem-estar fetal. Não se faz necessário iniciar uso de sulfato de magnésio para\nprofilaxia de convulsões.","D":"Permanecer com o seguimento pré-natal ambulatorial, com consultas semanais. Não se faz\nnecessário solicitar avaliação laboratorial para avaliação de proteinúria, função renal e\ndiagnóstico\nde síndrome HELLP. Iniciar terapia anti-hipertensiva para tratamento do pico hipertensivo com uso\nde nifedipina oral e vigiar bem-estar fetal. Não se faz necessário iniciar uso de sulfato de\nmagnésio\npara profilaxia de convulsões."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-199748","number":"199748","sourceNumber":"199748","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, 17 anos, 30 semanas de idade gestacional, foi à consulta de pré-natal sem\nnenhuma queixa. Trouxe exame laboratorial\nrecente com hemoglobina de 9,0 g/dl, além de\nhemácias hipocrômicas e microcíticas. Qual a melhor conduta?","options":{"A":"Ferroterapia endovenosa até hemoglobina de 12 g/dl.","B":"Tratamento com sulfato ferroso oral 3 a 6 drágeas/dia.","C":"Nenhuma, pois trata-se de hemodiluição própria da gestação.","D":"Transfusão sanguínea, pois a gestante encontra-se no terceiro trimestre."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-199759","number":"199759","sourceNumber":"199759","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 28 anos, G1P0A0, 12 semanas de idade gestacional, traz glicemia de jejum\nde 95 mg/dl nos exames iniciais de pré-natal. Qual a melhor conduta nesse caso?","options":{"A":"Conduzir a paciente como diabetes mellitus gestacional.","B":"Repetir a glicemia de jejum com 16 semanas de gestação.","C":"Encaminhar ao pré-natal de alto risco por diabetes mellitus prévio à gestação.","D":"Solicitar o teste de tolerância oral à glicose 75 g entre 20-24 semanas de gestação."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-199647","number":"199647","sourceNumber":"199647","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente feminino, 18 anos, primípara, no curso das 32 semanas de gestação, procurou\natendimento em unidade de atenção primária no interior do Estado, onde se evidenciou quadro\nclínico de cefaleia occipital, epigastralgia e escotomas visuais cintilantes, associado a pressão\narterial de 170x110 mmHg. Frente ao quadro clínico e capacidade hospitalar existente, o\nplantonista decide transferir a paciente para centro terciário na capital para assistência\nobstétrica\nadequada. Qual terapia disponível no Brasil é considerada atualmente como de primeira linha para\na crise hipertensiva descrita e que pode ser feita com segurança no cenário descrito?","options":{"A":"Labetalol.","B":"Nifedipina.","C":"Hidralazina.","D":"Sulfato de magnésio."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-172962","number":"172962","sourceNumber":"172962","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, 37 anos, realizou glicemia de jejum com 12 semanas cujo resultado foi 110\nmg/dl. Qual a conduta, conforme as novas recomendações do Ministério da Saúde (2017)?","options":{"A":"Realizar TOTG imediatamente.","B":"Realizar TOTG entre 24-28 semanas.","C":"Definir como diabetes mellitus e tratar.","D":"Definir como diabetes mellitus gestacional e tratar."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-172972","number":"172972","sourceNumber":"172972","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 17 anos, no curso de 37 semanas de gestação, procura emergência\nobstétrica devido a nível pressórico elevado\nidentificado em consulta de pré-natal. Após avaliação\ninicial, evidencia-se que a mesma encontra-se assintomática, com pressão arterial de 170 x 110\nmmHg e apresenta relação proteína/creatinina urinária de 0,6. Além do tratamento do pico\nhipertensivo, qual conduta deve ser adotada?","options":{"A":"Iniciar profilaxia anticonvulsivante com sulfato de magnésio e preparar para o parto.","B":"Indicar o parto sem a necessidade de iniciar profilaxia anticonvulsivante com sulfato de\nmagnésio.","C":"Adotar conduta conservadora, sem a necessidade de iniciar profilaxia anticonvulsivante com\nsulfato de magnésio.","D":"Iniciar profilaxia anticonvulsivante com sulfato de magnésio e adotar conduta conservadora\natravés de monitoração materno-fetal rigorosa."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-150819","number":"150819","sourceNumber":"150819","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 18 anos, com idade gestacional por ultrassonografia precoce de 32\nsemanas, procura emergência por queixa de cefaleia intensa e amaurose. Ao exame: PA:\n140x100mmHg, ausência de dinâmica uterina, altura do fundo uterino de 25 cm e batimentos\ncardíacos fetal de 148bpm. Qual a conduta indicada?","options":{"A":"Prescrever sulfato de magnésio e solicitar ressonância nuclear magnética do crânio.","B":"Iniciar sulfato de magnésio e corticoide e solicitar tomografia computadorizada do crânio.","C":"Prescrever hidralazina e corticoide e solicitar hemograma, transaminases e desidrogenase\nláctica.","D":"Iniciar sulfato de magnésio e corticoide e solicitar hemograma, transaminases e desidrogenase\nláctica."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-150828","number":"150828","sourceNumber":"150828","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 35 anos, com índice de massa corpórea de 28 Kg/m2, com gestação de\n12 semanas, retornou à Unidade Básica de Saúde\nda Família para mostrar os resultados dos\nexames laboratoriais de rotina pré-natal. O valor da glicemia de jejum foi de 88mg/dL. Ante o\nexposto, de acordo com a orientação do Ministério da Saúde do Brasil, como se deve prosseguir na\npesquisa diagnóstica do diabetes gestacional?","options":{"A":"Repetir a glicemia de jejum, entre 24 e 28 semanas.","B":"Indicar Teste oral de tolerância à glicose - 75g, de imediato.","C":"Fazer Teste oral de tolerância à glicose - 50g, entre 24 e 28 semanas.","D":"Solicitar Teste oral de tolerância à glicose - 75g, entre 24 e 28 semanas."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-150831","number":"150831","sourceNumber":"150831","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, assintomática, vivendo em zona endêmica de zika, preocupada com o risco\nde microcefalia fetal deseja fazer um ultrassom\npara avaliar possibilidade diagnóstica. Qual o\nparâmetro do perímetro cefálico (PC) é o LIMITE mais aceito para diagnóstico de microcefalia fetal,\nsegundo os boletins de investigação do Ministério da Saúde do Brasil?","options":{"A":"PC abaixo do percentil 5 para idade gestacional.","B":"PC abaixo do percentil 10 para idade gestacional.","C":"PC abaixo de menos 2 desvios-padrão para idade gestacional.","D":"PC abaixo de menos 3 desvios-padrão para idade gestacional."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-126931","number":"126931","sourceNumber":"126931","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, com idade gestacional de 35 semanas pela última menstruação e\nultrassonografia precoce, procura a emergência de\numa maternidade terciária referindo cefaleia\noccipital intensa, náuseas e turvação visual. Ao exame clínico: PA= 140x90mmHg, pulso = 92bpm,\nACP sem alterações, dinâmica uterina ausente e BCF=148bpm. Apresenta traços de proteína na\navaliação da urina por fita. Qual a hipótese diagnóstica e a melhor conduta?","options":{"A":"Pré-eclâmpsia grave, fazer corticoide e indicar a resolução da gestação.","B":"Pré-eclâmpsia leve, prescrever analgésico e aguardar a resolução da gestação a termo.","C":"Pré-eclâmpsia grave, iniciar sulfato de magnésio e indicar a resolução da gestação.","D":"Pré-eclâmpsia leve, iniciar sulfato de magnésio e aguardar a resolução da gestação a termo."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-81320","number":"81320","sourceNumber":"81320","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 35 anos, afrodescendente, com IMC de 28 kg/m² e pressão arterial de\n140 x 100 mmHg; realizou TTGO 75 g, com\nidade gestacional de 15 semanas, que revelou os\nseguintes resultados: jejum = 110 mg/dl e 2 horas = 210 mg/dl. Ante os achados da curva glicêmica\ne considerando os critérios atuais de diagnóstico de diabetes na gestação estabelecidos pela ADA\n(American Diabetes Association), qual o tipo de diabetes da paciente?","options":{"A":"Diabetes secundário.","B":"Diabetes mellitus\ntipo I.","C":"Diabetes mellitus gestacional.","D":"Diabetes mellitus pré-gestacional."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-51127","number":"51127","sourceNumber":"51127","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 18 anos, no curso de 36 semanas, procura a emergência obstétrica com\nepigastralgia, vômitos e visão turva. Pressão arterial: 160 x 120 mmHg. Apresenta sumário de urina\ncom proteinúria 2+. Plaquetas 45.000/mm3. Batimentos cardíacos fetais de 144 bpm, colo longo,\nposterior e fechado, feto em apresentação cefálica fletida. Qual a conduta indicada?","options":{"A":"Administrar hidralazina e sulfato de magnésio EV e induzir o parto com misoprostol sob vigilância\ncardiofetal rigorosa.","B":"Indicar cesárea sob anestesia raquidiana de imediato e, somente no pós-parto, administrar\nhidralazina e sulfato de magnésio EV por 7 dias.","C":"Acelerar maturação pulmonar com prednisona, utilizar hidralazina VO, prescrever sulfato de\nmagnésio EV e induzir o parto com ocitocina.","D":"Fazer tocólise com nifedipina sublingual, acelerar maturação pulmonar com hidrocortisona,\naplicar sulfato de magnésio EV e providenciar cesárea\ncom anestesia peridural."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-141605","number":"141605","sourceNumber":"141605","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, 20 anos, 30 semanas de gestação procurou a maternidade por cefaleia,\nepigastralgia e turvação visual. Ao exame,\napresenta-se lúcida e orientada, com edema de face,\nmãos e abdome. PA= 160/110 mmHg. No cartão do pré-natal com 2 consultas prévias, sendo a\nprimeira com 11 semanas e a última há 15 dias. Ganhou 15Kg entre a primeira e a última consulta.\nPA na primeira consulta: 100 x 60mmHg. Qual a melhor conduta?","options":{"A":"Acompanhamento ambulatorial diário, anti hipertensivo e corticoterapia.","B":"Internação imediata, corticoterapia e indução com misoprostol e ocitocina.","C":"Internação imediata, rotina laboratorial, anti-hipertensivo nos picos e sulfato de magnésio.","D":"Cesariana de urgência."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-37610","number":"37610","sourceNumber":"37610","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Bianca tem 26 anos e está grávida do seu segundo filho. Perdeu o primeiro que nasceu\nprematuro e era Grande para Idade Gestacional (GIG). Comparece à consulta de pré-natal,\napresentando pelo cálculo da DUM, 16 semanas de gestação. Refere que aumentou 1,3 kg de\npeso no último mês. Trouxe o resultado do exame de glicemia de jejum solicitado na sua primeira\nconsulta. A glicemia de jejum é de 90 mg/dl. Qual é a conduta mais adequada a ser tomada em\nrelação à Bianca?","options":{"A":"Repetir a glicemia de jejum e orientar dieta\nhipoglicídica.","B":"Solicitar o TTG (75 g em 2h) entre a 24ª e a 28ª semana de gestação.","C":"Solicitar uma hemoglobina glicada e orientar dieta.","D":"Acompanhar a gestante e solicitar nova glicemia na 30ª semana de gestação."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-30894","number":"30894","sourceNumber":"30894","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante 18 anos, G3P1A1, durante consulta pré-natal apresentou PA 140 x 100\nmmHg e proteinúria 24h = 250 mg/L. Realizou\nultrassonografia que evidenciou gestação de 32\nsemanas sem anormalidades. Qual a classificação mais adequada para essa condição clínica?","options":{"A":"Pré-eclâmpsia leve.","B":"Pré-eclâmpsia grave.","C":"Pré-eclâmpsia superajuntada.","D":"Hipertensão crônica.","E":"Hipertensão gestacional."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-32553","number":"32553","sourceNumber":"32553","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Dentre os seguintes, o sinal ou sintoma mais preocupante de uma patologia\npotencialmente grave no final da gestação é(são):","options":{"A":"Edema pré-tibial.","B":"Prisão de ventre.","C":"Azia.","D":"Alterações visuais.","E":"Nictúria."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-37008","number":"37008","sourceNumber":"37008","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 18 anos, G2P0A1, com data da última menstruação desconhecida,\ndurante consulta pré-natal apresentou PA: 150 x\n100 mmHg e proteinúria de ++/4+. Realizou\nultrassonografia que evidenciou gestação de 16 semanas com feto apresentando derrame pleural e\nascite. Qual o provável diagnóstico?","options":{"A":"Pré-eclâmpsia.","B":"Hipertensão transitória.","C":"Hipertensão crônica.","D":"Hipertensão gestacional."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-37440","number":"37440","sourceNumber":"37440","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Sueli, de 18 anos de idade está grávida de 26 semanas e chega à maternidade com\nqueixa de dor tipo cólica, sangramento transvaginal discreto, tipo perda de tampão mucoso,\ncefaleia, turvação visual e epigastralgia. O plantonista verifica sua Pressão Arterial (PA) e\ndiagnostica pré-eclâmpsia grave. Como deve estar a PA de Sueli e qual a conduta?","options":{"A":"Pressão arterial acima de 160 x 110 mmHg, interrupção da gravidez imediatamente.","B":"Pressão arterial acima de 160 x 110 mmHg, primeiro estabilizar a PA de Sueli.","C":"Pressão arterial acima de 160 x 110 mmHg , uso imediato de diurético.","D":"Só posso fazer diagnóstico de pré-eclâmpsia grave se tiver síndrome HELLP.","E":"Como o concepto é prematuro deve ser feito corticoide inicialmente."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-37452","number":"37452","sourceNumber":"37452","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Dona Eugênia, casada, branca, grávida (3º trimestre), quadrigesta e em tratamento de\nhipertensão arterial crônica com metildopa, comparece ao plantão médico com queixa de\ngengivorragia, vômitos, dor em hipocôndrio direito, cefaleia frontal e pele amarelada. Quais dos\nitens abaixo poderiam confirmar a suspeita diagnóstica mais provável para Dona Eugênia?","options":{"A":"Hemólise, presença de esquizócitos (> 5%), proteinúria. Síndrome HELLP.","B":"Alto teor de hemoglobina livre, aminotransferase elevada, trombocitopenia. Síndrome HELLP.","C":"Cisão eritrocitária, presença de esquizócitos, elevação de enzimas hepáticas. Síndrome\nhemolítico-urêmica.","D":"Proteinúnia, plaquetopenia e enzimas hepáticas alteradas. Síndrome hemolítico-urêmica.","E":"Enzimas hepáticas (TGO e TGP) alteradas, presença de hemólise e esquizócitos. Síndrome\nHELLP."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-25313","number":"25313","sourceNumber":"25313","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente no curso da 30ª semana de gravidez, proveniente do interior, onde apresentou\nquadro convulsivo há 6 horas, vinha sob uso de\nsulfato de magnésio e apresentava diurese de 15\nml/h, diminuição dos reflexos patelares e frequência respiratória de 10 rpm. A dosagem sérica do\nmagnésio foi de 20 mEq/L. Neste caso, a melhor conduta é:","options":{"A":"Suspender o sulfato e fazer gluconato de cálcio a 10%.","B":"Suspender o sulfato e iniciar hidantoína.","C":"Manter o sulfato e fazer cesárea.","D":"Manter o sulfato e fazer gluconato de cálcio a 10%.","E":"Manter o sulfato e fazer também hidantoína."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-25317","number":"25317","sourceNumber":"25317","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente com gestação gemelar monocoriônica, monoamniótica, na 28ª semana, é\nadmitida com óbito de um dos gemelares. Neste caso, para o feto vivo, há incremento de risco de:","options":{"A":"Infecção intrauterina.","B":"Encefalomalácia multicística.","C":"Coagulação intravascular disseminada.","D":"Insuficiência renal com posterior oligoidrâmnio.","E":"Acardia fetal."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-25335","number":"25335","sourceNumber":"25335","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante 34 anos, G4P2A1, com DUM desconhecida, durante consulta pré-natal\napresentou PA 150 X 100 mmHg e proteinúria de\n++/4+. Realizou ultrassonografia que evidenciou\ngestação de 18 semanas sem anormalidades. Qual o provável diagnóstico?","options":{"A":"Pré-eclâmpsia leve","B":"Pré-eclâmpsia grave","C":"Pré-eclâmpsia superajuntada","D":"Hipertensão crônica","E":"Hipertensão gestacional"},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-25340","number":"25340","sourceNumber":"25340","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Sueli, 18 anos, está grávida de 26 semanas. Chega à Maternidade Escola Assis\nChateaubriand com queixa de dor em cólica, sangramento transvaginal discreto, tipo perda de\ntampão mucoso, cefaleia, turvação visual e epigastralgia. O plantonista verifica sua PA e\ndiagnostica pré-eclampsia grave. Qual deve ser a PA de Sueli e qual a conduta?","options":{"A":"pressão arterial acima de 160/110 mmHg, interrupção da gravidez imediatamente.","B":"pressão arterial acima de 160/110 mmHg, primeiro estabilizar a PA de Sueli.","C":"pressão arterial acima de 160/110 mmHg , uso imediato de diurético.","D":"só posso fazer diagnóstico de pré-eclampsia grave se tiver síndrome de HELLP.","E":"como o bebê é prematuro deve ser feito corticoide imediatamente."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-25344","number":"25344","sourceNumber":"25344","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 19 anos, G1P0, idade gestacional de 35 semanas, trazida à emergência com\nquadro de convulsão tonicoclônica generalizada. Acompanhante relata que a paciente era\nsaudável, sem convulsão prévia ou intercorrência no pré-natal. Ao exame: PA 160 x 100 mmHg,\ndesorientada, BCF 122 bpm e ausência de contração uterina. Qual a melhor conduta?","options":{"A":"Hidralazina EV até PA reduzir para 120 x 80 mmHg.","B":"Verificar vias aéreas superiores, acesso venoso e parto imediato.","C":"<P>Sulfato de Magnésio, mesmo se diurese e função renal desconhecida.</P>","D":"Fenitoína EV e solicitar ultrassom para confirmar idade gestacional.","E":"Estabilizar a paciente e encaminhá-la para pesquisa de maturidade fetal."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-25345","number":"25345","sourceNumber":"25345","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante com 23 semanas, procura emergência devido à dor no membro inferior\nesquerdo. Ao exame: PA 120 x 70 mmHg, Pulso 96 bpm, panturrilha esquerda hiperemiada,\ndolorosa à palpação e com circunferência aumentada de 3 cm comparando-se com a direita.\nAusência de trauma ou ferimentos em membros inferiores (MMII). Qual a melhor conduta?","options":{"A":"Heparina em dose terapêutica e programar US com Doppler de MMII.","B":"Penicilina cristalina IV, 4/4h e programar US com Doppler de MMII.","C":"Penicilina cristalina IV, 4/4h e programar venografia.","D":"Heparina em dose profilática e programar US com Doppler de MMII.","E":"Iniciar cumarínico e programar venografia."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-27700","number":"27700","sourceNumber":"27700","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 17 anos chega à emergência da maternidade com 36 semanas, PA 170 x\n110 mmHg, cefaleia e escotomas cintilantes.\nFCF 144 bpm. Durante o exame físico apresenta\nepisódio convulsivo tonicoclônico generalizado. Indique a conduta imediata mais adequada a ser\ntomada.","options":{"A":"Cânula de Guedel, O2 por cateter, diazepam EV e cesárea imediata","B":"Acesso venoso, O2 por cateter, hidralazina EV e metildopa VO","C":"O2 por cateter, cânula de Guedel, sulfato de magnésio e rotina laboratorial","D":"Acesso venoso, sulfato de magnésio, hidralazina e cesárea imediata","E":"Sulfato de magnésio, hidralazina, metildopa e corticoterapia"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-27711","number":"27711","sourceNumber":"27711","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente G4P1A3 (3 abortamentos espontâneos entre 6-8 semanas seguidos de parto\nvaginal de feto morto com 28 semanas por DPPNI) chega ao consultório para consulta pré-natal\ncom diagnóstico de síndrome do anticorpo antifosfolípide. Qual a melhor conduta no caso?","options":{"A":"Suplementação de progesterona via vaginal até 12 semanas e AAS 100 mg/dia do diagnóstico\naté o final da gestação.","B":"Enoxaparina 40 mg/dia + AAS 100 mg/dia do diagnóstico até o final da gestação.","C":"Enoxaparina 40 mg/dia no 1° e 3° trimestre e warfarin 5 mg/dia no 2º trimestre + AAS 100 mg/dia\ntoda a gestação.","D":"Warfarin 5 mg/dia + AAS 100 mg/dia do diagnóstico até o final da gestação.","E":"AAS 100 mg/dia a partir de 14 semanas até o final da gestação."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-6899","number":"6899","sourceNumber":"6899","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Qual critério NÃO caracteriza pré-eclâmpsia grave?","options":{"A":"PA (maior ou igual) 160 x 110 mmHg","B":"Proteinúria (maior ou igual) 5 g/24h","C":"Plaquetas < 100.000","D":"Ácido úrico > 8,0","E":"Creatinina > 1,2"},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-6907","number":"6907","sourceNumber":"6907","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"VVT, 18 anos, com idade gestacional de 34 semanas, apresentando elevação dos\nníveis pressóricos. Realizou dopplerfluxometria fetal que mostrou artéria umbilical com índice de\nresistência de 0,9 e artéria cerebral média com índice de resistência de 0,7. Estes achados\nsugerem:","options":{"A":"Normalidade.","B":"Diminuição da resistência em artéria uterina.","C":"Centralização fetal.","D":"Descentralização fetal.","E":"Aumento da resistência em artéria cerebral média."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-9124","number":"9124","sourceNumber":"9124","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A síndrome hipertensiva está entre as causas mais frequentes de óbito materno. É uma\ndas atribuições da Estratégia de Saúde da\nFamília reduzir a morbimortalidade materno-infantil. Com\nrelação às síndromes hipertensivas na gestação, assinale a alternativa INCORRETA:","options":{"A":"Eclâmpsia é a ocorrência de convulsões motoras generalizadas (tipo grande mal), em gestante\ncom pré-eclâmpsia, não devidas à doença neurológica\nsubjacente.","B":"A hipertensão arterial percebida antes da 20º semana de gestação ou que persiste após o 42º\ndia pós-parto é classificada como doença hipertensiva específica da gravidez (DHEG).","C":"Algumas vezes pode haver associação entre pré-eclâmpsia e hipertensão arterial crônica.","D":"Em gestantes com pré-eclâmpsia, não há nenhuma razão que justifique a permanência\nintraútero de um feto com maturidade pulmonar."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-9107","number":"9107","sourceNumber":"9107","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação à hepatite B em gestantes é CORRETO afirmar que:","options":{"A":"A gestação favorece o aparecimento da infecção e agrava o curso da doença.","B":"O diagnóstico diferencial deve ser feito com icterícia colestática, colelitíase, síndrome HELLP,\nfígado gorduroso agudo da gestação e farmacotoxicidade.","C":"Os neonatos infectados pelo vírus têm 30% de chance de se tornarem portadores crônicos.","D":"Se o rastreamento no pré-natal com o HBsAg for positivo, os recém nascidos devem receber\napenas a imunoglobulina imediatamente após o\nnascimento."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-8913","number":"8913","sourceNumber":"8913","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma puérpera traz seu bebê para a primeira avaliação na atenção primária, 15 dias\napós o parto. A mãe é ansiosa, queixa-se de\nintolerância ao calor e fadiga, e relata que não ganha\nmuito peso apesar do marcante aumento no apetite. Ao exame, a mãe está taquicárdica, tem um\ntremor, apresenta exoftalmia e um aumento palpável na região cervical. O bebê tem risco\naumentado para o desenvolvimento de:","options":{"A":"Constipação","B":"Insuficiência cardíaca","C":"Macrocefalia","D":"Bloqueio cardíaco de terceiro grau","E":"Trombocitose"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-17866","number":"17866","sourceNumber":"17866","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gravidez gemelar em que ocorre a fertilização de dois óvulos em coitos diferentes,\nno mesmo ciclo menstrual, tem seu processo\ndenominado:","options":{"A":"superfetação","B":"superfecundação","C":"gemelidade imperfeita","D":"monozigotia","E":"poliembrionia"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-17870","number":"17870","sourceNumber":"17870","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Segundo a classificação de Priscilla White para Diabetes, uma gestante com nefropatia\ndiabética, pertenceria à classe:","options":{"A":"A","B":"B","C":"C","D":"D","E":"F"},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-349686","number":"349686","sourceNumber":"349686","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 36 semanas chega ao pronto-socorro apresentando PA de 160x100\nMmHg associada à turvação visual e cefaleia. A\nvitalidade fetal está preservada. Diante desse\ncaso, qual é a melhor conduta?","options":{"A":"Iniciar Metildopa 250 mg uma vez ao dia para controle pressórico.","B":"Nitroprussiato de sódio é a primeira opção para esse quadro.","C":"Realizar dipirona e aferir a pressão arterial após 4 horas da analgesia.","D":"Indicar a cesárea de forma imediata, visto que só haverá controle pressórico após a resolução\nda gestação.","E":"Realizar sulfato de magnésio a 50% e deixar aspirado gluconato de cálcio em cabeceira do leito."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-349682","number":"349682","sourceNumber":"349682","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Considerando as alternativas a seguir, qual apresenta uma indicação de investigação\npara trombofilias adquiridas?","options":{"A":"Quadro de trombose venosa profunda após trauma.","B":"Investigação recomendada após o 1° quadro de aborto.","C":"História familiar positiva para tromboembolismo venoso.","D":"Se houver necrose de pele associada ao uso de antagonistas da vitamina K.","E":"Perda fetal tardia."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-365586","number":"365586","sourceNumber":"365586","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Quanto às condições inerentes ao estado gestacional, assinale a alternativa\ncorrespondente à medida ou à droga que não é recomendada para diminuição do risco de\npré-eclâmpsia.","options":{"A":"Aspirina","B":"Metildopa","C":"Suplementação de cálcio caso o consumo seja menor do que 900 mg por dia","D":"Atividade física por pelo menos 140 minutos por semana"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-365607","number":"365607","sourceNumber":"365607","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 23 anos de idade, G2P1, 1G = 32 semanas, compareceu ao\n\npronto-socorro referindo cefaleia e epigastralgia. Em seu cartão de pré-natal, consta que o aumento\npressórico ocorreu a partir de 24 semanas. Ao exame físico, apresentou FC = 98 bpm, PA = 158\nmmHg x 75 mmHg, FR = 20 irpm, SpO2 = 97%, e BCF = 158 bpm. Realizou exames laboratoriais,\ncujos resultados foram os seguintes: TGO = 24 U/L; TGP = 18U/L; DHL = 230 U/L; Cr = 1,0 mg/dL;\nrelação proteína/creatinina = 0,2; e plaquetas = 100.000/mm³. Diante desse quadro, qual é o\ndiagnóstico dessa paciente?","options":{"A":"Pré-eclampsia","B":"Hipertensão gestacional","C":"Pré-eclâmpsia sobreposta","D":"Hipertensão crônica"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-322195","number":"322195","sourceNumber":"322195","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação à síndrome HELLP, assinale a alternativa INCORRETA.","options":{"A":"Plaquetas abaixo de 50.000 são contraindicação à anestesia raquidiana.","B":"A cesárea é a via de parto de melhor escolha na síndrome HELLP.","C":"Pode ocorrer síndrome HELLP sem elevação dos níveis pressóricos.","D":"O sulfato de magnésio é indicado quando se apresentar esse diagnóstico.","E":"Pacientes com passado obstétrico de síndrome HELLP devem ser alertadas quanto ao maior\nrisco de apresentar o mesmo quadro em gestação futura."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-322197","number":"322197","sourceNumber":"322197","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 23 semanas, refere que não fez nenhum dos exames solicitados na rotina de\nprimeiro trimestre. Nega doenças prévias; o peso pré-gestacional era 80 kg e, atualmente, está com\n90 kg, sendo que a altura é de 1,60 m. Considerando a disponibilidade técnica adequada, a melhor\nconduta para o diagnóstico de diabetes gestacional é solicitar","options":{"A":"hemoglobina glicada e glicemia de jejum no momento da consulta.","B":"teste oral de tolerância à glicose com 100g em jejum e duas horas após sobrecarga.","C":"teste oral de tolerância à glicose com 75 g em jejum de duas horas imediatamente.","D":"apenas hemoglobina glicada.","E":"teste oral de tolerância à glicose com 75 g em jejum, uma e duas horas após sobrecarga, entre\n24 e 28 semanas."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-337565","number":"337565","sourceNumber":"337565","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Juliana, G1, está com 31 semanas e comparece na consulta de pré-natal para mostrar\nalguns exames de rotina. Dentre os exames, o\nteste oral de tolerância à glicose demonstra os\nseguintes valores: 95 mg/dl em jejum; 160 mg/dl uma hora após e 155 duas horas após. Em\nrelação ao caso clínico relatado, considerando os valores de exames apresentados, julgue o item a\nseguir. É necessário solicitar o controle glicêmico e orientar sobre alimentação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-322200","number":"322200","sourceNumber":"322200","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 22 semanas comparece ao consultório referindo disúria e polaciúria há 3\ndias. Nega outras queixas. Trouxe exame de urocultura realizado há 3 dias que evidenciou E.Coli.\nO antibiograma mostrou que a bactéria em questão era sensível aos seguintes fármacos:\nnitrofurantoína, ampicilina, ciprofloxacino e norfloxacino. Refere que já é o terceiro quadro de\ninfecção do trato urinário durante essa gestação. Nesse caso, a conduta mais adequada é\nprescrever","options":{"A":"ciprofloxacino 500 mg de 12/12 horas por 7 dias.","B":"norfloxacino 400 mg uma vez ao dia por 3 dias.","C":"nitrofurantoína 100 mg de 6/6 horas por 5 dias.","D":"ampicilina 500 mg de 6/6 horas por 7 dias seguido de nitrofurantoína profilática uma vez ao dia.","E":"nitrofurantoína 100 mg de 6/6 horas por 7 dias."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-337566","number":"337566","sourceNumber":"337566","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Juliana, G1, está com 31 semanas e comparece na consulta de pré-natal para mostrar\nalguns exames de rotina. Dentre os exames, o\nteste oral de tolerância à glicose demonstra os\nseguintes valores: 95 mg/dl em jejum; 160 mg/dl uma hora após e 155 duas horas após. Em\nrelação ao caso clínico relatado, considerando os valores de exames apresentados, julgue o item a\nseguir. Iniciar insulina NPH 0,3 UI/KG por dia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-337567","number":"337567","sourceNumber":"337567","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Juliana, G1, está com 31 semanas e comparece na consulta de pré-natal para mostrar\nalguns exames de rotina. Dentre os exames, o\nteste oral de tolerância à glicose demonstra os\nseguintes valores: 95 mg/dl em jejum; 160 mg/dl uma hora após e 155 duas horas após. Em\nrelação ao caso clínico relatado, considerando os valores de exames apresentados, julgue o item a\nseguir. Apenas um valor do teste oral se encontra alterado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-322202","number":"322202","sourceNumber":"322202","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 39 anos, com antecedente de dois partos cesáreas pré-termo devido à\n\npré-eclâmpsia, deseja programar nova gravidez. É hipertensa crônica com bom controle pressórico.\nNesse caso, é necessário:","options":{"A":"Orientar que ela deve evitar uma nova gravidez por ser hipertensa.","B":"Orientar que, considerando a idade avançada, uma nova gestação está contraindicada.","C":"Orientar que ela deve iniciar heparina de baixo peso molecular no primeiro trimestre a fim de\nreduzir o risco de trombose.","D":"Orientar que existe risco de pré-eclâmpsia na futura gestação e que, caso engravide, ela tem\nrecomendação de profilaxia de pré-eclâmpsia.","E":"Prescrever AAS e heparina de baixo peso molecular no início da futura gestação."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-337568","number":"337568","sourceNumber":"337568","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Juliana, G1, está com 31 semanas e comparece na consulta de pré-natal para mostrar\nalguns exames de rotina. Dentre os exames, o\nteste oral de tolerância à glicose demonstra os\nseguintes valores: 95 mg/dl em jejum; 160 mg/dl uma hora após e 155 duas horas após. Em\nrelação ao caso clínico relatado, considerando os valores de exames apresentados, julgue o item a\nseguir. Indicar resolução do parto com 37 semanas devido ao diabetes gestacional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-337569","number":"337569","sourceNumber":"337569","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Juliana, G1, está com 31 semanas e comparece na consulta de pré-natal para mostrar\nalguns exames de rotina. Dentre os exames, o\nteste oral de tolerância à glicose demonstra os\nseguintes valores: 95 mg/dl em jejum; 160 mg/dl uma hora após e 155 duas horas após. Em\nrelação ao caso clínico relatado, considerando os valores de exames apresentados, julgue o item a\nseguir. Apenas um valor alterado do teste oral já diagnostica diabetes gestacional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-337570","number":"337570","sourceNumber":"337570","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Juliana, G1, está com 31 semanas e comparece na consulta de pré-natal para mostrar\nalguns exames de rotina. Dentre os exames, o\nteste oral de tolerância à glicose demonstra os\nseguintes valores: 95 mg/dl em jejum; 160 mg/dl uma hora após e 155 duas horas após. Em\nrelação ao caso clínico relatado, considerando os valores de exames apresentados, julgue o item a\nseguir. Controle alimentar e atividade física podem ser recomendados no caso descrito.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-305327","number":"305327","sourceNumber":"305327","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, 28 anos, obesa, vem para a consulta de pré-natal de sua segunda gestação\npreocupada com o resultado do seu teste oral de tolerância à glicose com 75mg de glicose\n(TOTG-75), visto que teve diabetes gestacional em sua última gravidez. No dia da consulta, a\npaciente se encontra com 26 semanas e 3 dias de gestação e traz o resultado de sua glicemia de\njejum realizada na primeira consulta pré-natal, com o seguinte resultado: 89mg/dl. Traz também\n\nTOTG-75, com os resultados: glicemia de jejum 91mg/dl, após 1h da ingesta: 176mg/dl, e, após 2h:\n140mg/dl. Sendo assim, o médico deve informar a paciente que","options":{"A":"ela possui diabetes gestacional e o tratamento deve ser com dieta e exercícios físicos.","B":"ela possui diabetes gestacional e o tratamento deve ser com insulina.","C":"ela possui diabetes pré-gestacional (preexistente) e deve iniciar dieta e exercícios físicos.","D":"ela possui diabetes pré-gestacional (preexistente) e o tratamento deve ser instituído com\nmetformina.","E":"ela não possui diabetes gestacional, mas, por ter histórico e outros fatores de risco, deve ficar\natenta e seguir rotina com alimentação saudável e exercícios para prevenção."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-305335","number":"305335","sourceNumber":"305335","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 37 anos, tabagista, idade gestacional de 34 semanas, vai à maternidade\nqueixando-se de cefaleia intensa, epigastralgia e alterações visuais. Exame físico: AFU 30 cm, MF\n\n+, DU negativa, PA 160/120 mmHg. O diagnóstico mais provável e a medicação indicada nesse\nmomento são, respectivamente:","options":{"A":"síndrome HELLP e hidralazina intravenosa.","B":"eclâmpsia e benzodiazepínico.","C":"pré-eclâmpsia grave e metildopa.","D":"pré-eclâmpsia grave e sulfato de magnésio.","E":"eclâmpsia e sulfato de magnésio."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-274403","number":"274403","sourceNumber":"274403","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Após ultrassom de primeiro trimestre, uma gestante tem como diagnóstico uma\ngestação múltipla dicoriônica e diamniótica. Diante dessa situação, é correto afirmar que","options":{"A":"gêmeo arcádico é uma complicação possível.","B":"o risco de malformação é sempre o mesmo para os fetos.","C":"o sinal do lambda é observado somente na gestação monocoriônica.","D":"pode ter como complicação a síndrome da transfusão feto-fetal.","E":"pode ser monozigótica ou dizigótica."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-274405","number":"274405","sourceNumber":"274405","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 17 semanas, queixa-se de sintomas urinários durante um atendimento do\npré-natal. O diagnóstico realizado foi de uma infecção do trato urinário (ITU) não complicada. Sobre\nas ITU na gestação, é correto afirmar que","options":{"A":"a conduta expectante com analgesia e hidratação é a primeira linha de tratamento.","B":"a ITU sintomática deve ser tratada somente após resultado da urocultura.","C":"a nitrofurantoína deve ser evitada em ITU de terceiro trimestre por risco de hemólise em fetos\ncom possível deficiência de G6PD.","D":"quinolonas são opções de primeira linha para o tratamento de cistite não complicada.","E":"tratando-se de uma gestante, a internação com medicamento endovenoso é mandatória."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-284342","number":"284342","sourceNumber":"284342","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Na gravidez, na maioria das vezes em que ocorre o edema pulmonar, a etiologia é não\ncardiogênica, sendo a pré-eclâmpsia uma das principais causas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-261056","number":"261056","sourceNumber":"261056","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Determinada gestante de 32 semanas, considerando a ultrassonografia realizada com\n10 semanas, com glicemia de jejum feita no\nprimeiro trimestre, cujo resultado foi de 95, realizou\npré-natal de alto risco, com seguimento regular, em uso de insulina NPH 10 UI pela manhã, 8 UI no\nalmoço e 8 UI à noite. Novo exame de ultrassonografia efetuado hoje demonstra feto único;\ncefálico; 2.410 (p100); com maior bolsão vertical de 12 cm, com Doppler habitual; índice de\npulsatilidade (IP) da artéria umbilical = 0,98; e IP da artéria cerebral média = 2,1. Tendo em vista\nesse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. Trata-se de\ndiabetes gestacional, diagnosticada no primeiro trimestre, por causa de glicemia de jejum acima de\n92, com necessidade de tratamento com insulina desde o início do pré-natal pelo risco de\nmalformações cardíacas fetais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-284345","number":"284345","sourceNumber":"284345","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A gravidez em si é uma condição que predispõe a ocorrência de pneumonia bacteriana\nem mulheres.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-284346","number":"284346","sourceNumber":"284346","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O risco de trombose venosa e embolia pulmonar em mulheres saudáveis é considerado\ncomo mais elevado durante o ciclo\ngravidez/puerpério.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-261061","number":"261061","sourceNumber":"261061","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Determinada gestante de 32 semanas, considerando a ultrassonografia realizada com\n10 semanas, com glicemia de jejum feita no\nprimeiro trimestre, cujo resultado foi de 95, realizou\npré-natal de alto risco, com seguimento regular, em uso de insulina NPH 10 UI pela manhã, 8 UI no\nalmoço e 8 UI à noite. Novo exame de ultrassonografia efetuado hoje demonstra feto único;\ncefálico; 2.410 (p100); com maior bolsão vertical de 12 cm, com Doppler habitual; índice de\npulsatilidade (IP) da artéria umbilical = 0,98; e IP da artéria cerebral média = 2,1. Tendo em vista\nesse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. A malformação\nmais observada nas pacientes com diabetes gestacional refere-se à síndrome de regressão caudal\ne a malformações cardíacas, principalmente em razão de hiperglicemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-261293","number":"261293","sourceNumber":"261293","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 35 anos de idade, G1, idade gestacional de 19 semanas, realizando\npré-natal regular na unidade básica de saúde\n(UBS), procura a emergência obstétrica por pressão\narterial aferida adequadamente, durante a consulta de pré-natal no dia anterior, de 150 mmHg x 92\nmmHg. À chegada, a paciente queixa-se de cefaleia e dor epigástrica leve. Verificam-se os\nseguintes sinais vitais: PA = 140 mmHg x 90 mmHg; FC = 102 bpm; FR = 18 irpm; e SatO2 = 98%.\nAcerca desse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a\nseguir. É possível considerar que a paciente possui diagnóstico de hipertensão arterial crônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-261294","number":"261294","sourceNumber":"261294","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 35 anos de idade, G1, idade gestacional de 19 semanas, realizando\npré-natal regular na unidade básica de saúde\n(UBS), procura a emergência obstétrica por pressão\narterial aferida adequadamente, durante a consulta de pré-natal no dia anterior, de 150 mmHg x 92\nmmHg. À chegada, a paciente queixa-se de cefaleia e dor epigástrica leve. Verificam-se os\nseguintes sinais vitais: PA = 140 mmHg x 90 mmHg; FC = 102 bpm; FR = 18 irpm; e SatO2 = 98%.\nAcerca desse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a\nseguir. Deve ser realizado rastreamento para pré-eclâmpsia em vista da presença de sinais\npremonitórios; cefaleia e dor epigástrica leve.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-250152","number":"250152","sourceNumber":"250152","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 26 anos de idade, primípara, iniciou acompanhamento pré-natal já\ncom trinta e duas semanas de gestação. Negou\nquaisquer diagnósticos prévios e uso contínuo de\nmedicações. A primeira avaliação médico evidenciou pressão arterial de 150/90 mmHg. Foram\nsolicitados exames complementares. Na segunda avaliação, já com 35 semanas de gestação, a\npressão arterial da paciente foi aferida em 160/100 mmHg e os exames laboratoriais evidenciaram\ncreatinina: 1,3 mg/dl e plaquetas: 95.000. Não foi evidenciado proteinúria. Com base nesse caso\nhipotético, julgue o item a seguir. A paciente não tem critérios diagnósticos para pré-eclâmpsia,\npois\nnão foi evidenciada proteinúria.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-250153","number":"250153","sourceNumber":"250153","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 26 anos de idade, primípara, iniciou acompanhamento pré-natal já\ncom trinta e duas semanas de gestação. Negou\nquaisquer diagnósticos prévios e uso contínuo de\nmedicações. A primeira avaliação médico evidenciou pressão arterial de 150/90 mmHg. Foram\nsolicitados exames complementares. Na segunda avaliação, já com 35 semanas de gestação, a\npressão arterial da paciente foi aferida em 160/100 mmHg e os exames laboratoriais evidenciaram\ncreatinina: 1,3 mg/dl e plaquetas: 95.000. Não foi evidenciado proteinúria. Com base nesse caso\nhipotético, julgue o item a seguir. A evidência de trombocitopenia é sugestiva de síndrome HELLP e\nsinaliza maior risco de sangramento cerebral, hepático e durante o parto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-250154","number":"250154","sourceNumber":"250154","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 26 anos de idade, primípara, iniciou acompanhamento pré-natal já\ncom trinta e duas semanas de gestação. Negou quaisquer diagnósticos prévios e uso contínuo de\nmedicações. A primeira avaliação médico evidenciou pressão arterial de 150/90 mmHg. Foram\nsolicitados exames complementares. Na segunda avaliação, já com 35 semanas de gestação, a\npressão arterial da paciente foi aferida em 160/100 mmHg e os exames laboratoriais evidenciaram\ncreatinina: 1,3 mg/dl e plaquetas: 95.000. Não foi evidenciado proteinúria. Com base nesse caso\nhipotético, julgue o item a seguir. Está indicada para a paciente a interrupção da gravidez após\n\n24-48 h de uso de corticoide.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-239336","number":"239336","sourceNumber":"239336","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Considerando os estudos acerca da síndrome antifosfolipídio (SAF), julgue o item a\nseguir. É uma causa de abortamento habitual e pode apresentar anticorpo lúpus anticoagulante\ncirculante.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-255758","number":"255758","sourceNumber":"255758","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Determinada primigesta de 20 anos de idade, sem parceiros sexuais fixos, com oito\nepisódios anuais de infecção urinária do trato inferior, buscou atendimento após um período de\ntempo, depois de sofrer estupro. Na consulta, refere desejo de abortar. Além disso, a paciente\napresenta lúpus eritematoso sistêmico, com anti-RO positivo. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. A probabilidade de a criança nascer com\nbloqueio atrioventricular total é maior do que em mães com esse anticorpo negativo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-239343","number":"239343","sourceNumber":"239343","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante com 35 semanas de idade gestacional dá entrada no pronto atendimento\nobstétrico com queixa de cefaleia intensa e\n\"visão embaçada\". Notou ainda que vem urinando\npouco ao longo dos últimos dois dias. Ao exame, não há dinâmica uterina, BCF = 90 bpm, e o colo\né grosso, pérvio para uma polpa digital ao toque vaginal. Apresenta PA = 160 mmHg x 110 mmHg\nem duas aferições, frequência cardíaca = 102 bpm, frequência respiratória = 20 ipm e SatO? = 97%\nem ar ambiente. Amostra isolada de urina com 3+ de proteinúria. Considerando esse caso clínico e\nos conhecimentos médicos correlatos, julgue o item a seguir. O caso deve ser classificado como\npré-eclâmpsia grave, devendo-se iniciar indução do parto vaginal com misoprostol e avaliação\nrigorosa de bem-estar fetal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-239344","number":"239344","sourceNumber":"239344","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante com 35 semanas de idade gestacional dá entrada no pronto atendimento\nobstétrico com queixa de cefaleia intensa e\n\"visão embaçada\". Notou ainda que vem urinando\npouco ao longo dos últimos dois dias. Ao exame, não há dinâmica uterina, BCF = 90 bpm, e o colo\né grosso, pérvio para uma polpa digital ao toque vaginal. Apresenta PA = 160 mmHg x 110 mmHg\nem duas aferições, frequência cardíaca = 102 bpm, frequência respiratória = 20 ipm e SatO? = 97%\nem ar ambiente. Amostra isolada de urina com 3+ de proteinúria. Considerando esse caso clínico e\nos conhecimentos médicos correlatos, julgue o item a seguir. O manejo inicial da paciente deve\nincluir, obrigatoriamente, um anti-hipertensivo como hidralazina e sulfato de magnésio, atentando\npara sinais de intoxicação por esse último.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-239345","number":"239345","sourceNumber":"239345","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante com 35 semanas de idade gestacional dá entrada no pronto atendimento\nobstétrico com queixa de cefaleia intensa e\n\"visão embaçada\". Notou ainda que vem urinando\npouco ao longo dos últimos dois dias. Ao exame, não há dinâmica uterina, BCF = 90 bpm, e o colo\né grosso, pérvio para uma polpa digital ao toque vaginal. Apresenta PA = 160 mmHg x 110 mmHg\nem duas aferições, frequência cardíaca = 102 bpm, frequência respiratória = 20 ipm e SatO? = 97%\nem ar ambiente. Amostra isolada de urina com 3+ de proteinúria. Considerando esse caso clínico e\nos conhecimentos médicos correlatos, julgue o item a seguir. Caso os exames complementares\nevidenciassem esquizócitos, LDH > 600 UI/L, AST > 70 UI/L e plaquetas < 160.000/mm³, estaria\nconfirmada a síndrome de HELLP.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-255767","number":"255767","sourceNumber":"255767","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Certa gestante com IG 26 semanas procura a equipe da Estratégia Saúde da Família\n(ESF) para consulta de pré-natal, levando\nexames realizados, com níveis pressóricos aumentados\nnas últimas duas semanas. A paciente nega história prévia de hipertensão arterial. Ao exame,\nverificaram-se BCF = 132; MF presentes; AU = 24 cm; toque = colo uterino grosso, fechado,\nposterior, sem edemas. PA = 150 mmHg x 90 mmHg; FC = 72 bpm; FR = 15; SpO2 = 99%; peso =\n71 kg; e estatura = 1,71. Exames laboratoriais: proteinúria de 24 horas = 117 mg; ácido úrico = 2,3;\nplaquetas = 190.000. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Esse quadro de hipertensão arterial pode ser classificado como\nhipertensão gestacional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-255770","number":"255770","sourceNumber":"255770","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Certa gestante com IG 26 semanas procura a equipe da Estratégia Saúde da Família\n(ESF) para consulta de pré-natal, levando\nexames realizados, com níveis pressóricos aumentados\nnas últimas duas semanas. A paciente nega história prévia de hipertensão arterial. Ao exame,\nverificaram-se BCF = 132; MF presentes; AU = 24 cm; toque = colo uterino grosso, fechado,\nposterior, sem edemas. PA = 150 mmHg x 90 mmHg; FC = 72 bpm; FR = 15; SpO2 = 99%; peso =\n71 kg; e estatura = 1,71. Exames laboratoriais: proteinúria de 24 horas = 117 mg; ácido úrico = 2,3;\nplaquetas = 190.000. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O enalapril é uma opção de anti-hipertensivo para uso na\ngestação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-196688","number":"196688","sourceNumber":"196688","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Determinada mulher de 25 anos de idade recebeu o diagnóstico de gravidez, e o\nmédico solicitou exames de rotina como glicemia de jejum (126 mg/dL), toxoplasmose IgM e IgG\nnão reagentes. Além disso, requisitou anti-HIV não reagente. O ultrassom é compatível com oito\nsemanas e três dias de gestação. Acerca desse caso clínico, julgue o item a seguir. A paciente\napresenta diabetes gestacional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-196711","number":"196711","sourceNumber":"196711","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 32 anos de idade, G3P2A0, gestação gemelar, idade gestacional (IG)\nde 32 semanas, procura atendimento em\nemergência obstétrica por fadiga, dor torácica e\npalpitações. Refere histórico de pré-eclâmpsia na última gestação. Relata hipertensão arterial\nsistêmica na gestação atual e nega outras comorbidades. Ao exame físico, encontram-se\ncardiomegalia, terceira bulha, ritmo irregular e murmúrio de regurgitação mitral. Solicita-se\necocardiografia com Doppler, que documenta aumento das quatro câmaras cardíacas, com\nredução marcada da função sistólica esquerda. Acerca desse caso clinico, julgue o item a seguir. O\nprincipal diagnóstico é miocardiopatia periparto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-196714","number":"196714","sourceNumber":"196714","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 32 anos de idade, G3P2A0, gestação gemelar, idade gestacional (IG)\nde 32 semanas, procura atendimento em\nemergência obstétrica por fadiga, dor torácica e\npalpitações. Refere histórico de pré-eclâmpsia na última gestação. Relata hipertensão arterial\nsistêmica na gestação atual e nega outras comorbidades. Ao exame físico, encontram-se\ncardiomegalia, terceira bulha, ritmo irregular e murmúrio de regurgitação mitral. Solicita-se\necocardiografia com Doppler, que documenta aumento das quatro câmaras cardíacas, com\nredução marcada da função sistólica esquerda. Acerca desse caso clinico, julgue o item a seguir.\n\nUso de terapia anticoagulante deve ser considerado, em razão do aumento da incidência de\neventos tromboembólicos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-196715","number":"196715","sourceNumber":"196715","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 32 anos de idade, G3P2A0, gestação gemelar, idade gestacional (IG)\nde 32 semanas, procura atendimento em\nemergência obstétrica por fadiga, dor torácica e\npalpitações. Refere histórico de pré-eclâmpsia na última gestação. Relata hipertensão arterial\nsistêmica na gestação atual e nega outras comorbidades. Ao exame físico, encontram-se\ncardiomegalia, terceira bulha, ritmo irregular e murmúrio de regurgitação mitral. Solicita-se\necocardiografia com Doppler, que documenta aumento das quatro câmaras cardíacas, com\nredução marcada da função sistólica esquerda. Acerca desse caso clinico, julgue o item a seguir.\n\nVasodilatadores devem ser considerados, sendo a hidralazina um deles.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-196606","number":"196606","sourceNumber":"196606","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher na 36ª semana de gestação sofreu queda ao solo e foi encaminhada ao hospital\ncom pressão arterial de 130 mmHg x 80 mmHg, frequência cardíaca de 100 bpm e saturação de\n97% em ar ambiente. Apresentava fortes náuseas durante o atendimento médico, e também\nescoriações em região pélvica. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Como o esvaziamento gástrico é demorado, e o esfíncter\nesofágico inferior apresenta tônus diminuído na gestante, deve-se sempre ter em mente o risco de\naspiração de conteúdo gástrico e considerar a passagem precoce de sonda gástrica para\ndescompressão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-196700","number":"196700","sourceNumber":"196700","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 22 anos de idade, G1P0A0, comparece a consulta de pré-natal do terceiro\ntrimestre de gestação. Havia referido, na última consulta, pirose moderada e regurgitação, sendo\norientada a realizar mudanças dietéticas e de estilo de vida. Hoje relata que teve alívio apenas\nparcial. Acerca do caso clínico apresentado e considerando-se os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Metoclopramida é últil no alívio dos sintomas dessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-196615","number":"196615","sourceNumber":"196615","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher de 35 anos de idade, com diagnóstico de lúpus eritematoso sistêmico, recebe o\ndiagnóstico de gravidez. O médico que a atende resolve suspender a hidroxicloroquina e inicia\nprednisona. Com relação a esse caso clínico, julgue o item a seguir. O uso de hidroxicloroquina não\nestá contraindicado, uma vez que não há evidência de sua teratogenicidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-179191","number":"179191","sourceNumber":"179191","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a alternativa que apresenta os parâmetros de exames complementares\nlaboratoriais para síndrome de HELLP completa.","options":{"A":"plaquetas/mL < 100.000, TGO \"maior ou igual\" 70 e DHL \"maior ou igual\" 600 UI/L","B":"plaquetas/mL < 150.000, TGO \"maior ou igual\" 50 e DHL \"maior ou igual\" 400 UI/L","C":"plaquetas/mL < 200.000, TPO \"maior ou igual\" 40 e bilirrubina \"maior ou igual\" 2 mg/dL","D":"plaquetas/mL > 300.000, TGP \"maior ou igual\" 60 e bilirrubina \"maior ou igual\" 2 mg/dL","E":"plaquetas/mL nornais, TGP \"maior ou igual\" 50 e presença de esquizócitos"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-179196","number":"179196","sourceNumber":"179196","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Assinale a alternativa que apresenta a terapêutica antimicrobiana menos indicada para\no tratamento de infecção urinária na gravidez.","options":{"A":"nitrofurantoína","B":"ampicilina","C":"amoxacilina","D":"cefalexina","E":"silfametoxazol + trimetropim"},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-177625","number":"177625","sourceNumber":"177625","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 34 semanas de gestação chega a uma emergência obstétrica, referindo\ncefaleia e mal-estar. Relata pré-natal sem intercorrências e não faz uso de medicações no\nmomento. Ao exame, evidenciam-se PA = 150 mmHg x 90 mmHg, altura uterina de 30 cm,\nbatimentos cardiofetais de 140 bpm, movimentação fetal presente, ausência de dinâmica uterina e\npresença de edema em membros inferiores e face. Considerando esse caso clínico os\nconhecimentos médicos a ela relacionados, julgue o item a seguir. A conduta adequada é deixar a\npaciente em observação para ver se a pressão melhora com o repouso. Havendo melhora dos\nníveis tensionais, a paciente poderá ser liberada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-177634","number":"177634","sourceNumber":"177634","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 34 semanas de gestação chega a uma emergência obstétrica, referindo\ncefaleia e mal-estar. Relata pré-natal sem intercorrências e não faz uso de medicações no\nmomento. Ao exame, evidenciam-se PA = 150 mmHg x 90 mmHg, altura uterina de 30 cm,\nbatimentos cardiofetais de 140 bpm, movimentação fetal presente, ausência de dinâmica uterina e\npresença de edema em membros inferiores e face. Considerando esse caso clínico os\nconhecimentos médicos a ela relacionados, julgue o item a seguir. Deve-se avaliar a vitalidade\nfetal e rastrear pré-eclâmpsia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-177712","number":"177712","sourceNumber":"177712","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 6 semanas de gestação realiza consulta para iniciar o pré-natal. Refere\nter lúpus eritematoso sistêmico (LES) e que\nestá em uso de hidroxicloroquina e com a doença\ninativa há 1 ano. Considerando essa situação e os conhecimentos médicos a ela relacionados,\njulgue o item a seguir. Existe maior risco de reativação do lúpus durante a gestação e o período\npós-parto, o que requer um pré-natal regular e a interação entre obstetra e reumatologista.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-177721","number":"177721","sourceNumber":"177721","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 6 semanas de gestação realiza consulta para iniciar o pré-natal. Refere\nter lúpus eritematoso sistêmico (LES) e que\nestá em uso de hidroxicloroquina e com a doença\ninativa há 1 ano. Considerando essa situação e os conhecimentos médicos a ela relacionados,\njulgue o item a seguir. Anemia e trombocitopenia leve são alterações fisiológicas da gravidez, que,\npor sua vez, podem ser confundidas com a atividade da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-177723","number":"177723","sourceNumber":"177723","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta com 6 semanas de gestação realiza consulta para iniciar o pré-natal. Refere\nter lúpus eritematoso sistêmico (LES) e que\nestá em uso de hidroxicloroquina e com a doença\ninativa há 1 ano. Considerando essa situação e os conhecimentos médicos a ela relacionados,\njulgue o item a seguir. A gestação em pacientes com LES está associada a um maior número de\ncomplicações, como nascimento em pré-termo, pré-eclâmpsia, restrição de crescimento fetal e\ntrombose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-131825","number":"131825","sourceNumber":"131825","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Nos casos de pré-eclâmpsia, é importante identificar a gravidade deles, pois os\nprognósticos materno e fetal dependem da conduta. A esse respeito, não representa critério que\nidentifica um caso de pré-eclâmpsia como grave a (o)","options":{"A":"Pressão arterial = 160 x 110 mmHg.","B":"Proteinúria = 1 g/24 horas.","C":"Aumento de enzimas hepáticas (AST, ALT).","D":"Plaquetopenia ( < 100.000/mm³).","E":"Anemia hemolítica microangiopática."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-134983","number":"134983","sourceNumber":"134983","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Julgue o seguinte item referente a distúrbios gastrintestinais e metabólicos na gestação.\nO cretinismo congênito é uma complicação\nrelacionada ao hipotireoidismo devido à deficiência em\niodo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108219","number":"108219","sourceNumber":"108219","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Acerca das complicações da gestação, julgue o item subsequente. Gestantes com\nhistórico de doença cardíaca valvar e defeitos septais ventriculares devem receber a profilaxia de\nendocardite bacteriana no momento da realização do parto.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108215","number":"108215","sourceNumber":"108215","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Acerca das complicações da gestação, julgue o item subsequente. Nos casos de\ngestantes epilépticas que usam simultaneamente\nfenitoína e ácido fólico, recomenda-se a redução\nda dosagem de folato devido ao fato de o ácido fólico aumentar os níveis plasmáticos do\nanticonvulsivante.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108202","number":"108202","sourceNumber":"108202","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Acerca das complicações da gestação, julgue o item subsequente. Pré-eclâmpsia\nsobreposta caracteriza-se pela ocorrência de\nhipertensão, não acompanhada de proteinúria, após a\nvigésima semana de gestação.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108185","number":"108185","sourceNumber":"108185","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação às doenças intercorrentes ou próprias da gestação, julgue o item a seguir.\nA hiperêmese gravídica habitualmente se associa ao\ndesequilíbrio hidroeletrolítico caracterizado\npela acidose metabólica hiperclorêmica e pela cetonúria persistente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108182","number":"108182","sourceNumber":"108182","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação às doenças intercorrentes ou próprias da gestação, julgue o item a seguir.\nDevido à elevação da secreção ácida produzida no período gestacional, a doença ulceropéptica\napresenta uma maior incidência durante a gravidez, devendo, nesse período, ser tratada com\nomeprazol.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108180","number":"108180","sourceNumber":"108180","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação às doenças intercorrentes ou próprias da gestação, julgue o item a seguir.\nEm casos de pacientes portadoras de púrpura\ntrombocitopênica idiopática (PTI), a amamentação é\na melhor medida preventiva contra a trombocitopenia neonatal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-108177","number":"108177","sourceNumber":"108177","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação às doenças intercorrentes ou próprias da gestação, julgue o item a seguir.\nNa gestação, o lúpus eritematoso sistêmico\ndescompensado pode ocasionar a síndrome do lúpus\nneonatal, caracterizado pela presença de bloqueio atrioventricular congênito irreversível ou de\neritema cutâneo transitório.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-88645","number":"88645","sourceNumber":"88645","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Acerca das intercorrências obstétricas, julgue o item subsequente. A síndrome HELLP é\numa complicação da doença hipertensiva específica da gestação, caracterizada por hemólise,\naumento dos valores das enzimas hepáticas e diminuição da contagem das plaquetas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-64695","number":"64695","sourceNumber":"64695","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente com 18 anos e idade gestacional de 28 semanas apresenta diagnóstico\nde pré-eclâmpsia grave com sinais de iminência de\neclampsia, sendo medicada com sulfato de\nmagnésio endovenoso. Com base nestas informações, assinale a alternativa que apresenta,\nrespectivamente, a dose de ataque, a manutenção do sulfato de magnésio e os sinais avaliados\nquando for usado o sulfato de magnésio e suas referências de normalidade.","options":{"A":"Ataque 4 g, manutenção 2 g por 24h, reflexo patelar presente e normal, frequência respiratória\nde 20 irpm e diurese em 4h acima de 100 ml.","B":"Ataque 2 g, manutenção de 2 g de 12/12h, reflexo patelar normal, frequência respiratória de\n30/40 irpm e diurese de 100 ml em 24h.","C":"Ataque 4 g, manutenção de 5 g 4/4h por 24h, reflexo patelar ausente, frequência respiratória de\n10 irpm e diurese de 50 ml em 24h.","D":"Ataque 10 g em 24h, manutenção de 4 g em 24h, reflexo patelar normal, frequência respiratória\nde 20 irpm e diurese de 25 ml/h.","E":"Ataque 4 g associado com nitroprussiato de sódio, manutenção de 1 g de 4/4h, reflexo patelar\nexacerbado, frequência respiratória normal e diurese de 50 ml em 24h."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-64718","number":"64718","sourceNumber":"64718","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente com 20 anos, gestante de 35 semanas, primigesta, deu entrada no\npronto-socorro de obstetrícia com PA de\n160 x 120 mmHg, em uso de metildopa de 2 g/dia e\nnifedipina de 20 mg/dia desde a vigésima terceira semana de gestação. No cartão de pré-natal\nmantinha níveis pouco elevados da PA, proteinúria de 24h positiva e aumento de peso de 21 kg. A\npaciente se queixava de cefaleia e escotomas. No exame físico constava movimento fetal presente,\ntônus uterino normal, dinâmica uterina ausente, altura uterina de 31 cm, batimento cardíaco fetal de\n134 bpm, toque: colo grosso, posterior, entreaberto. Após a realização do exame físico, a paciente\napresentou crise convulsiva. Com base nas informações acima, assinale a alternativa que\napresenta corretamente os primeiros procedimentos a serem tomados.","options":{"A":"Aplicar sulfato de magnésio, realizar catéter de oxigênio, providenciar um leito adequado para\nevitar queda, realizar sondagem vesical, providenciar proteção bucal, coletar exames, manter a\npaciente em decúbito lateral esquerdo e aplicar hidralazina endovenosa.","B":"Aplicar diazepan intramuscular, realizar intubação orotraqueal, manter a paciente em decúbito\nlateral esquerdo, ministrar nifedipina, aplicar\ndiurético endovenoso e realizar hidratação vigorosa.","C":"Aplicar sulfato de magnésio, realizar intubação orotraqueal, ministrar diurético, ministrar\ndigital,\nrealizar dosagem de ácido lático, utilizar corticoide para maturação pulmonar e aplicar hidralazina\nendovenosa.","D":"Ministrar hidantal e diazepan, realizar intubação orotraqueal, manter a paciente em decúbito\nlateral esquerdo, ministrar digital, realizar\nhidratação endovenosa e ministrar corticoide.","E":"Aplicar sulfato de magnésio e hidantal, ministrar diurético, realizar sondagem vesical e\nministrar\ncorticoide."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-64289","number":"64289","sourceNumber":"64289","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação às intercorrências obstétricas relativas à gestação, julgue o item\nsubsequente. A síndrome de transfusão\ngêmeo-gemelar (STGG) ocorre devido a uma anastomose\nvascular placentária entre os fetos e associa-se, quando não tratada, à elevada taxa de\nmortalidade.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-64297","number":"64297","sourceNumber":"64297","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação às intercorrências obstétricas relativas à gestação, julgue o item\nsubsequente. As malformações fetais, com\ndestaque para a atresia do esôfago e malformações do\naparelho urinário, podem ocasionar polidramnia e oligoidramnia. A deglutição fetal é o principal\nmodo de absorção do líquido amniótico e a urina fetal representa a principal fonte de síntese desse\nlíquido.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-13857","number":"13857","sourceNumber":"13857","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Distúrbios endócrinos e hipertensão são fatores de alto risco gestacional. Acerca\ndessas condições clínicas, assinale a opção\ncorreta.","options":{"A":"Pacientes diabéticas descompensadas tendem a apresentar fetos com crescimento intrauterino\nretardado e oligoidrâmnio secundário à\npresença de doença microvascular.","B":"A escolha do agente tocolítico em pacientes com diabetes melito em trabalho de parto prematuro\né limitada. O sulfato de magnésio é uma boa\nindicação, enquanto os simpaticomiméticos devem ser\nusados com cautela, porque podem exacerbar a hiperglicemia e causar cetoacidose.","C":"A necessidade de insulina no diabetes do tipo 1 diminui de 2 a 3 vezes durante a gravidez.","D":"As alterações fisiológicas da gravidez tendem a amenizar os riscos de sobrecarga cardíaca já\nexistente em pacientes hipertensas crônicas.","E":"O tratamento de escolha na gestante hipertensa crônica grave são os medicamentos inibidores\ndas enzimas conversoras da angiotensina."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-352354","number":"352354","sourceNumber":"352354","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 36 semanas de gestação, primigesta, (G1PO), fazendo uso de\npindolol, medicamento que foi alterado no início\nda primeira consulta de pré-natal. Algumas\nsemanas atrás, apresentou proteinúria de 24 horas com quantificação de 500 mg. Durante o\nacompanhamento obstétrico, não houve intercorrências, e os níveis de pressão arterial estavam\ndentro dos limites aceitáveis até o momento. A paciente buscou o pronto-socorro com queixa de\ncefaleia e escotomas que persistiam há 30 minutos. Ao exame físico, a paciente estava lúcida e\norientada no espaço e no tempo, com pressão arterial de 180 x 112. O útero apresentava uma\naltura de fundo uterino de 32 cm, com tônus habitual, e os batimentos cardíacos fetais estavam em\n144 bpm. O colo do útero estava pérvio, a apresentação fetal era cefálica, e a bolsa amniótica\nestava íntegra, Poucos minutos após a admissão, a paciente teve uma crise tônico-clônica\ngeneralizada e foi encaminhada à sala de emergência para receber tratamento imediato. Os\nresultados do hemograma não apresentaram alterações dignas de nota, e o número de plaquetas\nestava em 200.000/mm³. Com relação a doença hipertensiva específica da gestação, definições,\ncondutas médicas e conhecimentos relacionados, julgue o item abaixo. Pacientes com quadros\nsemelhantes devem ser encaminhadas imediatamente para a sala de emergência após a triagem\nrealizada por profissionais de enfermagem ou médicos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-334895","number":"334895","sourceNumber":"334895","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O diagnóstico de diabetes gestacional vem sofrendo alterações ao longo dos anos,\nporém é um tema bastante importante no que diz respeito à assistência materno-fetal. Acerca\ndesse assunto, assinale a alternativa CORRETA.","options":{"A":"O diagnóstico de diabetes prévio à gravidez, ou overt diabetes, ocorre quando se obtém uma\nhemoglobina glicada acima de 5,7% e (ou) uma glicemia de jejum entre 100 e 126.","B":"O tratamento inicial, comumente relacionado à diabetes gestacional, inclui o uso de\nhipoglicemiantes orais como a metformina, com\nestudos que descartam o risco de malformações\nfetais.","C":"As complicações relacionadas à diabetes incluem prematuridade, oligoâmnio, macrossomia fetal\ne morte súbita fetal, independentemente do\ncontrole glicêmico adequado.","D":"O diagnóstico de diabetes gestacional pode ser feito por meio do teste de tolerância à glicose\npós 75 g de dextrosol com valores de: jejum,\nacima de 92; 1 hora após, acima de 180; e 2 horas\napós, acima de 153.","E":"A associação entre a diabetes e a dislipidemia e (ou) a obesidade deve ser considerada e,\nmuitas vezes, o uso de medicações hipolipemiantes pode se relacionar a uma diminuição dos\nriscos cardiovasculares."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-334896","number":"334896","sourceNumber":"334896","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As doenças hipertensivas da gestação ainda representam uma importante causa de\nóbito materno no Brasil. No que se refere ao\ndiagnóstico e ao manejo dessas condições, assinale a\nalternativa correta.","options":{"A":"O diagnóstico de pré-eclâmpsia sempre exige a comprovação de proteinúria > 300 mg / 24\nhoras.","B":"O uso do sulfato de magnésio, no contexto do manejo da pré-eclâmpsia com sinais de\ngravidade, tem como objetivo a neuroproteção fetal.","C":"A observação de níveis pressóricos superiores a 140 mmHg x 90 mmHg antes das 20 semanas\nde idade gestacional, sem proteinúria\nassociada, permite o diagnóstico de hipertensão gestacional.","D":"Nos casos de hipertensão arterial sistêmica prévia à gestação, a recomendação atual é que seja\nmantido o anti-hipertensivo de uso habitual da paciente, apenas com ajuste de posologia,\nindependentemente da classe a que pertencer o medicamento.","E":"O manejo dos distúrbios hipertensivos da gestação inclui a solicitação de rotina laboratorial,\napresentando como objetivo, entre outros, a\nidentificação de critérios laboratoriais de gravidade e\nsíndrome HELLP."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-343448","number":"343448","sourceNumber":"343448","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Acerca da Infecção do Trato Urinário (ITU), é CORRETO afirmar:","options":{"A":"A infecção urinária pode ser sintomática ou assintomática, recebendo na ausência de sintomas a\ndenominação de bacteriúria assintomática.","B":"A infecção por Chlamydia Trachomatis deve ser considerada principalmente nas mulheres\nassintomáticas, com uroculturas positivas.","C":"A ITU baixa (cistite) apresenta-se habitualmente com disúria, urgência miccional, polaciúria,\nnictúria e diminuição da frequência\nurinária. A febre nas infecções baixas é um sintoma usual.","D":"Denomina-se ITU complicada quando ocorre em mulheres não grávidas e na ausência de\nanomalias estruturais ou funcionais do trato urinário."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-343452","number":"343452","sourceNumber":"343452","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O diagnóstico de Diabetes Mellitus gestacional é feito por:","options":{"A":"Glicemia de jejum entre 92 e 125 mg/dL abaixo de 20 semanas de gestação.","B":"Glicemia de jejum maior que 126 mg/dL no último trimestre de gestação.","C":"Glicemia de jejum a partir de 90 mg/dL em qualquer momento da gestação.","D":"Glicemia de jejum a partir de 101 mg/dL em qualquer momento da gestação."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-343463","number":"343463","sourceNumber":"343463","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente, 33 anos, nuligesta e na 25o semana de gravidez. Chega ao pronto-socorro\nobstétrico do hospital de sua cidade relatando\ncefaleia de moderada intensidade. Nega\nhipertensão, diabetes e outras comorbidades. Ao exame obstétrico: dinâmica uterina, ausente; feto\nem apresentação córmica; batimentos fetais de 140 bpm; altura de fundo uterino de 22,5 cm; e\npressão arterial 140 x 90 mmHg (confirmada por duas vezes e após repouso em decúbito lateral\nesquerdo). Exame de urina com proteinúria 2+/4+. Considerando as informações, a conduta inicial\nCORRETA é:","options":{"A":"Orientar dieta com restrição de sal, programar retorno com intervalos frequentes, encaminhar\npara o pré-natal de alto risco e solicitar\nexames laboratoriais complementares.","B":"Orientar dieta com restrição de sal, prescrever anti-hipertensivo (metildopa 750 mg/dia),\nprogramar retorno com intervalos frequentes,\nencaminhar para o pré-natal de alto risco e solicitar\nexames laboratoriais complementares.","C":"Programar retorno com intervalos frequentes, continuar o acompanhamento pré-natal na UBS e\nsolicitar exames laboratoriais complementares.","D":"Programar retorno com intervalos frequentes, encaminhar ao pré-natal de alto risco e solicitar\nexames laboratoriais complementares."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-307123","number":"307123","sourceNumber":"307123","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 17 anos de idade, primigesta, obesa, em seguimento de pré-natal de\nbaixo risco, atualmente com 32 semanas, dá entrada no pronto-socorro da maternidade com queixa\nde cefaleia frontal, associada à pirose e à sensação de mal-estar. Ao exame físico, apresenta PA =\n150 x 100 mmHg, FC = 80 bpm, FR = 16 irpm, SatO2 = 96% em ar ambiente, com boa\nmovimentação fetal e sem perdas transvaginais. Com base nesse caso clínico, assinale a\nalternativa CORRETA. Alternativas:","options":{"A":"Esta paciente necessita de controle pressórico adequado imediato, em pronto-socorro, com\nmetildopa pelo risco de crises convulsivas.","B":"Os fatores de risco para pré-eclâmpsia da paciente incluem idade, paridade e obesidade.","C":"O uso do nitroprussiato deve ser imediato em razão do risco de infarto e de acidente vascular\nencefálico na paciente gestante com pressão alterada.","D":"O sulfato de magnésio deve ser utilizado somente nas crises pressóricas superiores a PA = 160\nmmHg x 110 mmHg pelo risco de intoxicação.","E":"Não se pode afirmar que a paciente possui pré-eclâmpsia, pois não se dispõe de proteinúria de\n24h superior a 300 mg."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-307125","number":"307125","sourceNumber":"307125","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 26 semanas, 18 anos de idade, primigesta, pré-natal de baixo risco\naté a presente data, com exames do\nprimeiro trimestre normais, realizou exames laboratoriais de\npré-natal com teste oral de tolerância à glicose após 75 g dextrosol, com os seguintes resultados\nglicemia de jejum = 80 mg/dL, glicemia após 1 h = 187 mg/dL e após duas horas = 157 mg/dL. Com\nbase nesse caso clínico, assinale a alternativa correta. Alternativas:","options":{"A":"O diagnóstico de diabetes gestacional inclui alteração nas três medidas do teste oral de\ntolerância à glicose ou à glicemia de jejum alterada.","B":"O teste foi indicado de forma equivocada, pois a paciente não apresentou alteração dos exames\nde glicemia no primeiro trimestre.","C":"O teste deve ser realizado após as 24 semanas pelo início da produção de hormônios lactogênio\nplacentário e hormônio liberador de corticotrofina.","D":"O diagnóstico dessa paciente foi determinado somente pela glicemia de 2 h superior a 155\nmg/dL.","E":"O pré-natal da paciente pode continuar a ser realizado no pré- natal de risco habitual, uma vez\nque não há alteração no exame (glicemias\ninferiores a 200 mg/dL)."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-291459","number":"291459","sourceNumber":"291459","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta, de 25 anos de idade, com 34 semanas de gestação. Vinha em uso de\nmetildopa 1 g/dia e deu entrada na\nmaternidade, com quadro de iminência de eclámpsia e níveis de\npressóricos de 170 x 120 mmHg. Foi iniciado tratamento com sulfato de magnésio (dose de ataque\nde 6 g) e está em uso de infusão intravenosa contínua na dose de 1g/hora. Cerca de 4 horas após\ninicio da medicação, a paciente referiu mal-estar e tonturas. Ao exame físico: regular estado geral,\nsonolenta, Pa=140 x 90 mmHg, frequência respiratória - 14 irpm, frequência cardiaca = 90bpm,\nreflexo patelar ausente. Nas ultimas 4 horas apresentou diurese total de 70 mL. Nesse caso, é\nindicado","options":{"A":"aumentar dose de infusão do sulfato de magnésio para 2g/hora.","B":"administrar gluconato de cálcio, 1 g, via intravenosa, lentamente.","C":"aumentar infusão de cristaloides e associar furosemida, por via intravenosa.","D":"administrar hidralazina, 5 mg, por via intravenosa."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-263352","number":"263352","sourceNumber":"263352","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 20 anos de idade, com 10 semanas de gestação, retorna para\nconsulta de pré-natal com exames de rotina.\nA urocultura apresentou crescimento bacteriano maior\nque 10? UFC/mL (unidades formadoras de colônias por mL). A paciente relatou aumento da\nfrequência urinária, entretanto negou sintomas como disúria, urgência miccional, noctúria, dor\nsuprapúbica ou febre. Nesse caso, o diagnóstico e o tratamento antimicrobiano são,\nrespectivamente,","options":{"A":"bacteriúria assintomática; nitrofurantoína.","B":"bacteriúria assintomática; ciprofloxacina.","C":"cistite aguda; nitrofurantoína.","D":"cistite aguda; ciprofloxacina."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-273329","number":"273329","sourceNumber":"273329","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"O hormônio placentário que aumenta a resistência insulínica e é fator para\ndesenvolvimento do diabetes gestacional é o(a):","options":{"A":"Gonadotrofina coriônica (hCG).","B":"Estradiol.","C":"Lactogênio placentário (HPL).","D":"Progesterona."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-268914","number":"268914","sourceNumber":"268914","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 32 anos de idade, G1P0, com diabetes mellitus (DM) tipo 1, em uso\nde insulina, iniciou acompanhamento pré-natal\nde alto risco com 10 semanas de idade gestacional,\ncalculada a partir da data da última menstruação (DUM) e confirmada por ecografia realizada com\noito semanas e dois dias. Durante a primeira consulta de pré-natal, apresentou primeira medida de\nPA = 150 mmHg x 85 mmHg. Após o período adequado de repouso, ao final da consulta, a medida\nfoi confirmada, com valores de PA = 140 mmHg x 92 mmHg. A paciente recebeu diagnóstico de\nhipertensão arterial sistêmica e foi iniciada metildopa 250 mg, de oito em oito horas, para controle\npressórico, bem como tomadas as condutas pertinentes ao período gestacional e às demais\ncomorbidades apresentadas. Com 30 semanas de idade gestacional, a paciente passou a\napresentar descontrole da pressão arterial, a despeito do ajuste das medicações anti-hipertensivas.\nFoi realizada proteinúria de 24 horas, com resultado 450 mg/24 horas. Tendo em vista esse caso\nclínico e os conhecimentos médicos correlatos, assinale a alternativa correta.","options":{"A":"A paciente apresenta diagnóstico provável de pré-eclâmpsia sobreposta à hipertensão crônica e,\npara melhor caracterização do diagnóstico, deveria ter sido solicitada proteinúria de Bence Jones\nquando do diagnóstico da hipertensão arterial sistêmica em razão do antecedente de DM tipo 1.","B":"A administração diária de AAS em alta dosagem (275 mg a 500 mg), iniciada antes das 16\nsemanas de idade gestacional, poderia ser\nindicada para essa paciente como medida de redução\nde risco para pré-eclâmpsia.","C":"Fazem parte dos exames laboratoriais para avaliação mais abrangente de gravidade e\ndiagnóstico precoce de síndrome HELLP na paciente mencionada: hemograma completo, ácido\núrico, TGO, TGP, creatinina, bilirrubina total e frações e DHL.","D":"O descolamento prematuro de placenta é complicação possível quando da persistência de\ncontrole pressórico adequado, consistindo em urgência obstétrica com baixas taxas de\nmorbimortalidade maternofetal.","E":"A prescrição mais adequada para a paciente em questão seria o inibidor da enzima conversora\nde angiotensina (IECA), pois, além de ser mais\neficaz do que a metildopa para o controle\n\npressórico, também é capaz de promover nefroproteção nas pacientes portadoras de DM."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-291503","number":"291503","sourceNumber":"291503","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Primigesta de 18 anos de idade, com 37 semanas de idade gestacional, chega ao\npronto atendimento com queixa de cefaleia\nintensa. Refere também visualização de pontos pretos.\nNega outras queixas. Pré-natal até o momento sem intercorrências. Ao exame encontra-se lúcida e\norientada, com muita dor. A pressão arterial é de 160/100 mmHg, mantida após repouso em\ndecúbito lateral esquerdo, a frequência cardíaca é de 90 batimentos por minuto. Sem dinâmica\nuterina, feto com movimentação normal. Batimentos cardíacos fetais = 144 bpm com variabilidade.\nEdema em membros inferiores de 3 cruzes em 4. Traz um exame de urina, coletado há 2 dias que\nmostra proteinúria 2 cruzes em 4, sem outras alterações significativas. Foi prescrita hidralazina\nendovenosa para controle de pressão arterial (PA). Que outra conduta seria necessária no\nmomento e para quê?","options":{"A":"Prescrever sulfato de magnésio para prevenir convulsões.","B":"Prescrever sulfato de magnésio para controle de pressão arterial e dos sintomas maternos.","C":"Prescrever analgésicos e benzodiazepínicos para controle dos sintomas e prevenção de\nconvulsões.","D":"Prescrever analgésicos e aguardar efeito do anti-hipertensivo."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-263383","number":"263383","sourceNumber":"263383","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante, no curso da 12.ª semana de gestação, vai ao ambulatório de obstetrícia\nreferenciado de sua Unidade Básica de Saúde com o seguinte encaminhamento: \"Encaminho\nprimigesta com 23 anos de idade por ter apresentado, em seus exames de rotina do pré-natal, uma\nglicemia de jejum de 140 mg/dL\". No momento, a paciente encontrava-se assintomática e já trazia\num segundo resultado de glicemia de jejum que demonstrava um valor de 148 mg/dL. O obstetra\ndo ambulatório, segundo as recomendações mais atualizadas da OMS e da Sociedade Brasileira\nde Diabetes, deve","options":{"A":"solicitar teste de sobrecarga oral com 75 gramas de glicose anidra ainda com 12 semanas de\ngestação.","B":"solicitar teste de sobrecarga oral com 75 gramas de glicose anidra entre 24 e 28 semanas de\ngestação.","C":"diagnosticar a paciente com diabete melito prévio à gestação e iniciar tratamento adequado.","D":"diagnosticar a paciente com diabete melito gestacional e iniciar tratamento adequado."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-274659","number":"274659","sourceNumber":"274659","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente gestante, 24 anos, G2P1, apresenta nível de hemoglobina normal na primeira\nvisita pré-natal, e 4 semanas após, com 28\nsemanas completas de gestação, o nível de\nhemoglobina é de 7,0 g/dL. Relata, ainda, fadiga há uma semana e que a urina adquiriu aparência\nescura após fazer uso de nitrofurantoína para infecção do trato urinário. Diagnóstico provável de:","options":{"A":"Talassemia.","B":"Hemólise.","C":"Deficiência de folato.","D":"Anemia por deficiência de ferro."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-274660","number":"274660","sourceNumber":"274660","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As doenças da tireoide são comuns nas mulheres em idade de reprodução. Os níveis\ndo hormônio da tireoide costumam ser alterados\nna gravidez. Um procedimento que pode ser\nrealizado, a fim de amenizar eventuais problemas decorrentes das doenças da tireoide, é:","options":{"A":"O uso do Iodo-131, indicado durante três vezes ao dia.","B":"O uso da Metimazol, que pode ser usado em dose, é de 15 a 150 mg diárias.","C":"O PTU, que produz a conversão periférica de T3 e T4.","D":"A tireoidectomia, que pode ser feita após o 3o mês da gravidez."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-263430","number":"263430","sourceNumber":"263430","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma secundigesta com 23 anos de idade comparece à consulta ambulatorial de\n\npré-natal de alto risco, encaminhada pela Unidade Básica de Saúde. Afirma estar receosa com a\ngestação atual e refere ter tido, na gravidez anterior, elevação da pressão arterial e convulsão\nantes do parto, que ocorreu com 37 semanas. No momento, encontra-se com 14 semanas de\ngestação e sem queixas, não havendo outros antecedentes patológicos. Ao exame físico,\nmostra-se dentro da normalidade, com PA = 115 x 82 mmHg. Avaliando-se essa história clínica,\n\nqual medicamento faz parte da prevenção da condição que a paciente apresentou em sua primeira\ngestação?","options":{"A":"Metildopa.","B":"Ácido fólico.","C":"Progesterona.","D":"Ácido acetilsalicílico."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-244494","number":"244494","sourceNumber":"244494","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 19 anos de idade, G1P0, IG 36 semanas, pré-natal sem intercorrências,\ncompareceu a consulta habitual. Ao aferir\nsinais vitais durante triagem, apresentou PA = 164 mmHg\nx 112 mmHg. Após cinco minutos, foi aferida novamente com PA = 160 mmHg x 80 mmHg. Então,\na unidade básica de saúde encaminhou a paciente imediatamente para o hospital. Ao chegar, ela\nqueixou-se de cefaleia occipital, escotomas e epigastralgia e, após avaliação inicial, manteve PA =\n170 mmHg x 100 mmHg, e foram solicitados exames que evidenciaram proteinúria 3+/4+, creatinina\n\n= 1,3 mg/dL e os demais exames dentro dos padrões da normalidade. A respeito desse caso\nclínico, em relação ao diagnóstico, assinale\na alternativa correta. A respeito desse caso clínico, em\nrelação ao diagnóstico assinale a alternativa correta.","options":{"A":"Hipertensão gestacional.","B":"Pré-eclâmpsia sem sinais de gravidade.","C":"Síndrome HELLP.","D":"Pré-eclâmpsia com sinais de gravidade.","E":"Pré-eclâmpsia sobreposta."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-244495","number":"244495","sourceNumber":"244495","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 19 anos de idade, G1P0, IG 36 semanas, pré-natal sem intercorrências,\ncompareceu a consulta habitual. Ao aferir\nsinais vitais durante triagem, apresentou PA = 164 mmHg\nx 112 mmHg. Após cinco minutos, foi aferida novamente com PA = 160 mmHg x 80 mmHg. Então,\na unidade básica de saúde encaminhou a paciente imediatamente para o hospital. Ao chegar, ela\nqueixou-se de cefaleia occipital, escotomas e epigastralgia e, após avaliação inicial, manteve PA =\n170 mmHg x 100 mmHg, e foram solicitados exames que evidenciaram proteinúria 3+/4+, creatinina\n\n= 1,3 mg/dL e os demais exames dentro dos padrões da normalidade. A respeito desse caso\nclínico, em relação ao diagnóstico, assinale a alternativa correta. Assinale a alternativa que\ncorresponde à propedêutica obstétrica mais adequada para o caso.","options":{"A":"Ministrar anti-hipertensivo; se PA diminuir para PAS < 140 mmHg e PAD < 90 mmHg, a paciente\npode ser liberada para retorno em consulta\npré-natal.","B":"Ministrar anti-hipertensivo, sulfato de magnésio e resolução da gestação após estabilização da\npaciente, preferencialmente por indução do trabalho de parto.","C":"Ministrar anti-hipertensivo e programar resolução da gestação com 40 semanas.","D":"Ministrar anti-hipertensivo e programar resolução da gestação por cesariana com 37 semanas.","E":"Ministrar sulfato de magnésio e, em caso de diminuição da PA e remissão dos sintomas,\nprogramar resolução da gestação para 37 semanas por cesariana."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-244496","number":"244496","sourceNumber":"244496","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Acerca do diabetes gestacional, assinale a alternativa que não representa uma\ncomplicação gestacional ou perinatal esperada em\nfetos e recém-nascidos de mães portadoras de\ndiabetes gestacional.","options":{"A":"Polidrâmnio","B":"Crescimento fetal excessivo","C":"Tocotraumatismo","D":"Síndrome da angústia respiratória do recém-nascido","E":"Hiperglicemia neonatal"},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-227427","number":"227427","sourceNumber":"227427","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A respeito de doenças infecciosas durante a gravidez, julgue o item que se segue.\nEstudos recentes mostram que o risco de\ndesenvolvimento de pielonefrite em gestantes com\nbacteriúria assintomática é igual ao da população geral, portanto a antibioticoterapia só deve ser\nrealizada em gestantes com infecção urinária sintomática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-227430","number":"227430","sourceNumber":"227430","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A respeito de doenças infecciosas durante a gravidez, julgue o item que se segue. A\ndengue durante a gravidez pode cursar com\ncomplicações clínicas maternas, porém não aumenta a\ntaxa de complicações obstétricas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-230614","number":"230614","sourceNumber":"230614","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A profilaxia para infecções urinárias de repetição pode ser realizada com qualquer dos\nantibióticos, EXCETO:","options":{"A":"Nitrofurantoina.","B":"Cefalexina.","C":"fosfomicina-trometamol.","D":"Meropenem."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-203042","number":"203042","sourceNumber":"203042","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 25 anos de idade, G3P2C1A0, gestante de 38 semanas, comparece\nao pronto-socorro de obstetrícia em razão de quadro\nconvulsivo em casa. Não realizou pré-natal.\nRefere cefaleia e escotomas visuais e nega epigastralgia. Ao exame físico, apresenta pressão\narterial = 186 mmHg x 112 mmHg, tônus uterino normal, BCF = 142 bpm e colo longo e fechado.\nOs exames laboratoriais evidenciam as seguintes alterações: 90.000 plaquetas, TGO = 86, TGP =\n84, DHL = 850 e proteinúria +++. Quanto a esse caso clínico, assinale a alternativa correta.","options":{"A":"É imprescindível solicitar eletroencefalograma para descartar epilepsia como causa de\nconvulsão.","B":"Deve-se prescrever diazepam intramuscular para controle do quadro convulsivo e proceder à\ncesariana imediatamente.","C":"Deve-se iniciar a sulfatação e estabilizar a pressão arterial sistêmica, e então proceder à\nrealização de cesariana.","D":"Deve-se realizar Doppler fetal para definir se há tempo disponível para maturação pulmonar de\nfeto com corticoide.","E":"Caso a paciente tenha estabilizado o quadro e a avaliação fetal tenha demonstrado boa\nvitalidade, deve ser iniciada indução do parto\nmisoprostol para evitar parto cirúrgico, tendo em vista\na presença de plaquetopenia."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-203062","number":"203062","sourceNumber":"203062","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 25 anos de idade, G3P2C1A0, gestante de 38 semanas, comparece\nao pronto-socorro de obstetrícia em razão de quadro\nconvulsivo em casa. Não realizou pré-natal.\nRefere cefaleia e escotomas visuais e nega epigastralgia. Ao exame físico, apresenta pressão\narterial = 186 mmHg x 112 mmHg, tônus uterino normal, BCF = 142 bpm e colo longo e fechado.\nOs exames laboratoriais evidenciam as seguintes alterações: 90.000 plaquetas, TGO = 86, TGP =\n84, DHL = 850 e proteinúria +++. Caso a paciente apresente hipertonia uterina e sangramento\nabundante, a principal hipótese diagnóstica e a conduta a ser seguida são as seguintes:","options":{"A":"Descolamento prematuro de placenta - ecografia obstétrica para confirmar o diagnóstico.","B":"placenta prévia - ecografia transvaginal para definir a distância da borda placentária ao\norifício\ninterno do colo.","C":"rotura de vasa prévia - cesárea imediata.","D":"Descolamento prematuro de placenta - cesárea imediata.","E":"Sangramento proveniente do colo em razão do início do trabalho de parto - observação clínica."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-206100","number":"206100","sourceNumber":"206100","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante assintomática comparece ao pré-natal com resultados de exames\nlaboratoriais de rotina, em que fica evidenciado\nna urocultura presença de bactérias em mais de\n\n100.000 colonias por ml. Nesse caso, aponte a assertiva CORRETA.","options":{"A":"Esse exame não confirma infecção urinária, portanto não é necessário o tratamento.","B":"A paciente tem bacteriúria assintomática e não necessita tratamento.","C":"A bacteriúria assintomática necessita tratamento na gravidez pelo risco de complicações\nmaternas e fetais.","D":"A bacteriúria assintomática necessita tratamento somente fora do ciclo gravídico-puerperal pelos\nriscos da antibioticoterapia."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-206102","number":"206102","sourceNumber":"206102","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação à gravidez gemelar, assinale a alternativa CORRETA:","options":{"A":"Em gemelidade imperfeita, a placentação é dicoriônica/diamniótica.","B":"Os gêmeos dizigóticos são sempre dicoriônicos.","C":"As placentas dicoriônicas estão sempre bem divididas em duas massas placentárias.","D":"Os gêmeos monozigóticos podem ter sexos diferentes."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-177251","number":"177251","sourceNumber":"177251","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente de 33 anos de idade, G2P1C0A0, com gestação gemelar\n\ndicoriônica-dimniótica, foi levada por ambulância ao pronto-socorro, em razão de quadro de\ntrabalho de parto prematuro, que progrediu\na despeito da tentativa de inibição. Após o parto, foram\nrealizadas a dequitação placentária e a revisão do canal de parto. O caso evoluiu com sangramento\nvaginal importante cerca de 20 minutos depois. A principal hipótese diagnóstica é atonia uterina. A\nrespeito desse caso clínico, assinale a alternativa correta.","options":{"A":"Inicialmente, deve ser tentado o controle clínico do quadro, que pode ser feito com ocitocina\nendovenosa, ergometrina intramuscular e misoprostol via vaginal.","B":"Deve ser realizada histerectomia o mais rápido possível, como primeira conduta, pelo risco de\ncoagulação intravascular disseminada (CIVD) e parada cardiorrespiratória.","C":"Inicialmente, deve ser tentado o controle clínico do quadro, que pode ser feito com ocitocina\nendovenosa, ergometrina intramuscular e misoprostol via retal.","D":"A colocação de tampão vaginal duplo geralmente é efetiva para contenção do sangramento\nhemorrágico.","E":"A avaliação da cavidade uterina para investigar se há restos placentários deve ser realizada\napenas na vigência de sinais infecciosos."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-177260","number":"177260","sourceNumber":"177260","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente gestante de 32 anos de idade, com histórico de cesária há 3 anos por\napresentação pélvica, no momento está com 38\nsemanas de idade gestacional. A paciente estava\nsendo acompanhada em um pré-natal de alto risco, em razão de diabetes gestacional de difícil\ncontrole, que necessitou de uso de insulina. Ao exame físico, observa-se a medida da altura do\nfundo uterino de 42 cm, BCF 136 bpm, com dinâmica uterina efetiva, dilatação cervical total, bolsa\níntegra e polo cefálico no plano zero do De Lee. A respeito do mencionado caso, assinale a\nalternativa correta.","options":{"A":"Não há risco de prolapso de cordão quando ocorrer amniorrexe, tendo em vista que o feto é\nmacrossômico.","B":"Caso esse quadro evolua para distócia de ombro, esta pode ser resolvida com algumas\nmanobras, como compressão suprapública,\nposicionamento da parturiente em posição de quatro\napoios e compressão do abdome materno.","C":"Nesse caso, o ideal teria sido indicar cesariana com 34 semanas, pois diabetes gestacional em\nuso de insulina pode acarretar sofrimento\nfetal súbito e os riscos não superam os benefícios de se\nmanter a gestação até o termo.","D":"Caso esse quadro evolua para distócia de ombro, a fratura intencional de clavícula é umas das\nmanobras que pode ser utilizada, já que é preconizada para desimpactar os ombros fetais.","E":"É indicada cesárea de urgência nesse caso, por se tratar de paciente com cesárea prévia há\nmenos de 5 anos, o que aumenta o risco de\nruptura uterina."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-183935","number":"183935","sourceNumber":"183935","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, com vinte e seis anos de idade, G2P1, idade gestacional de vinte e duas\nsemanas, exibiu, em sua primeira consulta\npré-natal, havia quatro semanas, resultados\nlaboratoriais normais, inclusive nível de hemoglobina normal e nenhum antecedente patológico\ndigno de nota. No retorno para a segunda consulta, queixou-se de fadiga e astenia persistentes por\numa semana. Nessa ocasião, apresentou nível de hemoglobina de 7,0 g/dL. Relatou ter observado\nurina escura depois de ter feito uso de um antibiótico, prescrito em atendimento emergencial, para\ninfecção do trato urinário. Os resultados do exame físico foram: PA = 110 mmHg x 70 mmHg, FC =\n80 bpm, afebril, ictérica +/4+, ausculta cardíaca e pulmonar sem alteração e glândula tireoide\nnormal à palpação. O fundo uterino encontrava-se ao nível da cicatriz umbilical e os batimentos\ncardíacos fetais estavam na faixa de 140 bpm a 150 bpm. Constatou-se nos membros inferiores\nausência de edema e pulsos preservados. Considerando esse caso clínico, julgue o item que se\nsegue. Nenhum sintoma apresentado pela paciente condiz com sintoma de lúpus eritematoso\nsistêmico ou de outra doença autoimune.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-183851","number":"183851","sourceNumber":"183851","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante, com vinte e seis anos de idade, G2P1, idade gestacional de vinte e duas\nsemanas, exibiu, em sua primeira consulta\npré-natal, havia quatro semanas, resultados\nlaboratoriais normais, inclusive nível de hemoglobina normal e nenhum antecedente patológico\ndigno de nota. No retorno para a segunda consulta, queixou-se de fadiga e astenia persistentes por\numa semana. Nessa ocasião, apresentou nível de hemoglobina de 7,0 g/dL. Relatou ter observado\nurina escura depois de ter feito uso de um antibiótico, prescrito em atendimento emergencial, para\ninfecção do trato urinário. Os resultados do exame físico foram: PA = 110 mmHg x 70 mmHg, FC =\n80 bpm, afebril, ictérica +/4+, ausculta cardíaca e pulmonar sem alteração e glândula tireoide\nnormal à palpação. O fundo uterino encontrava-se ao nível da cicatriz umbilical e os batimentos\ncardíacos fetais estavam na faixa de 140 bpm a 150 bpm. Constatou-se nos membros inferiores\nausência de edema e pulsos preservados. Considerando esse caso clínico, julgue o item que se\nsegue. Os sintomas refletem um provável processo de anemia hemolítica, devido possivelmente à\ndeficiência de glicose-6-fosfato desidrogenase: condição ligada ao X segundo a qual as hemácias\npodem ter capacidade reduzida de metabolismo anaeróbio da glicose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-168464","number":"168464","sourceNumber":"168464","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 32 anos de idade, no quinto dia de puerpério de parto normal, retorna\nà maternidade com queixa de dor intensa em\npanturrilha esquerda. Nega febre e, ao exame físico,\nobservam-se: varizes em membros inferiores bilateralmente, panturrilha esquerda empastada com\nedema e aumento da temperatura local. Diante desse quadro, a conduta adequada é recomendar:","options":{"A":"Internação, repouso no leito, manutenção dos membros inferiores elevados e calor local.","B":"Internação, repouso no leito, realização de exame de ultrassom com Doppler e terapia\nanticoagulante.","C":"Repouso no domicílio, uso de meia elástica e orientação para retorno, caso não haja melhora\nem 2 dias.","D":"Repouso no domicílio, tratamento com anti-inflamatórios não hormonais e controle semanal com\nresultados de hemograma e coagulograma."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-158025","number":"158025","sourceNumber":"158025","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 35 anos de idade, GIP0, idade gestacional de 39 semanas e três dias, foi\nencaminhada ao pronto-socorro de obstetrícia pelo médico do pré-natal em função do valor da\nPressão Arterial (PA) ser 150 mmHg x 100 mmHg em consulta pela manhã. Nega cefaleia,\nepigastralgia ou alterações visuais. Nas consultas anteriores aferições sempre se encontravam\ndentro dos parâmetros da normalidade. Ultrassonografia realizada após a consulta evidencia feto\ncom peso estimado no percentil 30 para a idade gestacional e doppler fetal sem alterações. É\nrealizada avaliação laboratorial que não demonstra alterações bioquímicas, EAS sem evidência de\nproteinúria. No momento, apresenta: PA = 148 mmHg x 106 mmHg; BCF = 142 bpm; edema 3+/4+.\nNesse caso clínico, o diagnóstico mais provável é:","options":{"A":"Hipertensão gestacional sem proteinúria.","B":"Pré-eclâmpsia leve.","C":"Síndrome Hellp parcial.","D":"Pré-eclâmpsia grave.","E":"Hipertensão arterial crônica"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-158029","number":"158029","sourceNumber":"158029","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 35 anos de idade, GIP0, idade gestacional de 39 semanas e três dias, foi\nencaminhada ao pronto-socorro de obstetrícia pelo médico do pré-natal em função de o valor da\nPressão Arterial (PA) ser 150 mmHg x 100 mmHg em consulta pela manhã. Nega cefaleia,\nepigastralgia ou alterações visuais. Nas consultas anteriores aferições sempre se encontravam\ndentro dos parâmetros da normalidade. Ultrassonografia realizada após a consulta evidencia feto\ncom peso estimado no percentil 30 para a idade gestacional e doppler fetal sem alterações. É\nrealizada avaliação laboratorial que não demonstra alterações bioquímicas, EAS sem evidência de\nproteinúria. No momento, apresenta: PA = 148 mmHg x 106 mmHg; BCF = 142 bpm; edema 3+/4+.\nQuanto à conduta mais indicada no caso clínico apresentado, assinale a alternativa CORRETA:","options":{"A":"Prescrever metildopa e liberar a paciente com orientação de retornar ao pré-natal para\nseguimento até 41 semanas.","B":"Internar e prescrever sulfato de magnésio em função do nível pressórico e do risco de\nconvulsão.","C":"Internar e programar resolução da gestação por via de indicação obstétrica.","D":"Internar e realizar cesariana assim que a pressão estiver estabilizada.","E":"Internar e realizar cesariana logo em seguida."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157962","number":"157962","sourceNumber":"157962","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 34 anos de idade, G4P3COAO, idade gestacional de 37 semanas e um\ndia, com gestação gemelar dicoriônica diamniótica, ambos os fetos em apresentação cefálica,\ncomparece ao pronto-socorro por contrações. Não apresentou intercorrências no pré-natal. No\nmomento, apresenta três contrações de 30 segundos em 10 minutos e o colo uterino está 80%\napagado, dilatado 5 cm, bolsa íntegra, polo cefálico flutuante. Considerando esse caso clínico,\nassinale a alternativa CORRETA.","options":{"A":"A paciente deve ser levada, o mais rápido possível, para cesariana, já que gestação gemelar é\ncontraindicação para parto normal.","B":"A paciente pode evoluir para parto normal, desde que o peso fetal estimado dos fetos esteja\nabaixo de 3 kg.","C":"Caso haja evidência ultrassonográfica de circular cervical de cordão, a paciente deve ser\nsubmetida a cesariana para evitar sofrimento fetal.","D":"A paciente pode evoluir para parto normal caso não apresente intercorrências durante o trabalho\nde parto.","E":"Não deve ser realizada amniotomia para que não ocorra entrelaçamento dos cordões umbilicais."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-157968","number":"157968","sourceNumber":"157968","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 34 anos de idade, G4P3COAO, idade gestacional de 37 semanas e um\ndia, com gestação gemelar dicoriônica diamniótica, ambos os fetos em apresentação cefálica,\ncomparece ao pronto-socorro por contrações. Não apresentou intercorrências no pré-natal. No\nmomento, apresenta três contrações de 30 segundos em 10 minutos e o colo uterino está 80%\napagado, dilatado 5 cm, bolsa íntegra, polo cefálico flutuante. Com base no caso clínico, e\nconsiderando os conhecimentos médicos a ele relacionados, acerca das gestações gemelares,\nassinale a alternativa CORRETA:","options":{"A":"As gestações gemelares monocoriônicas diamnióticas são as que apresentam menos risco para\nos fetos de forma geral.","B":"A ocorrência de gêmeos siameses ou gemelaridade imperfeita se dá quando o zigoto se divide\nantes do 12º dia de desenvolvimento.","C":"Em gestações dicoriônicas diamnióticas, os fetos são sempre do mesmo sexo.","D":"Caso a gestação fosse monocoriônica diamniótica haveria a possibilidade de ter desenvolvido\nsíndrome da transfusão feto-fetal, uma condição clínica que pode ser grave e fatal para os fetos.","E":"A definição da zigosidade é muito importante para a condução do pré-natal e deve ser feita na\nprimeira ultrassonografia."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-168454","number":"168454","sourceNumber":"168454","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 30 anos de idade, primigesta, com gestação a termo, internada em\num hospital, apresenta pré-eclâmpsia com\nsinais de sofrimento fetal, tendo-se optado por\ninterrupção da gestação. Em seu prontuário, registra-se que, no segundo trimestre da gestação, a\npaciente havia apresentado dosagens de TSH = 5,0 mcU/L (valor de referência 0,3 a 4,0 mcU/L) e\nde T4 livre = 0,7 ng/L (valor de referência: 0,9 a 1,7 ng/L), tendo sido aumentada a dose da\nlevotiroxina que a paciente usava algum tempo antes de iniciada a gravidez, de 50 mcg para 100\nmcg. No puerpério imediato, ainda durante a sua internação hospitalar, qual deve ser a indicação\nadequada para a paciente quanto à dose diária de levotiroxina?","options":{"A":"Manter a dose de 100 mcg até o 28º dia de puerpério.","B":"Retornar o uso regular para a dose pré-gestacional de 50 mcg.","C":"Aumentar para 125 mcg e manter durante o período de lactação.","D":"Suspender o uso dessa medicação e avaliar, em 40 dias, a necessidade de reintroduzir o\nmedicamento."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-168526","number":"168526","sourceNumber":"168526","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 25 anos de idade, provinda de região Nordeste do Brasil, na 16 ª\nsemana de sua primeira gestação, é\natendida na Unidade Básica de Saúde (UBS) para a\nrealização de pré-natal , referindo discreto exanterna com prurido há 2 dias, acompanhado de um\nepisódio de febre de 38 ºC, além de poliartralgia discreta. Ao exame físcio, apresenta temperatura\naxilar = 37,8 ºC , hiperemia conjuntival, frequência respiratória = 18 irpm, frequência cardíaca =\n80\nbpm, com exanterna difuso discreto. Realizada a prova do laço, o resultado mostra-se negativo.\n\nNão se constataram visceronegalias e outros sinais ou achados ao exame físico. Considerando a\nhipótese provável de infecção viral e realizada a Notificação Compulsória da suspeita clínica de\ninfecção por Zika vírus e dengue, a conduta médica indicada é","options":{"A":"solicitar a paciente o retorno diário a UBS, com monitoramento domiciliar da temperatura, para\nacompanhar evolução clínica e laboratorial com realização de hemograma completo e funções\nhepática e renal sequenciais.","B":"solicitar imediatamente pesquisa para infecção por Zika vírus (por RT-PCR) e dengue (por\nNS-1), além de recomendar à paciente a adoção\nde medidas de proteção pessoal e familiar para\nminimizar a exporsição ao vetor.","C":"encaminhar a paciente ao serviço de saúde referência para gestação de alto risco, sugerindo\ninvestigação das hipóteses de infecção por\nZika vírus ou dengue e soliciar exame ultrassonográfico\nobstétrico.","D":"solicitar avaliação complementar e sequencial de plaquetas em Unidade de Pronto\nAntendimento e sorologia para infecção por Zika\nVírus no sexto dia dos sintomas, orientando a\npaciente acerca dos sinais de alerta."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-154469","number":"154469","sourceNumber":"154469","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"São sinais de gravidade na pré-eclâmpsia, EXCETO:","options":{"A":"Trombocitopenia <100.000/mm³.","B":"Escotomas.","C":"Edema agudo de pulmão.","D":"Enzimas hepáticas (TGO, TGP) elevadas.","E":"Tromboembolismo pulmonar."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-168490","number":"168490","sourceNumber":"168490","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante com 37 anos de idade, com gravidez de 8 semanas confirmada por\nultrassonografia realizada há uma semana, comparece à Unidade Básica de Saúde para iniciar\nacompanhamento pré-natal. Como antecedentes familiares, cita o pai e a mãe como portadores de\ndiabetes melito, ambos em tratamento com hipoglicemiantes orais. A paciente apresenta resultados\nde glicemia de jejum de 180 mg/dL em duas dosagens realizadas em dias diferentes. Nesse caso\nclínico, a conduta indicada é","options":{"A":"dieta para diabetes e reavaliação clínico-laboratorial em 4 semanas.","B":"administração de metformina.","C":"administração de sulfoniureia.","D":"insulinoterapia."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-168463","number":"168463","sourceNumber":"168463","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma primigesta com 27 anos de idade, na 31ª semana de gestação, procura a\nemergência obstétrica, queixando-se de cefaleia\noccipital moderada e persistente há 12 horas. O\nexame físico revela: palidez cutâneo-mucosa ++/4+; edema de membros inferiores +++/4+; pressão\narterial = 145 x 95 mmHg; altura uterina = 30 cm; batimentos cardíacos fetais = 140 bpm, com\naceleração transitória presente. Dinâmica: duas contrações de 30 segundos em 10 minutos. Toque\nvaginal: colo grosso, posterior, uma polpa digital, bolsa íntegra. Cardiotocografia com padrão\ntranquilizador. Os resultados dos exames laboratoriais demonstram: hematócrito = 39% (valor de\nreferência: 36 a 54%); hemoglobina = 13 g/dl (valor de referência: 13,0 a 16,5 g/dl); plaquetas =\n65.000/ml (valor de referência: 130.000 a 450.000/mm³); desidrogenase láctica = 1.500 UI/L (valor\nde referência: 240 a 480 U/L); aspartato aminotransferase = 105 UI/L (valor de referência: < 34\nU/L); proteinúria em fita +++/4+. Em face desse quadro clínico, a conduta adequada é:","options":{"A":"Administrar sulfato de magnésio e corticoterapia para a maturação pulmonar fetal e iniciar a\nindução do parto vaginal, após 24 horas da segunda dose do corticoide.","B":"Prescrever corticoterapia para a maturação pulmonar fetal e iniciar a indução do parto vaginal,\napós 24 horas da segunda dose do corticoide.","C":"Administrar sulfato de magnésio, estabilizar clinicamente a paciente e proceder à resolução da\ngestação por parto cesáreo.","D":"Iniciar tocólise com nifedipina via oral e prescrever corticoterapia para maturação pulmonar\nfetal."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-159518","number":"159518","sourceNumber":"159518","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"No que se refere às intercorrências clínicas da gestação, julgue o item seguinte. A\nrecomendação de dieta hipossódica desde o primeiro trimestre de gravidez é ineficaz para a\nprevenção da pré-eclampsia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-159520","number":"159520","sourceNumber":"159520","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"No que se refere às intercorrências clínicas da gestação, julgue o item a seguir. O\ntratamento da bacteriúria assintomática em pacientes gestantes deve ser realizado para evitar a\nocorrência de pielonefrite, cujo principal agente etiológico é o Proteus mirabilis.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-168456","number":"168456","sourceNumber":"168456","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma mulher com 20 anos de idade, primigesta na 19ª semana de gestação, procura o\nPronto-Socorro com história de febre não medida há 24 horas e queixa de disúria, polaciúria,\nurgência miccional, dor lombar e náuseas. Ao exame físico, apresenta-se em regular estado geral,\nafebril, frequência cardíaca = 98 bpm, frequência respiratória = 25 irpm, pressão arterial = 90 x 60\nmmHg, desidratada ++/4+ e com dor à punho-percussão da região lombar direita. Diante desse\nquadro clínico, a conduta adequada é","options":{"A":"internação hospitalar para hidratação e administração de analgésicos, antiespasmódicos e\nantieméticos endovenosos; solicitação de urocultura e antibiograma para início de\nantibioticoterapia.","B":"acompanhamento na Unidade de Atenção Básica; solicitação de urocultura e antibiograma para\ninício de antibioticoterapia por via oral.","C":"acompanhamento na Unidade de Atenção Básica; início do tratamento sintomático e\nantibioticoterapia por via oral.","D":"internação hospitalar para antibioticoterapia e hidratação endovenosas; administração de\nanalgésicos, antiespasmódicos e antieméticos."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-159540","number":"159540","sourceNumber":"159540","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com relação às patologias endócrinas no contexto da ginecologia e da obsetrícia,\njulgue o item subsecutivo. Pacientes\ngrávidas com exacerbação do hipertireoidismo e consequente\ninsuficiência cardíaca podem usar betabloqueadores, desde que por curto prazo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-129052","number":"129052","sourceNumber":"129052","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A hipertensão arterial sistêmica pode comprometer a saúde da gestante e do feto.\nQuando a elevação dos níveis tensionais se\nmanifesta antes das vinte semanas de gestação e(ou)\npersiste com agravamento dos níveis pressóricos já previamente elevados, mesmo transcorridas\ndoze semanas do parto, com proteinúria presente, alterações de enzimas hepáticas e\ntrombocitopenia, trata-se de","options":{"A":"Pré-eclâmpsia.","B":"Hipertensão arterial crônica.","C":"Hipertensão arterial crônica com pré-eclâmpsia sobreposta.","D":"Hipertensão gestacional persistente.","E":"Eclâmpsia."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-129051","number":"129051","sourceNumber":"129051","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Alguns fatores isolados ou associados podem comprometer a saúde da mulher, ou,\nquando gestante, a do binômio mãe e filho, por longo prazo. Quanto a esses riscos, é correto\nafirmar que o(a):","options":{"A":"Pré-eclâmpsia e o retardo de crescimento intrauterino secundário à insuficiência placentária\ncompartilham os mesmos fatores de risco, mas apresentam manifestações clínicas diferentes.","B":"Taxa de mortalidade fetal é bem maior quando a pressão diastólica materna é superior a 95\nmmHg, independentemente da presença de proteinúria.","C":"Uso de anticoncepcionais associado ao cigarro não aumenta significativamente o risco de sofrer\nderrame cerebral e infarto devido à segurança de microdoses hormonais nos contraceptivos\nmodernos.","D":"Controle da hipertensão com medicação anti-hipertensiva é mais fácil em adultos que nasceram\ncom baixo peso.","E":"Uso materno de álcool, drogas ilícitas e tabaco ocasiona retardo do crescimento intrauterino,\nmas somente o tabagismo interfere no fluxo e na\noxigenação placentária."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-104768","number":"104768","sourceNumber":"104768","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante primigesta de 26 semanas, em acompanhamento no pré-natal de risco\nhabitual, apresentou, na consulta, aumento dos níveis pressóricos. Ao exame físico, constatou-se\nPA em repouso de 145 x 100 mmHg (confirmada), edema MMII +/4+, BCF positivo e AFU\ncompatível com a idade gestacional. O obstetra iniciou medicação anti-hipertensiva apropriada,\nsolicitou ecografia obstétrica com Doppler e encaminhou a paciente ao pré-natal de alto risco.\n\nConsiderando esse caso hipotético, assinale a alternativa que apresenta a medicação que\nprovavelmente foi prescrita.","options":{"A":"Captopril.","B":"Enalapril.","C":"Hidralazina.","D":"Metildopa.","E":"Losartana."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-111290","number":"111290","sourceNumber":"111290","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Em relação às síndromes hipertensivas na gestação, assinale a alternativa correta:","options":{"A":"A pré-eclâmpsia caracteriza-se por hipertensão arterial de aparecimento precoce acompanhada\nde proteinúria com desaparecimento até 12 semanas\ndo parto.","B":"A hipertensão arterial crônica isolada cursa com proteinúria tardia, desaparecendo até 12\nsemanas após o parto.","C":"Ocorre sobreposição da pré-eclâmpsia quando as gestantes previamente hipertensas\napresentam proteinúria.","D":"O aparecimento da hipertensão arterial isolada, após a 20ª semana de gravidez caracteriza a\npré-eclâmpsia.","E":"A proteinúria não é critério para diferenciação dos quadros hipertensivos na gravidez."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-97772","number":"97772","sourceNumber":"97772","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma primigesta, com 37 semanas de gestação, queixa-se de edema de membros\ninferiores há uma semana. O cartão de\npré-natal apresenta anotações conforme demonstrado na\nfigura a seguir (VER IMAGEM). Ao exame físico apresenta bom estado geral, pressão arterial = 150\nx 90 mmHg, altura uterina = 34 cm, dinâmica uterina ausente, ausculta fetal = 140 bpm, sem\ndesacelerações, edema de membros inferiores ++/4+. Toque vaginal: colo grosso e impérvio.\n\nProteinúria de fita +/4+. Qual o diagnóstico correto e a conduta mais adequada?","options":{"A":"Hipertensão gestacional; solicitação de exames para avaliação do bem-estar fetal e seguimento\nno pré-natal.","B":"Pré-eclâmpsia leve; hospitalização para repouso relativo, dieta normossódica e avaliação do\nbem-estar fetal.","C":"Pré-eclâmpsia leve; solicitação de exames para avaliação do bem-estar fetal e seguimento no\npré-natal.","D":"Pré-eclâmpsia grave; hospitalização para resolução da gestação por indução do parto ou\ncesárea."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-80728","number":"80728","sourceNumber":"80728","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de onze semanas realiza ultrassonografia com identificação do sinal do\nlambda, conforme demonstrado na figura (VER\nIMAGEM). Frente ao achado, é CORRETO afirmar\nque se trata de gestação:","options":{"A":"Gemelar dicoriônica.","B":"Gemelar monocoriônica diamniótica.","C":"Ectópica.","D":"Tópica única.","E":"Anembrionada."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-80743","number":"80743","sourceNumber":"80743","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante primigesta em seguimento pré-natal com idade gestacional (IG) de 21\nsemanas pela data da última mestruação (DUM),\npreviamente normotensa, apresenta elevação dos\nníveis pressóricos com valores em torno de 150 x 100 mmHg. Nega antecedentes pessoais de\nhipertensão arterial. Relata avó paterna com diabete melito. Considerando a suspeita de doença\nhipertensiva específica da gestação (DHEG), assinale a alternativa correta.","options":{"A":"Frente aos dados clínicos do enunciado, pode-se enumerar como fatores de risco para DHEG\nnessa paciente o histórico gestacional e o\nantecendente familiar de diabete.","B":"O diagnóstico só pode ser confirmado após 24 semanas de gestação por meio de\nultrassonografia com doppler de artérias uterinas e visualização da incisura protodiastólica.","C":"É conduta adequada orientar dieta hipossódica para a paciente e iniciar anti-hipertensivo\nimediatamente, devendo-se evitar bloqueadores do\ncanal de cálcio, diuréticos e inibidores da\nenzina conversora de angiotensina.","D":"Deve ser solicitada dosagem de proteína na urina para confirmação do diagnóstico, valores\niguais ou acima de 300 mg/dia em urina de 24 horas confirmam DHGE.","E":"A avaliação da vitalidade fetal é investigada por meio da amnioscopia e da ultrassonografia com\ndoppler de artérias umbilicais."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-75523","number":"75523","sourceNumber":"75523","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher com 23 anos de idade, primigesta, idade gestacional de 30 semanas, vem à\nquarta consulta de pré-natal. Não relata nenhuma queixa. Ao exame clínico, apresenta pressão\narterial = 140 x 90 mmHg (em decúbito lateral esquerdo), pulso = 80 bpm, altura uterina = 31 cm e\nfrequência cardíaca fetal = 140 bpm. Traz exame de proteinúria de 24 horas com valor de 412\nmg/24h. Hemograma apresentando contagem de plaquetas de 220.000/mm³. No cartão da\ngestante, estão anotadas as seguintes medidas da pressão arterial registradas nas consultas\nanteriores: 110 x 70 mmHg, 120 x 70 mmHg e 140 x 100 mmHg. O diagnóstico correto é:","options":{"A":"pré-eclâmpsia leve.","B":"pré-eclâmpsia grave.","C":"iminência de eclâmpsia.","D":"hipertensão gestacional.","E":"hipertensão arterial crônica."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-75457","number":"75457","sourceNumber":"75457","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher com 36 anos de idade, secundigesta, na 27ª semana de gestação, está\nrealizando pré-natal em Unidade Básica de Saúde.\nRelata que sua primeira gestação transcorreu\nde forma tranquila e que seu filho nasceu bem, de parto vaginal, pesando 4.200 gramas. Ao exame\nfísico, nota-se pressão arterial = 120 x 80 mmHg, ausência de edemas. Ao exame obstétrico: altura\nuterina = 28 cm, batimentos cardíacos fetais = 144 bpm, movimentação fetal presente. Realizou\nglicemia de jejum na primeira consulta com resultado de 83 mg/dl. Em relação ao rastreamento do\ndiabetes gestacional, é indicado para esta gestante:","options":{"A":"realizar manejo expectante, já que apresentou glicemia normal na primeira consulta e, portanto,\nnão tem risco de desenvolver diabetes\ngestacional.","B":"repetir a glicemia de jejum com 28 semanas e caso\nseja normal, refazer o exame com 34 semanas.","C":"realizar exame de hemoglobina glicada com 34 semanas, para diagnóstico de diabetes\ngestacional.","D":"solicitar teste oral de tolerância a glicose com 75g, com 28 semanas de gestação.","E":"solicitar dosagem de glicemia pós-prandial, com 34 semanas de gestação."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-137538","number":"137538","sourceNumber":"137538","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante de 32 anos de idade, gesta = 2, para = 1, hoje com 15 semanas de\ngestação, comparece a sua segunda consulta de\npré-natal. Encontra-se assintomática. Tem\nhistórico de parto pré-termo há 4 anos devido a descolamento prematuro de placenta, com\ncomplicação de hemorragia pós-parto. Nega história de hipertensão, pré-eclâmpsia e diabetes\ngestacional anterior. O filho anterior nasceu com 36 semanas, pesou 2 050 g e mediu 40 cm. A\ngestante nega o uso, na gravidez anterior, de quaisquer medicações, exceto sulfato ferroso e ácido\nfólico. Ao exame clínico apresentou: PA = 110 x 60 mmHg; FC = 80 bpm; altura uterina = 15 cm;\nbatimentos cardiofetais = 152 bpm; toque: colo fechado, grosso e posterior. A paciente traz os\nresultados dos seguintes exames laboratoriais: glicemia de jejum = 65 mg/dL (valor de referência <\n99 mg/dL); sorologia para toxoplasma gondii = IgM não reagente/IgG reagente; sorologia rubéola =\nIgG reagente/IgM não reagente; VDRL não reagente; TSH = 15 UI/ml (valor de referência = 0,4 a\n5,0 UI/ml), hemograma com Hb =12,0 g/dL (valor de referência =11,3 a 16,3 g/dL), leucócitos e\nplaquetas normais. Com base na história clínica e nos resultados dos exames acima apresentados\né correto afirmar que","options":{"A":"a gestante deve iniciar reposição de hormônio tireoidiano.","B":"os níveis de T4 livre da gestante estão necessariamente\nelevados.","C":"o quadro clínico apresentado não sugere risco de parto\nprematuro.","D":"a mesma rotina laboratorial deve ser repetida após 30 dias\npara nova avaliação.","E":"a gestante está assintomática, fato que não indica reposição de hormônio tiroidiano."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-137577","number":"137577","sourceNumber":"137577","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 25 anos de idade, com história obstétrica gesta = 1, para = 0, aborto =\n0, com 28 semanas de idade gestacional, foi atendida na Unidade Básica de Saúde (UBS) referindo\nque há 2 dias está gripada e fez uso de medicação sintomática. Resolveu vir ao posto de saúde\nporque está tossindo muito. Ao ser realizado o exame físico, constatou-se: temperatura axilar =\n38,1ºC, frequência respiratória = 30 irpm, pressão arterial = 80 x 60 mmHg, normohidratada.\n\nQual é a abordagem adequada para o caso?","options":{"A":"Encaminhar a paciente para internação hospitalar.","B":"Solicitar hemograma completo e radiografia de tórax com urgência.","C":"Orientar hidratação, prescrever paracetamol e solicitar retorno se piorar.","D":"Solicitar hemograma completo, prescrever vitamina C, dipirona e nebulização.","E":"Prescrever dipirona, nebulização sem uso de broncodilatador e reavaliar a paciente em 48 horas."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-137524","number":"137524","sourceNumber":"137524","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Acerca de distúrbios hipertensivos na gestação, é correto afirmar que uma paciente\ngestante com","options":{"A":"hipertensão acima de 140 x 90 mmHg, sem edema e sem proteinúria, apresenta característica\nde pré-eclâmpsia grave.","B":"hipertesão leve ou moderada, sem edema e sem proteinúria, apresenta característica de\nhipertensão transitória.","C":"hipertensão, edema e proteinúria antes das 20 semanas de gestação, apresenta características\nde doença hipertensiva específica da gestação.","D":"hipertensão antes das 20 semanas de gestação com proteinúria de 24 horas com mais de 300\nmg/L, apresenta característica de hipertensão crônica.","E":"acréscimo na pressão diastólica de 15mmHg e na sistólica de 30mmHg, com edema, apresenta\ncaracterísticas de doença hipertensiva específica da gestação."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-137682","number":"137682","sourceNumber":"137682","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 38 anos de idade, obesa, multípara, descobriu-se grávida aos 4\nmeses. Como era uma gravidez não desejada,\ndemorou para iniciar seu pré-natal. Em sua primeira\nconsulta pré-natal, apresentava idade gestacional pela última menstruação de 26 semanas, com\nfundo do útero medindo 27 centímetros. O médico, além dos exames da rotina pré-natal normal,\nsolicitou o teste oral de tolerância à glicose, com sobrecarga de 75 mg de dextrosol. Os seguintes\nresultados foram encontrados: glicemia de jejum: 100 mg /dL; 1 hora pós-sobrecarga: 190 mg /dL; 2\nhoras póssobrecarga: 143 mg /dL. Durante o resto do pré-natal, e a despeito das orientações\nmédicas, a paciente não aderiu a uma dieta equilibrada, ainda que o doppler da artéria umbilical\nnão tenha apresentado alterações significativas. Considerando esses resultados, a que risco o feto\ndessa paciente está sujeito?","options":{"A":"Macrossomia.","B":"Espinha bífida.","C":"Agenesia sacral.","D":"Malformação do tubo neural.","E":"Restrição de crescimento intrauterino."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-138399","number":"138399","sourceNumber":"138399","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Quanto ao desenvolvimento de diabetes gestacional em paciente primigesta, com 29\nanos de idade, estatura de 1,50 m , peso\npré-gravídico de 70Kg, peso atual de 75Kg na 24ª\nsemana de gestação e glicemia em jejum de 90mg/dl, pode-se afirmar","options":{"A":"a ausência de risco pela idade inferior a 30 anos\nda gestante.","B":"a existência de risco pelo ganho excessivo de peso na gestação.","C":"a ausência de risco pela normalidade da glicemia de jejum da gestante.","D":"a existência de risco pelo IMC pré-gravídico superior a 27Kg/m2.","E":"a ausência de risco pela inexistência de antecedentes familiares da gestante."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-138400","number":"138400","sourceNumber":"138400","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher com 34 anos de idade, gestante de 28 semanas, iniciou quadro febril há cinco\ndias associado a dor no hemitórax esquerdo à\nrespiração profunda. Há dois dias passou a\napresentar tosse produtiva com expectoração amarelada. Procurou Unidade de Pronto\nAtendimento. Ao exame: bom estado geral; sinais vitais: Pulso = 100 bpm; Pressão arterial = 120 x\n80 mmHg; Frequência respiratória = 23 irpm. Temperatura axilar = 39 °C; Ausculta pulmonar:\ncrepitações, broncofonia e aumento do frêmito tóraco-vocal na base do pulmão esquerdo. O\nleucograma apresenta 15.800 leucócitos/mm3, com predomínio de polimorfonucleares neutrófilos.\nQual a conduta a ser tomada, com relação a exames de imagem e tratamento antimicrobiano?","options":{"A":"Solicitar radiografia de tórax com proteção abdominal e iniciar tratamento com amoxicilina oral.","B":"Solicitar ultrassonografia de tórax e iniciar tratamento com quinolona respiratória oral.","C":"Solicitar tomografia computadorizada do tórax e\niniciar tratamento com aminoglicosídeo injetável","D":"Solicitar radiografia de tórax com proteção abdominal e iniciar claritromicina oral.","E":"Solicitar tomografia computadorizada do tórax e\niniciar vancomicina injetável."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-31006","number":"31006","sourceNumber":"31006","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante com 29 anos de idade, previamente hígida, com 12 semanas de\ngestação, procurou atendimento no\npronto-socorro com relato de tosse seca e dor torácica à direita\nhá um dia. Informou que, no dia da consulta, pela manhã, sentiu-se cansada durante o banho,\napresentando melhora após repouso. Relatou, ainda, que a temperatura corporal de 37,8°C\nnormalizou-se após o banho. Ao exame clínico apresentou: frequência cardíaca de 95 bpm,\nfrequência respiratória de 22 irpm, pressão arterial de 100 mmHg x 60 mmHg. A ausculta pulmonar\nevidenciou murmúrio vesicular discretamente reduzido em região infraescapular direita, com\ncrepitações teleinspiratórias no mesmo local. Não havia sinais de trombose venosa profunda em\nmembros inferiores. Considerando esse caso clínico, julgue o item que se segue. Nesse caso, a\nangiotomografia torácica é absolutamente contraindicada, por tratar-se de paciente no primeiro\ntrimestre de gestação, devendo-se, então, utilizar a cintilografia ventilação-perfusão para\ninvestigação diagnóstica.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-31013","number":"31013","sourceNumber":"31013","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma gestante com 29 anos de idade, previamente hígida, com 12 semanas de\ngestação, procurou atendimento no\npronto-socorro com relato de tosse seca e dor torácica à direita\nhá um dia. Informou que, no dia da consulta, pela manhã, sentiu-se cansada durante o banho,\napresentando melhora após repouso. Relatou, ainda, que a temperatura corporal de 37,8°C\nnormalizou-se após o banho. Ao exame clínico apresentou: frequência cardíaca de 95 bpm,\nfrequência respiratória de 22 irpm, pressão arterial de 100 mmHg x 60 mmHg. A ausculta pulmonar\nevidenciou murmúrio vesicular discretamente reduzido em região infraescapular direita, com\ncrepitações teleinspiratórias no mesmo local. Não havia sinais de trombose venosa profunda em\nmembros inferiores. Considerando esse caso clínico, julgue o item que se segue. Considere que\nessa paciente tenha o diagnóstico de embolia pulmonar confirmado. Nesse caso, o uso de\nanticoagulantes orais (inibidores de vitamina K) é opção terapêutica que pode ser usada apenas\ndurante o segundo e o terceiro trimestre da gestação, pois os efeitos colaterais associados a esses\nmedicamentos só ocorrem no primeiro trimestre.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-138597","number":"138597","sourceNumber":"138597","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente do sexo feminino, assintomática, em avaliação de rotina, determinada pelo\nseu médico assistente, é submetida à coleta de duas amostras de urinocultura, que revelam\ncrescimento de >100.000 Unidades Formadoras de Colônias/ml de Escherichia coli, nas duas\namostras, com o mesmo perfil de sensibilidade. A solicitação das urinoculturas e o tratamento\nantibiótico da bactéria isolada são justificadas, se a paciente em questão for","options":{"A":"muito idosa, moradora de asilo.","B":"diabética, insulino-dependente.","C":"portadora de cateter vesical de demora.","D":"gestante, em qualquer idade gestacional.","E":"jovem, sexualmente ativa."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-31003","number":"31003","sourceNumber":"31003","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Com referência a intercorrências clínico-cirúrgicas e obstétricas, julgue o próximo item:\nA doença hipertensiva específica da gestação é\numa das complicações mais comuns da gravidez e\nse caracteriza pela presença de hipertensão arterial, edema e(ou) proteinúria. Nas formas graves\nda doença, a mortalidade materna e a perinatal são elevadas.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-138677","number":"138677","sourceNumber":"138677","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente, com 27 anos de idade, segunda gestação (um parto normal anterior), com\nidade gestacional de 38 semanas, confirmada por\nultrassonografi a de 10 semanas, apresenta\ndinâmica uterina positiva e forte cefaléia. Refere uso de metildopa - 750mg/dia em três tomadas.\nFoi admitida com esse quadro na emergência de um hospital, queixando-se também de visão turva\ne de grande mal estar. A anamnese e exame físico indicam paciente inquieta, poliqueixosa,\nreferindo medo de morrer. Pressão arterial = 190x120mmhg, colo uterino fino e dilatado para 8 cm,\napresentação cefálica, dorso à esquerda, contrações uterinas presentes - três em 10 minutos, de\n45 segundos . Com base no quadro acima, qual o diagnóstico correto e a conduta a ser adotada?","options":{"A":"Pré-eclâmpsia grave. Paciente com indicação de parto cesáreo após normalização pressórica\ncom\n\nnifedipina ou hidralazina.","B":"Eclâmpsia eminente. Indicação de sulfato de magnésio e hidralazina para correção dos níveis\npressóricos e resolução do parto por via alta.","C":"Pré-eclâmpsia grave. Indicação de sulfato de magnésio e nifedipina para correção dos níveis\npressóricos e resolução por parto abdominal.","D":"Crise hipertensiva na gestação e pré eclâmpsia. Indicação de cesárea pela necessidade de\nremoção da placenta e introdução de nifedipina para correção dos níveis pressóricos.","E":"Eminência de eclâmpsia. Indicação de sulfato de\n\nmagnésio e hidralazina para correção dos níveis pressóricos e resolução por parto vaginal."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-138733","number":"138733","sourceNumber":"138733","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Mulher, com 35 anos de idade, obesa. Teve duas gestações, um parto e zero abortos.\nAtualmente, gestante de 14 semanas, vem à consulta de pré-natal trazendo seus exames, nos\nquais a glicemia de jejum tem valor de 90 mg/dL. Tem histórico obstétrico com filho anterior\npesando 4.200 g, nascido com 37 semanas e cinco dias. Nesse caso, além da orientação dietética\npara prevenção de ganho de peso anormal, a conduta apropriada é","options":{"A":"internação para realizar perfil glicêmico e realização de ecografia pelo alto risco de más\nformações fetais, especialmente cardíacas e de tubo neural.","B":"realização de teste de sobrecarga da glicose e, se normal, reavaliação em idade gestacional\nposterior.","C":"realização de teste de sobrecarga da glicose e, se alterado, introdução de insulina.","D":"realização de teste oral de sobrecarga da glicose e, se normal, afastada a possibilidade de\ndesenvolvimento de diabetes gestacional durante a gravidez atual.","E":"Internação para realizar perfil glicêmico e introdução de insulina para prevenir macrossomia\nfetal."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-19252","number":"19252","sourceNumber":"19252","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Uma paciente de 28 anos de idade, G1P0A0, vinha sendo atendida no pré-natal de\nbaixo risco, sem apresentar nenhuma\nintercorrência clínica. Na 24ª semana de gestação,\napresentou os seguintes achados clínicos e laboratoriais: edema em membros inferiores +/4+;\npressão arterial máxima de 140/90 mmHg em algumas aferições; proteína em urina de 24h = 200\nmg/dL (VR < 300 mg/dL); clearence de creatinina = 120 mg/dL (VR 80?125 mg/dL); TGO = 15 UI/L\n(VR < 30 UI/L); TGP = 20 UI/L (VR < 30 UI/L); DHL = 250 UI/L (VR 150?330 UI/L); plaquetas =\n\n160.000 cel/mm3 (VR: 150.000 cel/mm3); ácido úrico = 4,0 mg/dL (VR: 3,0?6,0 mg/dL); EAS\nnormal. A partir do caso clínico apresentado\nacima, julgue o item a seguir. A paciente apresenta\nquadro clínico compatível com hipertensão gestacional ou transitória, cujo diagnóstico final é\ndefinido somente após o parto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-19273","number":"19273","sourceNumber":"19273","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Julgue o item seguinte quanto a gestação múltipla. A gestação gemelar monozigótica\npode ser dicoriônica / diamniótica;\nmonocoriônica / diamniótica; monocoriônica / monoamniótica e\nconceptos unidos, enquanto a gestação dizigótica é sempre dicoriônica / diamniótica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-368175","number":"368175","sourceNumber":"368175","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente está com nove semanas de gestação e informa que fazia uso de losartana 50\nmg ao dia, mas, ao descobrir a gravidez,\ninterrompeu o uso há três semanas por conta própria.\n\nSobre essa situação, assinale a alternativa correta.","options":{"A":"A substituição da medicação anti-hipertensiva é desnecessária, visto que a losartana pode ser\nutilizada com tranquilidade na gestação.","B":"Essa paciente tem indicação de AAS, que deve ser iniciado com até 16 semanas de gestação.","C":"No primeiro trimestre de gestação, é esperada uma pequena elevação da pressão arterial média\nde todas as gestantes, sendo essa uma resposta fisiológica.","D":"Caso a pressão arterial da paciente esteja acima de 120x70 mmHg, é necessário que seja\nprescrita alguma droga hipotensora de uso permitido na gestação."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-346846","number":"346846","sourceNumber":"346846","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente, 25 anos, primigesta, 28 semanas e 4 dias de gravidez, sem queixas, pré-natal\nem dia e exames normais. Até o momento\nganhou 14kg. No cartão de pré-natal consta glicemia de\njejum de 88mg/dl com 12 semanas. Traz o exame do teste de tolerância oral à glicose realizado há\numa semana, com os seguintes resultados: ? Glicemia de jejum de 97mg/dl. ? Glicemia após 1 hora\nde dextrosol de 183mg/dl. ? Glicemia após 2 horas de dextrosol 2 horas de 150mg/dl. Sobre o\nquadro exposto, é CORRETO afirmar que:","options":{"A":"O teste de tolerância oral à glicose é desnecessário caso a paciente gestante apresente valores\nde glicemia de jejum no primeiro trimestre\ninferiores a 92mg/dL.","B":"O fato de a gestante ser obesa e ter familiares com DM tipo 2 na família obriga à realização de\nteste de tolerância oral à glicose no primeiro trimestre.","C":"A melhor conduta nesse caso é realizar um segundo teste confirmatório, que poderá ser glicemia\nde jejum ou hemoglobina glicosilada.","D":"O diagnóstico da gestante é Diabetes Mellitus Gestacional (DMG) e a conduta inicial é\norientação de dieta e prática de atividades\nfísicas, tendo como base o teste de tolerância oral à\nglicose."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-346848","number":"346848","sourceNumber":"346848","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Paciente 17 anos, primigesta, IG 37 semanas e 2 dias, nega comorbidades. Dá entrada\nna maternidade com PA: 170x120mmHg, queixando\ncefaleia e epigastralgia. Informa\nmovimentação fetal usual, nega perdas vaginais. Solicitado propedêutica HELLP, com resultado\ndentro da normalidade, exceto pela proteinúria positiva. De acordo com o quadro apresentado,\nassinale a MELHOR conduta para essa paciente.","options":{"A":"Internação para controle da pressão com prescrição de metildopa, alta com seguimento\nambulatorial após estabilidade dos níveis pressóricos.","B":"Prescrição de sulfato de magnésio para prevenção de eclampsia, hidralazina EV devido a níveis\npressóricos e internação para parto, com via de parto obstétrica.","C":"Internação para cesariana imediata devido ao risco eminente de óbito fetal.","D":"Informação sobre a normalidade do quadro atual, prescrever anti-hipertensivo e dar alta da\nurgência."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-320429","number":"320429","sourceNumber":"320429","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"Gestante de 16 anos, primigesta, idade gestacional 39 semanas, sem patologias\nprévias, pré-natal sem intercorrências. É admitida\nna emergência apresentando convulsões\ntônico-clônicas generalizadas, pressão arterial 210x130 mmHg e edema generalizado. É\nimediatamente iniciado infusão de sulfato de magnésio e hidralazina endovenoso. Os exames\nlaboratoriais realizados evidenciam 2+ de proteinúria em fita e 87.000 plaquetas/mm³. Assinale a\nalternativa correta sobre a patologia que acomete esta paciente:","options":{"A":"as lesões hepáticas podem ser do tipo hemorragias periportais ou necrose hemorrágica\nperiportal. Embora graves e podendo evoluir para formação de hematoma subcapsular,\nnormalmente não estão associadas a elevação das transaminases.","B":"as alterações circulatórias causadas pela doença não afetam o fluxo uteroplacentário,\npreservando assim o aporte de nutrientes e oxigênio\npara o feto.","C":"o fluxo plasmático renal e a filtração glomerular estão aumentados, resultando no aumento dos\nníveis séricos de ácido úrico, ureia e creatinina.","D":"a pressão arterial é o resultado do débito cardíaco e da resistência vascular periférica. Nesta\npaciente podemos afirmar que o aumento dos níveis pressóricos ocorre devido ao aumento da\nvolemia.","E":"há lesão endotelial associada a aumento da permeabilidade capilar e, portanto, extravasamento\ndo plasma para o meio extravascular gerando\nedema e hemoconcentração."},"answer":"E","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-320431","number":"320431","sourceNumber":"320431","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"?A associação de hiperglicemia e gravidez diferencia principalmente três grupos de\npacientes: (i) aquelas com diabetes mellitus tipos 1 (DM1) e 2 (DM2), com diagnóstico confirmado\nantes da gestação, denominado de DM prévio; (ii) as mulheres com DM diagnosticado na gestação,\nmas com níveis glicêmicos que atingem os critérios da Organização Mundial de Saúde (OMS)\nestabelecidos para o diagnóstico do DM fora da gestação (DM diagnosticado na gestação); e (iii)\naquelas com DM gestacional (DMG) com níveis glicêmicos que não atingem os critérios para o\ndiagnóstico do DM fora da gestação? - Cuidados obstétricos em diabetes mellitus gestacional no\nBrasil [recurso eletrônico] / Ministério da Saúde, Organização Pan-Americana da Saúde, Federação\nBrasileira das Associações de Ginecologia e Obstetrícia, Sociedade Brasileira de Diabetes ?\n\nBrasília : Ministério da Saúde, 2021. Considere uma paciente de 23 anos, primigesta, com 22\nsemanas de idade gestacional, sem\npatologias prévias à gestação que comparece para consulta de\npré-natal na unidade básica de saúde. Ao observar seu cartão de pré- natal observamos uma\nglicemia de jejum realizada na 10ª semana de gestação com resultado de 87 mg/dL. Por tratar-se\nde paciente com sobrepeso, o médico que a acompanha solicitou um TOTG 75g que ela realizou\nna 20ª semana de gestação e apresenta agora para avaliação: jejum = 112 mg/dL; 1hora = 204\nmg/dL; 2 horas = 145 mg/dL. A paciente está assintomática. Avaliando o acima exposto, podemos\nconcluir sobre o diagnóstico dessa paciente:","options":{"A":"trata-se de paciente com diagnóstico de DM diagnosticado na gestação.","B":"trata-se de paciente com diagnóstico de DM prévio.","C":"trata-se de paciente com diagnóstico de DM gestacional (DMG).","D":"trata-se de paciente com avaliação normal quanto à glicemia.","E":"trata-se de paciente que deve realizar novamente o TOTG 75g entre 24 e 28 semanas de\ngestação."},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-335084","number":"335084","sourceNumber":"335084","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As complicações materno-fetais e perinatais são significativamente maiores em\nmulheres portadoras de cardiopatias. A carência\nde protocolos no atendimento da gestante\ncardiopata e a frágil interação multidisciplinar contribuem para o mau desfecho da gravidez. Em\nrelação às complicações fetais e perinatais nas gestações de mães cardiopatas, assinale com V as\nafirmativas verdadeiras e com F as falsas. ( ) A morbimortalidade perinatal é maior em\n\nrecém-nascidos de mães cardiopatas, quando comparada à da população em geral. ( ) Múltiplos\nfatores maternos associam-se a maior incidência\nde perdas fetais, malformações, crescimento\nintrauterino restrito e prematuridade. ( ) A varfarina sódica, quando usada no primeiro trimestre,\ncausa em 5% a 10% das gestantes a síndrome da varfarina fetal, que ocorre entre a sexta e a nona\nsemana de gestação. ( ) Dentre os fatores maternos que comprometem o crescimento e\ndesenvolvimento fetais, pode-se citar baixo débito cardíaco, cardiopatias cianogênicas e uso de\nmedicamentos (anticoagulantes, betabloqueadores, diuréticos, antiarrítmicos). Assinale a sequência\ncorreta.","options":{"A":"F V F F","B":"V F V F","C":"V V V V","D":"F F F V"},"answer":"C","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-334735","number":"334735","sourceNumber":"334735","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A pré-eclâmpsia aumenta os riscos de morte materna e perinatal, sendo responsável\npelo aumento na incidência da prematuridade. Com\nrelação à pré-eclâmpsia, assinale a alternativa\nINCORRETA.","options":{"A":"A pré-eclâmpsia é uma doença progressiva, multissistêmica, caracterizada pelo início de\nhipertensão e proteinúria ou início de\nhipertensão e disfunção significativa de órgãos-alvo, com ou\nsem proteinúria, na última metade da gravidez ou pós-parto.","B":"A hipertensão gestacional verdadeira deve se resolver até o parto. Se persistir pós-parto, o\ndiagnóstico é \"revisado\" para hipertensão crônica que foi mascarada pela diminuição fisiológica da\npressão arterial que ocorre no início da gravidez.","C":"A pré-eclâmpsia é causada por disfunção vascular placentária e materna e se resolve após o\nnascimento em um período de tempo variável.","D":"A síndrome HELLP (hemólise, elevação das enzimas hepáticas, plaquetas baixas),\nprovavelmente representa um tipo de pré-eclâmpsia com características graves."},"answer":"B","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-335086","number":"335086","sourceNumber":"335086","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"As alterações cardiovasculares associadas às síndromes hipertensivas da gravidez\ndependem da gravidade da pré-eclâmpsia, da\nhipertensão e da presença de doença crônica\nsubjacente. Em algumas mulheres, essas alterações cardiovasculares podem preceder o\nsurgimento da hipertensão. Considerando a função ventricular da paciente com pré-eclâmpsia,\nanalise as afirmativas a seguir. I. Apesar da frequência relativamente alta de disfunção diastólica\nna\npré-eclâmpsia, a função cardíaca na maioria das mulheres afetadas é apropriada. II. Tanto\nmulheres grávidas quanto aquelas com síndrome de pré-eclâmpsia podem ter ventrículos normais\nou levemente hiperdinâmicos. III. Tanto mulheres grávidas quanto aquelas com síndrome de\n\npré-eclâmpsia têm um débito cardíaco apropriado para as pressões de enchimento do lado\nesquerdo do coração. IV. As pressões de enchimento dependem do volume de fluidos\nintravenosos. Dessa forma, hidratação agressiva resulta em função ventricular abertamente\nhiperdinâmica. Estão corretas as afirmativas.","options":{"A":"I e II, apenas.","B":"II e III, apenas.","C":"III e IV, apenas.","D":"I, II, III, IV."},"answer":"D","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-4-334738","number":"334738","sourceNumber":"334738","collectionBlock":"medcurso:medcurso-obstetricia-obs-4","collectionLabel":"Medcurso · OBS 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 4","subtopic":"","stem":"A realização do teste oral de tolerância à glicose com 75 g de glicose é considerada um\nteste de triagem de diabetes gestacional em mulheres no pré-natal. Assinale a alternativa que\napresenta o tempo ideal preconizado para a realização desse teste.","options":{"A":"Entre 24 e 28 semanas de gestação.","B":"Entre 18 e 22 semanas de gestação.","C":"Logo no início da gestação.","D":"Seis meses após o parto."},"answer":"A","source":"Obstetricia/OBS 4/OBS 4.txt","sourceLabel":"Medcurso · OBS 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 4","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
